      var iBody = document.createElement("div");
      iBody.className = "_eli3_bd_guided_ctx_body _eli3_bd_guided_ctx_empty";
      iBody.textContent = "No additional context for this question. Choose the option that best fits the agreement.";
      rightBody.appendChild(iBody);
    }
    right.appendChild(rightBody);
    card.appendChild(right);
    bodyEl.appendChild(card);
    _updateProgress();
    // Auto-scroll the right column to the first highlighted OARS row.
    try {
      var firstHit = right.querySelector("._eli3_bd_guided_oars_hit");
      if (firstHit) setTimeout(function () { firstHit.scrollIntoView({ block: "center", behavior: "smooth" }); }, 80);
    } catch (_e) {}
  }

  _renderQuestion();
  // Fire initial progress so the activity feed entry gets created on open
  _saveProgress();
}

// renderTemplateFillForm — Step 2 v3 port of v2 renderTemplateForm (line 6458).
// Lists placeholders with auto-expanding textareas + Locate buttons +
// optional AI Auto-Fill button when AGREEMENT_DATA is loaded.

view.renderTemplateFillForm:
function renderTemplateFillForm(opts) {
  var mount = opts.mount || document.getElementById("_eli3_dashboard_root");
  if (!mount) return;
  var placeholders = opts.placeholders || [];
  // Dedup [[X:FMT]] variants whose bare [[X]] twin is also present in the
  // list — the variant's value is synthesized in _runStep2Apply from the
  // bare's value. Variants without a bare twin survive (their input is
  // still needed) but their label is suffix-stripped by _cleanLabel.
  var _bdParseFmtVariant = function (ph) {
    var s = String(ph || "");
    var outer = s.match(/^(\[\[)(.+)(\]\])$/);
    if (!outer) return null;
    var fmt = null;
    var stripped = outer[2].replace(
      /\s*:\s*(UPPER|LOWER|TITLE)\s*(\||$)/gi,
      function (_, f, tail) { fmt = f.toUpperCase(); return tail; }
    );
    return fmt ? { fmt: fmt, baseKey: outer[1] + stripped + outer[3] } : null;
  };
  // Dedup by group (a "group" = bare key + all its :FMT variants share
  // one). Keep the FIRST appearance per group so the form follows
  // document order — if [[X:UPPER]] appears before [[X]] in the doc,
  // the form shows the variant's input at the variant's position.
  // The dropped peer goes to _bdHiddenVariants and the apply handler
  // re-injects it so init.js synthesis can fill it (in either direction:
  // bare→variant via transform, or variant→bare via raw user input).
  var _bdGroupSeen = {};
  var _bdHiddenVariants = [];
  placeholders = placeholders.filter(function (ph) {
    var v = _bdParseFmtVariant(ph);
    var groupKey = v ? v.baseKey : ph;
    if (_bdGroupSeen[groupKey]) { _bdHiddenVariants.push(ph); return false; }
    _bdGroupSeen[groupKey] = true;
    return true;
  });
  var sourceText = opts.sourceText || "";
  var sourceName = opts.sourceName || null;
  var onAutoFill = opts.onAutoFill || function () {};
  var onApply = opts.onApply || function () {};
  var onLocate = opts.onLocate || function () {};
  var onOarsLookup = opts.onOarsLookup || function () {};
  var onPaymentHelper = opts.onPaymentHelper || function () {};
  var onUpload = opts.onUpload || function () {};
  var onBack = opts.onBack || function () {};
  // 2026-05-27: Email Requester flow. Renders per-card checkboxes after
  // auto-fill marks a field _bd_missing; aggregates checked labels and
  // surfaces a bar above Fill All Fields. Click → onEmailRequester(labels).
  var onEmailRequester = opts.onEmailRequester || function () {};
  var _requester = opts.requester || {};
  var _emailCheckedLabels = new Set();
  var _emailBarEl = null;        // assigned below; updated as user toggles
  function _updateEmailBar() {
    if (!_emailBarEl) return;
    var n = _emailCheckedLabels.size;
    if (n > 0) {
      _emailBarEl.style.display = "";
      var countEl = _emailBarEl.querySelector("._eli3_bd_email_count");
      if (countEl) countEl.textContent = n;
    } else {
      _emailBarEl.style.display = "none";
    }
  }
  // Walk every card after auto-fill / upload completes. Reveal the
  // checkbox for inputs that ended up _bd_missing; hide for filled
  // ones. Also clears any stale checked state from a previous pass.
  function _revealEmailChecksForMissing(rootEl) {
    if (!rootEl) return;
    _emailCheckedLabels.clear();
    rootEl.querySelectorAll("._eli3_bd_fill_field").forEach(function (card) {
      var inp = card.querySelector("._eli3_bd_fill_input");
      var chk = card.querySelector("._eli3_bd_fill_email_chk");
      var chkInp = card.querySelector("._eli3_bd_fill_email_input");
      if (!inp || !chk || !chkInp) return;
      var missing = inp.classList.contains("_bd_missing");
      chk.style.display = missing ? "" : "none";
      if (!missing && chkInp.checked) chkInp.checked = false;
    });
    _updateEmailBar();
  }
  // 2026-05-19: prefill values (from activity restore) + change callback
  // (debounced, used by init.js to keep the activity-feed payload fresh
  // so back/restore round-trips the user's in-progress filling).
  var prefillValues = (opts && opts.prefillValues) || {};
  var onValuesChange = opts.onValuesChange || function () {};

  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }
  function _cleanLabel(ph) {
    var raw = ph.replace(/[\[\]{}]/g, "").replace(/^(\$!|\$|!)/, "");
    // Strip :UPPER/:LOWER/:TITLE format suffix wherever it appears —
    // it's a declarative transform on the value, not a label fragment.
    // Works for plain [[X:FMT]] and the `||` form [[X:FMT || Y]] or
    // [[X || Y:FMT]].
    raw = raw.replace(/\s*:\s*(UPPER|LOWER|TITLE)\s*(\||$)/gi, "$2");
    // 2026-05-22: support optional `ask:` prefix on the right side of
    // `||` to make placeholders self-documenting. Forms accepted:
    //   [[Field]]                        — label + OARS key both = "Field"
    //   [[OARSField || Label]]           — OARS = "OARSField", label = "Label"
    //   [[OARSField || ask:Label]]       — same as above, ask: stripped
    //   [[ask:Label]]                    — label = "Label", OARS = "Label"
    //                                      (ask: stripped; explicit "this is
    //                                      a lawyer-facing question" marker)
    // NO `oars:` prefix — left side is implicitly the OARS key by position.
    if (raw.indexOf("||") !== -1) {
      var parts = raw.split("||");
      var label = parts[1].trim().replace(/^ask\s*:\s*/i, "");
      return { label: label, aiKey: parts[0].trim() };
    }
    var stripped = raw.replace(/^ask\s*:\s*/i, "");
    return { label: stripped, aiKey: stripped };
  }

  mount.innerHTML = "";
  var root = document.createElement("div");
  root.className = "_eli3_bd_root _eli3_bd_fill";
  root.innerHTML =
    '<div class="_eli3_bd_bar">' +
      '<button class="_eli3_bd_back">←</button>' +
      '<div class="_eli3_bd_title">⚡ Auto-Fill Templates</div>' +
      '<div class="_eli3_bd_overview">' + placeholders.length + ' placeholder' + (placeholders.length === 1 ? "" : "s") + '</div>' +
    '</div>';
  root.querySelector("._eli3_bd_back").onclick = onBack;

  if (!placeholders.length) {
    var empty = document.createElement("div");
    empty.className = "_eli3_bd_fill_empty";
    var diag = opts.diag || null;
    var diagHtml = diag
      ? '<div class="_eli3_bd_fill_empty_diag">' +
          '<div class="_eli3_bd_fill_empty_diag_label">Scan result</div>' +
          '<div class="_eli3_bd_fill_empty_diag_val">' + diag.textLen.toLocaleString() + ' characters checked across body, headers, and footers</div>' +
        '</div>'
      : '';
    // 2026-05-20: premium empty-state. Eyebrow + large heading + supporting
    // copy + four example markers in their own card + tip + diag block.
    // Centered hero block, gold accent rail to match the rest of Build
    // Draft's chrome.
    empty.innerHTML =
      '<div class="_eli3_bd_fill_empty_hero">' +
        '<div class="_eli3_bd_fill_empty_icon">📭</div>' +
        '<div class="_eli3_bd_fill_empty_eyebrow">Nothing to fill</div>' +
        '<div class="_eli3_bd_fill_empty_title">No placeholders detected</div>' +
        '<div class="_eli3_bd_fill_empty_desc">' +
          'This document doesn\'t contain any ELI placeholder markers, so Step 2 has nothing to fill. ' +
          'Open a template that uses one of the supported marker syntaxes.' +
        '</div>' +
      '</div>' +
      '<div class="_eli3_bd_fill_empty_markers">' +
        '<div class="_eli3_bd_fill_empty_marker">' +
          '<code>[[Brackets]]</code>' +
          '<span class="_eli3_bd_fill_empty_marker_desc">Standard placeholder</span>' +
        '</div>' +
        '<div class="_eli3_bd_fill_empty_marker">' +
          '<code>$[Total Fee]</code>' +
          '<span class="_eli3_bd_fill_empty_marker_desc">Currency amount</span>' +
        '</div>' +
        '<div class="_eli3_bd_fill_empty_marker">' +
          '<code>$![Total Fee]</code>' +
          '<span class="_eli3_bd_fill_empty_marker_desc">Payment trigger</span>' +
        '</div>' +
        '<div class="_eli3_bd_fill_empty_marker">' +
          '<code>![Schedule]</code>' +
          '<span class="_eli3_bd_fill_empty_marker_desc">Payment schedule candidate</span>' +
        '</div>' +
      '</div>' +
      '<div class="_eli3_bd_fill_empty_tip">' +
        '<span class="_eli3_bd_fill_empty_tip_icon">💡</span>' +
        '<span>Open <b>Templates</b> from the Build Draft hub to load a saved one, or paste a template into the active document.</span>' +
      '</div>' +
      diagHtml;
    root.appendChild(empty);
    mount.appendChild(root);
    return;
  }

  // AGREEMENT data summary + Auto-Fill button if loaded
  if (sourceText) {
    var loadedWrap = document.createElement("div");
    loadedWrap.className = "_eli3_bd_fill_loaded_wrap";
    // 2026-05-27: optional Requester row between LOADED SOURCE label and
    // the filename. Sourced from OARS state's "Requester Name" field via
    // init.js's _extractRequesterName. Hidden when empty.
    var requesterRowHtml = opts.requesterName
      ? '<div class="_eli3_bd_fill_loaded_requester">👤 Requester: <span>' + _esc(opts.requesterName) + '</span></div>'
      : "";
    loadedWrap.innerHTML =
      '<div class="_eli3_bd_fill_loaded">' +
        '<div class="_eli3_bd_fill_loaded_main">' +
          '<div class="_eli3_bd_fill_loaded_label">LOADED SOURCE</div>' +
          requesterRowHtml +
          '<div class="_eli3_bd_fill_loaded_name">📄 ' + _esc(sourceName || "OARS data") + '</div>' +
        '</div>' +
        '<button class="_eli3_bd_fill_autofill_btn">' +
          '<span class="_eli3_bd_fill_autofill_icon">⚡</span>' +
          '<span class="_eli3_bd_fill_autofill_label">AUTO-FILL</span>' +
        '</button>' +
      '</div>' +
      '<div class="_eli3_bd_fill_status" hidden></div>';
    root.appendChild(loadedWrap);
    var autoBtn = loadedWrap.querySelector("._eli3_bd_fill_autofill_btn");
    var btnLabel = loadedWrap.querySelector("._eli3_bd_fill_autofill_label");
    var btnIcon  = loadedWrap.querySelector("._eli3_bd_fill_autofill_icon");
    var status = loadedWrap.querySelector("._eli3_bd_fill_status");
    autoBtn.onclick = function () {
      autoBtn.disabled = true;
      autoBtn.classList.add("_eli3_bd_fill_autofill_btn_filling");
      btnIcon.textContent = "⏳";
      btnLabel.textContent = "Filling…";
      status.hidden = false;
      status.textContent = "Analyzing data…";
      onAutoFill(placeholders, function (mapping, err) {
        autoBtn.disabled = false;
        autoBtn.classList.remove("_eli3_bd_fill_autofill_btn_filling");
        btnIcon.textContent = "⚡";
        btnLabel.textContent = "AUTO-FILL";
        if (err) { status.textContent = "❌ " + (err.message || "Error"); return; }
        var inputs = root.querySelectorAll("._eli3_bd_fill_input");
        var filled = 0;
        inputs.forEach(function (inp) {
          var v = mapping[inp.dataset.target] || mapping[inp.dataset.aiKey];
          inp.classList.remove("_bd_filled", "_bd_missing");
          if (v) {
            inp.value = v;
            inp.classList.add("_bd_filled");
            filled++;
            inp.style.height = "auto";
            inp.style.height = inp.scrollHeight + "px";
          } else {
            inp.classList.add("_bd_missing");
          }
        });
        // 2026-05-27: reveal Email Requester checkboxes for missing inputs.
        _revealEmailChecksForMissing(root);
        var missing = inputs.length - filled;
        status.textContent = "✅ Filled " + filled + " · ❌ Missing " + missing;
      });
    };
  } else {
    // No source loaded — drop-zone for .docx/.txt/.csv/.json
    var dropZone = document.createElement("div");
    dropZone.className = "_eli3_bd_fill_drop";
    dropZone.innerHTML =
      '<div class="_eli3_bd_fill_drop_icon">📂</div>' +
      '<div class="_eli3_bd_fill_drop_title">Import Data Source</div>' +
      '<div class="_eli3_bd_fill_drop_desc">Click to upload (.docx, .txt, .csv, .json)</div>';
