    fileInput.type = "file";
    fileInput.accept = ".docx,.txt,.csv,.json,application/pdf";
    fileInput.style.display = "none";
    dropZone.onclick = function () { fileInput.click(); };
    fileInput.onchange = function (e) {
      var f = e.target.files && e.target.files[0];
      if (!f) return;
      dropZone.innerHTML =
        '<div class="_eli3_bd_fill_drop_icon">⏳</div>' +
        '<div class="_eli3_bd_fill_drop_title">Reading ' + _esc(f.name) + '…</div>';
      onUpload(f, placeholders, function (mapping, err) {
        if (err) {
          dropZone.innerHTML =
            '<div class="_eli3_bd_fill_drop_icon">❌</div>' +
            '<div class="_eli3_bd_fill_drop_title">' + _esc(err.message || "Error") + '</div>';
          return;
        }
        var inputs = root.querySelectorAll("._eli3_bd_fill_input");
        var filled = 0;
        inputs.forEach(function (inp) {
          var v = mapping[inp.dataset.target] || mapping[inp.dataset.aiKey];
          inp.classList.remove("_bd_filled", "_bd_missing");
          if (v) {
            inp.value = v;
            inp.classList.add("_bd_filled");
            filled++;
            inp.style.height = "auto";
            inp.style.height = inp.scrollHeight + "px";
          } else {
            inp.classList.add("_bd_missing");
          }
        });
        // 2026-05-27: reveal Email Requester checkboxes for missing inputs.
        _revealEmailChecksForMissing(root);
        dropZone.innerHTML =
          '<div class="_eli3_bd_fill_drop_icon">✅</div>' +
          '<div class="_eli3_bd_fill_drop_title">Filled ' + filled + ' / ' + inputs.length + ' fields</div>';
      });
    };
    root.appendChild(dropZone);
    root.appendChild(fileInput);
  }

  // Per-placeholder fill rows
  var formContainer = document.createElement("div");
  formContainer.className = "_eli3_bd_fill_form";
  // 2026-05-19: debounce helper for onValuesChange so we don't fire
  // a full state-snapshot on every keystroke.
  var _changeTimer = null;
  function _emitChange() {
    if (_changeTimer) clearTimeout(_changeTimer);
    _changeTimer = setTimeout(function () {
      _changeTimer = null;
      try {
        var values = {};
        formContainer.querySelectorAll("._eli3_bd_fill_input").forEach(function (inp) {
          values[inp.dataset.target] = inp.value;
        });
        onValuesChange(values);
      } catch (_e) {}
    }, 400);
  }
  // 2026-05-20: payment helper detection — ONLY ![[ placeholders.
  // Narrower than the prior "any payment-keyword label" gate — the
  // helper is tied to the specific ![[…]] payment-schedule-candidate
  // marker convention. [[Payment Terms]] etc. won't trigger it.
  function _isPaymentPlaceholder(ph) {
    return /^!\[\[/.test(String(ph || ""));
  }
  placeholders.forEach(function (ph) {
    var ck = _cleanLabel(ph);
    var isPayment = _isPaymentPlaceholder(ph);
    var wrap = document.createElement("div");
    wrap.className = "_eli3_bd_fill_field" + (isPayment ? " _eli3_bd_fill_field_payment" : "");
    // 2026-05-22: locate button collapsed to a single 📍 pin icon and
    // moved inline with the label text (right after the label). Reads
    // as "this label's locator" — single icon, no extra row footprint.
    // Payment Helper + OARS sit in the right-side button group. Payment
    // Helper is rendered before OARS so it anchors immediately to the
    // left of the OARS button.
    wrap.innerHTML =
      '<label class="_eli3_bd_fill_label">' +
        '<span class="_eli3_bd_fill_label_text">' +
          '<span>' + _esc(ck.label) + '</span>' +
          '<button class="_eli3_bd_fill_locate" type="button" title="Scroll the Word document to this placeholder">📍</button>' +
          // 2026-05-27: Email Requester checkbox. Hidden by default;
          // revealed in the auto-fill response handler for inputs that
          // ended up _bd_missing. Toggling updates the floating Email
          // Requester bar above Fill All Fields.
          '<label class="_eli3_bd_fill_email_chk" title="Include this field in an email to the OARS requester" style="display:none;">' +
            '<input type="checkbox" class="_eli3_bd_fill_email_input" />' +
            '<span class="_eli3_bd_fill_email_chk_text">EMAIL REQUESTER</span>' +
          '</label>' +
        '</span>' +
        '<span class="_eli3_bd_fill_label_btns">' +
          (isPayment
            ? '<button class="_eli3_bd_fill_payment" type="button" title="Open the payment schedule helper to build the due-as-follows string before applying — the dialog won\'t pop up later if this field is filled.">💰 PAYMENT HELPER</button>'
            : "") +
          '<button class="_eli3_bd_fill_oars" type="button" title="Open the processed OARS data viewer and jump to the field that matches this placeholder">🔎 OARS</button>' +
        '</span>' +
      '</label>';
    var inp = document.createElement("textarea");
    inp.className = "_eli3_bd_fill_input";
    inp.dataset.target = ph;
    inp.dataset.aiKey = ck.aiKey;
    inp.placeholder = "Enter " + ck.label;
    inp.rows = 1;
    // 2026-05-19: pre-populate value from prefillValues (activity-feed
    // restore). Lookup by full placeholder OR by aiKey so saved values
    // round-trip regardless of which form the placeholder was stored as.
    var pre = (prefillValues[ph] != null ? prefillValues[ph] : prefillValues[ck.aiKey]);
    if (pre != null && pre !== "") {
      inp.value = String(pre);
      inp.classList.add("_bd_filled");
    }
    inp.addEventListener("input", function () {
      this.style.height = "auto";
      this.style.height = this.scrollHeight + "px";
      // Live filled/empty visual state — green left-bar when non-empty,
      // base when cleared. Removes the gap where the user typed but
      // didn't yet submit, so the "is this filled?" signal is instant.
      if (this.value && this.value.trim()) {
        this.classList.add("_bd_filled");
        this.classList.remove("_bd_missing");
      } else {
        this.classList.remove("_bd_filled");
      }
      _emitChange();
    });
    wrap.appendChild(inp);
    var locBtn = wrap.querySelector("._eli3_bd_fill_locate");
    locBtn.onclick = function () { onLocate(ph, inp.value); };
    var oarsBtn = wrap.querySelector("._eli3_bd_fill_oars");
    if (oarsBtn) oarsBtn.onclick = function () { onOarsLookup(ph, ck.aiKey, ck.label); };
    var payBtn = wrap.querySelector("._eli3_bd_fill_payment");
    if (payBtn) payBtn.onclick = function () {
      onPaymentHelper(ph, ck.label, inp.value, function (formattedString) {
        if (formattedString == null) return;
        inp.value = formattedString;
        inp.classList.add("_bd_filled");
        inp.classList.remove("_bd_missing");
        inp.style.height = "auto";
        inp.style.height = inp.scrollHeight + "px";
        _emitChange();
      });
    };
    // 2026-05-27: Email Requester checkbox wiring. Closure over ck.label
    // so the bar aggregates by display label (what the email body lists).
    var emailChkInput = wrap.querySelector("._eli3_bd_fill_email_input");
    if (emailChkInput) {
      emailChkInput.addEventListener("change", function (e) {
        if (e.target.checked) _emailCheckedLabels.add(ck.label);
        else _emailCheckedLabels.delete(ck.label);
        _updateEmailBar();
      });
    }
    // If the input goes from missing → filled (via typing), uncheck +
    // hide its email checkbox automatically — no need to email about a
    // field that's no longer missing.
    inp.addEventListener("input", function () {
      var chk = wrap.querySelector("._eli3_bd_fill_email_chk");
      var chkInp = wrap.querySelector("._eli3_bd_fill_email_input");
      if (!chk || !chkInp) return;
      if (inp.value && inp.value.trim()) {
        chk.style.display = "none";
        if (chkInp.checked) {
          chkInp.checked = false;
          _emailCheckedLabels.delete(ck.label);
          _updateEmailBar();
        }
      }
    });
    formContainer.appendChild(wrap);
  });
  root.appendChild(formContainer);
  // 2026-05-19: after first paint, auto-fit any prefilled textarea's
  // height and emit one initial change so the activity entry's payload
  // reflects what's currently on screen.
  setTimeout(function () {
    formContainer.querySelectorAll("._eli3_bd_fill_input").forEach(function (inp) {
      if (inp.value) {
        inp.style.height = "auto";
        inp.style.height = inp.scrollHeight + "px";
      }
    });
  }, 0);

  var actions = document.createElement("div");
  actions.className = "_eli3_bd_logic_actions";

  // 2026-05-27: Email Requester bar — sits above FILL ALL FIELDS.
  // Hidden by default; revealed when at least one per-card EMAIL
  // REQUESTER checkbox is checked. Click → onEmailRequester(labels).
  _emailBarEl = document.createElement("div");
  _emailBarEl.className = "_eli3_bd_email_bar";
  _emailBarEl.style.display = "none";
  _emailBarEl.innerHTML =
    '<button class="_eli3_bd_email_btn" type="button" title="Open a draft email to the OARS requester asking about the checked missing fields">' +
      '<span class="_eli3_bd_email_btn_icon">✉️</span>' +
      '<span class="_eli3_bd_email_btn_label">Email Requester (<span class="_eli3_bd_email_count">0</span>)</span>' +
    '</button>';
  _emailBarEl.querySelector("._eli3_bd_email_btn").onclick = function () {
    onEmailRequester(Array.from(_emailCheckedLabels));
  };
  actions.appendChild(_emailBarEl);

  var apply = document.createElement("button");
  apply.className = "_eli3_bd_run_all";
  apply.innerHTML = "FILL ALL FIELDS";
  apply.onclick = function () {
    var values = {};
    var missing = [];
    formContainer.querySelectorAll("._eli3_bd_fill_input").forEach(function (inp) {
      var v = inp.value;
      values[inp.dataset.target] = v;
      inp.classList.remove("_bd_filled", "_bd_missing");
      if (!v || !String(v).trim()) {
        inp.classList.add("_bd_missing");
        var lbl = inp.dataset.aiKey || inp.dataset.target;
        missing.push(_esc(lbl));
      }
    });
    // Re-inject hidden [[KEY:FMT]] variants as empty entries so init.js
    // synthesis can populate them from the bare [[KEY]] value. Without
    // this, the variant placeholder in the doc never gets resolved.
    _bdHiddenVariants.forEach(function (ph) {
      if (values[ph] == null) values[ph] = "";
    });
    // FROM v2 applyTemplateValues missing-fields warning (line 6960).
    // Skip dialog if no missing or showEliDialog isn't loaded.
    if (missing.length && typeof showEliDialog === "function") {
      showEliDialog({
        variant: "warning",
        tier: "premium",
        icon: "⚠️",
        title: "Missing Fields",
        body:
          '<div style="font:500 12px/1.5 \'Inter\',sans-serif;color:#475569;margin-bottom:8px;">' +
            'These ' + missing.length + ' field' + (missing.length === 1 ? '' : 's') + ' are empty:' +
          '</div>' +
          '<div style="max-height:180px;overflow-y:auto;padding:8px 12px;background:#fef3c7;border-left:3px solid #f59e0b;font:600 12px/1.6 \'Inter\',sans-serif;color:#78350f;">' +
            missing.join("<br>") +
          '</div>',
        primary: {
          label: "I'll Fix Them",
          onclick: function () {
            var firstMissing = formContainer.querySelector("._eli3_bd_fill_input._bd_missing");
            if (firstMissing) {
              firstMissing.scrollIntoView({ behavior: "smooth", block: "center" });
              try { firstMissing.focus(); } catch (e) {}
            }
          },
        },
        secondary: {
          label: "Skip & Fill",
          onclick: function () { onApply(values); },
        },
      });
      return;
    }
    onApply(values);
  };
  actions.appendChild(apply);
  root.appendChild(actions);

  mount.appendChild(root);
}

// renderGuidedFillForm — Step 2 guided mode. One field at a time with
// auto-fill-first, OARS data in the right column, Payment Helper inline,
// and Email Requester for missing fields. Same opts as renderTemplateFillForm
// plus oarsFields, oarsTablesData, onProgress.

view.renderGuidedFillForm:
function renderGuidedFillForm(opts) {
  var mount = opts.mount || document.getElementById("_eli3_dashboard_root");
  if (!mount) return;
  var placeholders = opts.placeholders || [];
  // Dedup format variants (same logic as renderTemplateFillForm)
  var _bdParseFmtVariant = function (ph) {
    var s = String(ph || "");
    var outer = s.match(/^(\[\[)(.+)(\]\])$/);
    if (!outer) return null;
    var fmt = null;
    var stripped = outer[2].replace(/\s*:\s*(UPPER|LOWER|TITLE)\s*(\||$)/gi, function (_, f, tail) { fmt = f.toUpperCase(); return tail; });
    return fmt ? { fmt: fmt, baseKey: outer[1] + stripped + outer[3] } : null;
  };
  var _bdGroupSeen = {};
  var _bdHiddenVariants = [];
  placeholders = placeholders.filter(function (ph) {
    var v = _bdParseFmtVariant(ph);
    var groupKey = v ? v.baseKey : ph;
    if (_bdGroupSeen[groupKey]) { _bdHiddenVariants.push(ph); return false; }
    _bdGroupSeen[groupKey] = true;
    return true;
  });
  var onAutoFill = opts.onAutoFill || function () {};
  var onApply = opts.onApply || function () {};
  var onLocate = opts.onLocate || function () {};
  var onPaymentHelper = opts.onPaymentHelper || function () {};
  var onBack = opts.onBack || function () {};
  var onEmailRequester = opts.onEmailRequester || function () {};
  var onProgress = opts.onProgress || function () {};
  var onValuesChange = opts.onValuesChange || function () {};
  var docText = opts.docText || "";
  var oarsFields = opts.oarsFields || {};

  // Find all occurrences of a placeholder in docText, return context snippets
  function _findOccurrences(ph) {
    if (!docText) return [];
    var hits = [];
    var idx = 0;
    while (true) {
      var pos = docText.indexOf(ph, idx);
      if (pos === -1) break;
      // Extract ~40 chars before and after for context
      var before = docText.substring(Math.max(0, pos - 40), pos);
      var after = docText.substring(pos + ph.length, Math.min(docText.length, pos + ph.length + 40));
      // Trim to word boundaries
      var bTrim = before.indexOf(" ") !== -1 ? before.substring(before.indexOf(" ") + 1) : before;
      var aTrim = after.lastIndexOf(" ") !== -1 ? after.substring(0, after.lastIndexOf(" ")) : after;
      hits.push({ before: bTrim, after: aTrim, pos: pos });
      idx = pos + ph.length;
    }
    return hits;
  }
  var oarsTablesData = opts.oarsTablesData || [];
  var sourceText = opts.sourceText || "";
  var prefillValues = (opts && opts.prefillValues) || {};

  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }
  function _cleanLabel(ph) {
    // Extract | lookup:X and | ai:X pipes BEFORE stripping brackets
    // so {references} in ai: prompts survive
    var lookup = null, aiHint = null;
    var raw = ph;
    raw = raw.replace(/\s*\|\s*lookup\s*:\s*([^|\]]+)/gi, function (_, v) { lookup = v.trim(); return ""; });
    raw = raw.replace(/\s*\|\s*ai\s*:\s*([^|\]]+)/gi, function (_, v) { aiHint = v.trim(); return ""; });
    raw = raw.replace(/[\[\]]/g, "").replace(/^(\$!|\$|!)/, "");
    raw = raw.replace(/\s*:\s*(UPPER|LOWER|TITLE)\s*(\||$)/gi, "$2");
    raw = raw.trim();
    var out;
    if (raw.indexOf("||") !== -1) {
      var parts = raw.split("||");
      out = { label: parts[1].trim().replace(/^ask\s*:\s*/i, ""), aiKey: parts[0].trim() };
    } else {
      out = { label: raw.replace(/^ask\s*:\s*/i, ""), aiKey: raw.replace(/^ask\s*:\s*/i, "") };
    }
    if (lookup) out.lookup = lookup;
    if (aiHint) out.aiHint = aiHint;
    return out;
  }
  function _isPaymentPlaceholder(ph) { return /^!\[\[/.test(String(ph || "")); }

  // State
  var values = {};
  var _startIdx = (opts.startIdx && typeof opts.startIdx === "number") ? opts.startIdx : 0;
  var currentIdx = _startIdx;
  var autoFillDone = false;
  var autoFillMapping = {};
  var _gfEmailLabels = new Set();
  placeholders.forEach(function (ph) {
    var pre = prefillValues[ph] != null ? prefillValues[ph] : prefillValues[_cleanLabel(ph).aiKey];
    values[ph] = (pre != null && pre !== "") ? String(pre) : "";
  });

  // Render OARS tables (reused from guided logic form)
  function _renderOarsTables() {
    if (!oarsTablesData.length) return '<div class="_eli3_bd_guided_ctx_empty">No OARS data available.</div>';
    return oarsTablesData.map(function (tbl) {
      if (!tbl || !tbl.length) return "";
      var hdr = tbl[0] || [];
      var html = '<table class="_eli3_bd_guided_oars_tbl"><thead><tr>' +
        hdr.map(function (h) { return '<th class="_eli3_bd_guided_oars_tbl_th">' + _esc(h) + '</th>'; }).join("") +
        '</tr></thead><tbody>';
      for (var r = 1; r < tbl.length; r++) {
        var row = tbl[r] || [];
        var empty = row.every(function (c) { return !c || !String(c).trim(); });
        html += '<tr>' + row.map(function (c) {
          return '<td class="_eli3_bd_guided_oars_tbl_td' + (empty ? ' _eli3_bd_guided_oars_tbl_empty' : '') + '">' + _esc(c) + '</td>';
        }).join("") + '</tr>';
      }
      html += '</tbody></table>';
      return html;
    }).join("");
  }

  mount.innerHTML = "";
  var root = document.createElement("div");
  root.className = "_eli3_bd_guided_root";

  // Header bar
  root.innerHTML =
    '<div class="_eli3_bd_guided_header">' +
      '<button class="_eli3_bd_guided_back" title="Back to hub">←</button>' +
      '<div class="_eli3_bd_guided_header_text">' +
        '<div class="_eli3_bd_guided_eyebrow">GUIDED FILL</div>' +
        '<div class="_eli3_bd_guided_title">⚡ Fill Placeholders</div>' +
      '</div>' +
    '</div>' +
    '<div class="_eli3_bd_guided_body" id="_eli3_bd_guided_fill_body"></div>';
  root.querySelector("._eli3_bd_guided_back").onclick = onBack;
  mount.appendChild(root);
  var bodyEl = root.querySelector("#_eli3_bd_guided_fill_body");

  function _filledCount() {
    var n = 0;
    placeholders.forEach(function (ph) { if (values[ph] && String(values[ph]).trim()) n++; });
    return n;
  }
  function _updateProgress() {
    var filled = _filledCount();
    var pct = placeholders.length ? Math.round((filled / placeholders.length) * 100) : 0;
    var fillEl = bodyEl.querySelector("#_eli3_bd_gf_fill");
    var plabelEl = bodyEl.querySelector("#_eli3_bd_gf_plabel");
    if (fillEl) fillEl.style.width = pct + "%";
    if (plabelEl) plabelEl.textContent = filled + " of " + placeholders.length + " filled";
  }
  function _emitProgress() {
    var filled = _filledCount();
    var curPh = currentIdx < placeholders.length ? placeholders[currentIdx] : null;
    var curLabel = curPh ? _cleanLabel(curPh).label : null;
    onProgress({ filled: filled, total: placeholders.length, currentIdx: currentIdx, currentKey: curLabel });
  }
  function _emitChange() {
    try { onValuesChange(Object.assign({}, values)); } catch (_e) {}
  }

  function _renderField() {
    // Generate/apply screen — past all fields
    if (currentIdx >= placeholders.length) {
      bodyEl.innerHTML = "";
      var card = document.createElement("div");
      card.className = "_eli3_bd_guided_card";
      var left = document.createElement("div");
      left.className = "_eli3_bd_guided_left";
      var leftContent = document.createElement("div");
      leftContent.className = "_eli3_bd_guided_left_content";
      leftContent.style.cssText = "display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;gap:18px;padding:32px 24px;";
      var filled = _filledCount();
      var missing = placeholders.length - filled;
      var statusIcon = document.createElement("div");
      statusIcon.style.cssText = "font-size:48px;line-height:1;";
      statusIcon.textContent = missing === 0 ? "✅" : "⚠️";
      leftContent.appendChild(statusIcon);
      var statusTitle = document.createElement("div");
      statusTitle.style.cssText = "font-size:18px;font-weight:700;color:#1e293b;letter-spacing:-.3px;";
      statusTitle.textContent = missing === 0 ? "All Fields Filled" : filled + " of " + placeholders.length + " Filled";
      leftContent.appendChild(statusTitle);
      var statusSub = document.createElement("div");
      statusSub.style.cssText = "font-size:13px;color:#64748b;max-width:280px;line-height:1.5;";
      statusSub.textContent = missing === 0
        ? "Ready to apply all values to the document."
        : missing + " field" + (missing === 1 ? " is" : "s are") + " empty. You can still apply — empty fields will be skipped.";
      leftContent.appendChild(statusSub);
      var applyBtn = document.createElement("button");
      applyBtn.type = "button";
      applyBtn.style.cssText = "margin-top:12px;padding:14px 36px;border:none;border-radius:10px;background:linear-gradient(135deg,#c9a227 0%,#dbb846 100%);color:#fff;font-size:15px;font-weight:700;letter-spacing:.3px;cursor:pointer;box-shadow:0 2px 8px rgba(201,162,39,.35);transition:filter .15s;";
      applyBtn.textContent = "⚡ Fill All Fields";
      applyBtn.onmouseover = function () { applyBtn.style.filter = "brightness(1.08)"; };
      applyBtn.onmouseout = function () { applyBtn.style.filter = ""; };
      applyBtn.onclick = function () {
        _bdHiddenVariants.forEach(function (ph) { if (values[ph] == null) values[ph] = ""; });
        onApply(values);
      };
      leftContent.appendChild(applyBtn);
      left.appendChild(leftContent);
      // Nav
      var nav = document.createElement("div");
      nav.className = "_eli3_bd_guided_nav";
      var backBtn = document.createElement("button");
      backBtn.type = "button";
      backBtn.className = "_eli3_bd_guided_nav_btn _eli3_bd_guided_nav_prev";
      backBtn.textContent = "← Back";
      backBtn.onclick = function () { currentIdx = placeholders.length - 1; _renderField(); };
      nav.appendChild(backBtn);
      left.appendChild(nav);
      // Progress
      var progWrap = document.createElement("div");
      progWrap.className = "_eli3_bd_guided_progress_bar";
      var pct = placeholders.length ? Math.round((_filledCount() / placeholders.length) * 100) : 100;
      progWrap.innerHTML =
        '<div class="_eli3_bd_guided_progress_fill" id="_eli3_bd_gf_fill" style="width:' + pct + '%"></div>' +
        '<div class="_eli3_bd_guided_progress_label" id="_eli3_bd_gf_plabel">' + _filledCount() + ' of ' + placeholders.length + ' filled</div>';
      left.appendChild(progWrap);
      card.appendChild(left);
      // Right — summary
      var right = document.createElement("div");
      right.className = "_eli3_bd_guided_right";
      var colHeader = document.createElement("div");
      colHeader.className = "_eli3_bd_guided_col_header";
      colHeader.innerHTML = '<span class="_eli3_bd_guided_col_icon">📋</span><span>YOUR VALUES</span>';
      right.appendChild(colHeader);
      var rightBody = document.createElement("div");
      rightBody.className = "_eli3_bd_guided_right_body";
      var summaryHtml = '<div style="padding:12px 16px;display:flex;flex-direction:column;gap:8px;">';
      placeholders.forEach(function (ph, i) {
        var ck = _cleanLabel(ph);
        var val = values[ph] || "(empty)";
        var isFilled = values[ph] && String(values[ph]).trim();
        summaryHtml +=
          '<div style="display:flex;align-items:baseline;gap:8px;padding:6px 10px;border-radius:6px;background:' + (isFilled ? '#f8fafc' : '#fefce8') + ';border:1px solid ' + (isFilled ? '#e2e8f0' : '#fde68a') + ';cursor:pointer;" data-goto="' + i + '">' +
          '<span style="font-size:10px;font-weight:700;color:#94a3b8;min-width:20px;">' + (i + 1) + '</span>' +
          '<span style="font-size:12px;font-weight:600;color:#334155;flex:1;">' + _esc(ck.label) + '</span>' +
          '<span style="font-size:11px;color:' + (isFilled ? '#16a34a' : '#92400e') + ';font-weight:500;max-width:140px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">' + _esc(val) + '</span>' +
          '</div>';
      });
      summaryHtml += '</div>';
      rightBody.innerHTML = summaryHtml;
      rightBody.querySelectorAll("[data-goto]").forEach(function (row) {
        row.onclick = function () { currentIdx = parseInt(row.getAttribute("data-goto"), 10); _renderField(); };
      });
      right.appendChild(rightBody);
      card.appendChild(right);
      bodyEl.appendChild(card);
      return;
    }

    if (currentIdx < 0) currentIdx = 0;
    var ph = placeholders[currentIdx];
    var ck = _cleanLabel(ph);
    var isPayment = _isPaymentPlaceholder(ph);
    var isMissing = !values[ph] || !String(values[ph]).trim();
    var isFirst = currentIdx === 0;
    var isLast = currentIdx === placeholders.length - 1;

    bodyEl.innerHTML = "";
    var card = document.createElement("div");
    card.className = "_eli3_bd_guided_card";

    // Left column
    var left = document.createElement("div");
    left.className = "_eli3_bd_guided_left";
    var leftContent = document.createElement("div");
    leftContent.className = "_eli3_bd_guided_left_content";
    var qNum = document.createElement("div");
    qNum.className = "_eli3_bd_guided_qnum";
    qNum.textContent = "Field " + (currentIdx + 1) + " of " + placeholders.length;
    leftContent.appendChild(qNum);
    var qTitle = document.createElement("div");
    qTitle.className = "_eli3_bd_guided_qtitle";
    qTitle.textContent = ck.label;
    leftContent.appendChild(qTitle);

    // Status chip
    if (autoFillDone) {
      var chip = document.createElement("div");
      chip.style.cssText = "display:inline-flex;align-items:center;gap:4px;padding:3px 10px;border-radius:10px;font:600 10px/1 Inter,sans-serif;margin-bottom:4px;";
      if (isMissing) {
        chip.style.background = "#fef3c7"; chip.style.color = "#92400e";
        chip.textContent = "⚠️ Not found in OARS data";
      } else {
        chip.style.background = "#f0fdf4"; chip.style.color = "#16a34a";
        chip.textContent = "✅ Auto-filled from OARS data";
      }
      leftContent.appendChild(chip);
    }

    // Occurrence count + arrows (only if more than 1)
    var hits = _findOccurrences(ph);
    if (hits.length > 1) {
      var _snippetIdx = 0;
      var occBox = document.createElement("div");
      occBox.style.cssText = "display:inline-flex;align-items:center;gap:6px;padding:3px 10px;border-radius:10px;background:#f0f9ff;border:1px solid #bae6fd;font:600 10px/1 Inter,sans-serif;color:#0c4a6e;margin-bottom:4px;";
      function _renderOccNav() {
        occBox.innerHTML =
          'appears ' + hits.length + '× ' +
          '<button type="button" class="_gf_snip_prev" style="border:none;background:none;color:#0c4a6e;font-size:12px;cursor:pointer;padding:0 2px;">←</button>' +
          '<span>' + (_snippetIdx + 1) + '/' + hits.length + '</span>' +
          '<button type="button" class="_gf_snip_next" style="border:none;background:none;color:#0c4a6e;font-size:12px;cursor:pointer;padding:0 2px;">→</button>';
        occBox.querySelector("._gf_snip_prev").onclick = function () { _snippetIdx = (_snippetIdx - 1 + hits.length) % hits.length; _renderOccNav(); onLocate(ph, inp.value); };
        occBox.querySelector("._gf_snip_next").onclick = function () { _snippetIdx = (_snippetIdx + 1) % hits.length; _renderOccNav(); onLocate(ph, inp.value); };
      }
      _renderOccNav();
      leftContent.appendChild(occBox);
    }

    // Textarea input — with currency prefix for $![[...]] and $[[...]] fields
    var isCurrency = /^\$!?\[\[/.test(String(ph || ""));
    var inp = document.createElement("textarea");
    inp.className = "_eli3_bd_guided_text_input";
    inp.value = values[ph] || "";
    inp.placeholder = "Enter " + ck.label;
    if (isCurrency) inp.style.paddingLeft = "28px";
    inp.oninput = function () {
      values[ph] = inp.value;
      _updateProgress();
      _emitChange();
    };
    if (isCurrency) {
      var currWrap = document.createElement("div");
      currWrap.style.cssText = "position:relative;";
      var currLabel = document.createElement("span");
      currLabel.style.cssText = "position:absolute;left:10px;top:14px;font:700 14px/1 Georgia,serif;color:#c9a227;z-index:1;pointer-events:none;";
      currLabel.textContent = "$";
      currWrap.appendChild(currLabel);
      currWrap.appendChild(inp);
      leftContent.appendChild(currWrap);
    } else {
      leftContent.appendChild(inp);
    }

    // Action row: Ask ELI lookup + Email Requester checkbox
    var actRow = document.createElement("div");
    actRow.style.cssText = "display:flex;gap:8px;flex-wrap:wrap;margin-top:4px;align-items:center;";
    if (ck.aiHint) {
      // Resolve the prompt with {references} interpolated
      var _resolvedPrompt = ck.aiHint.replace(/\{([^}]+)\}/g, function (_, ref) {
        var found = "";
        var refL = ref.trim().toLowerCase();
        placeholders.forEach(function (p) {
          var c = _cleanLabel(p);
          if (c.label.toLowerCase() === refL || c.aiKey.toLowerCase() === refL) {
            if (values[p] && String(values[p]).trim()) found = values[p];
          }
        });
        if (!found) {
          Object.keys(oarsFields).forEach(function (k) {
            if (!found && k.toLowerCase().indexOf(refL) !== -1 && oarsFields[k]) found = String(oarsFields[k]).trim();
          });
        }
        return found || ref;
      });
      var aiBtn = document.createElement("button");
      aiBtn.type = "button";
      aiBtn.className = "_eli3_bd_guided_ask_eli_btn";
      var _displayPrompt = _resolvedPrompt.replace(/\s*[.\s]*format\s*:.*$/i, "").trim();
      aiBtn.textContent = "💬 Ask ELI: " + _displayPrompt;
      aiBtn.title = _resolvedPrompt;
      // Result container — shown inline below the button after AI responds
      var aiResultBox = document.createElement("div");
      aiResultBox.style.cssText = "display:none;margin-top:6px;padding:10px 14px;background:#f0fdf4;border:1px solid #86efac;border-radius:8px;font:500 13px/1.5 Inter,sans-serif;color:#166534;";
      aiBtn.onclick = function () {
        aiBtn.disabled = true;
        aiBtn.textContent = "⏳ Asking ELI…";
        aiResultBox.style.display = "block";
        aiResultBox.innerHTML = '<span style="color:#94a3b8;font-size:12px;">Thinking…</span>';
        var sysPrompt = "You are a legal research assistant. Answer using your general knowledge about companies, jurisdictions, and entity types. Do NOT reference any document. Give a short, direct answer.";
        try {
          eli.ai.complete(sysPrompt + "\n\nQuestion: " + _resolvedPrompt, { maxTokens: 200 }).then(function (answer) {
            aiBtn.disabled = false;
            aiBtn.textContent = "💬 Ask ELI: " + _displayPrompt;
            var ans = String(answer || "").trim();
            aiResultBox.innerHTML =
              '<div style="font:700 9px/1 Inter,sans-serif;color:#16a34a;letter-spacing:.1em;margin-bottom:4px;">AI ANSWER</div>' +
              '<div>' + _esc(ans) + '</div>' +
              '<button type="button" style="margin-top:8px;padding:5px 14px;border:1px solid #22c55e;border-radius:6px;background:#f0fdf4;color:#166534;font:600 11px/1 Inter,sans-serif;cursor:pointer;">✓ Use This Answer</button>';
            aiResultBox.querySelector("button").onclick = function () {
              inp.value = ans;
              values[ph] = ans;
              _updateProgress();
              _emitChange();
              aiResultBox.style.display = "none";
            };
          }).catch(function (err) {
            aiBtn.disabled = false;
            aiBtn.textContent = "💬 Retry";
            aiResultBox.innerHTML = '<span style="color:#b91c1c;font-size:12px;">Error: ' + _esc(err && err.message || "unknown") + '</span>';
          });
        } catch (_e) {
          aiBtn.disabled = false;
          aiBtn.textContent = "💬 Retry";
          aiResultBox.innerHTML = '<span style="color:#b91c1c;font-size:12px;">AI unavailable</span>';
        }
      };
      actRow.appendChild(aiBtn);
      leftContent.appendChild(actRow);
      leftContent.appendChild(aiResultBox);
      // Re-point actRow to a new container so email checkbox goes below
      actRow = document.createElement("div");
      actRow.style.cssText = "display:flex;gap:8px;flex-wrap:wrap;margin-top:4px;align-items:center;";
    }
    if (isMissing && autoFillDone) {
      var emailLbl = document.createElement("label");
      emailLbl.style.cssText = "display:inline-flex;align-items:center;gap:5px;padding:6px 12px;border:1px solid #e2e8f0;border-radius:6px;background:#f8fafc;color:#475569;font:600 11px/1 Inter,sans-serif;cursor:pointer;";
      var emailChk = document.createElement("input");
      emailChk.type = "checkbox";
      emailChk.checked = _gfEmailLabels.has(ck.label);
      emailChk.style.cssText = "margin:0;";
      emailChk.onchange = function () {
        if (emailChk.checked) _gfEmailLabels.add(ck.label);
        else _gfEmailLabels.delete(ck.label);
        _renderField();
      };
      emailLbl.appendChild(emailChk);
      emailLbl.appendChild(document.createTextNode("✉️ Email Requester"));
      actRow.appendChild(emailLbl);
    }
    leftContent.appendChild(actRow);

    left.appendChild(leftContent);

    // Nav
    var nav = document.createElement("div");
    nav.className = "_eli3_bd_guided_nav";
    var prev = document.createElement("button");
    prev.type = "button";
    prev.className = "_eli3_bd_guided_nav_btn _eli3_bd_guided_nav_prev";
    prev.textContent = "← Previous";
    if (isFirst) { prev.disabled = true; prev.style.opacity = "0.35"; prev.style.cursor = "default"; }
    else { prev.onclick = function () {
      currentIdx--;
      _renderField();
      if (currentIdx >= 0 && currentIdx < placeholders.length) {
        try { onLocate(placeholders[currentIdx], values[placeholders[currentIdx]] || ""); } catch (_e) {}
      }
    }; }
    nav.appendChild(prev);
    var next = document.createElement("button");
    next.type = "button";
    next.className = "_eli3_bd_guided_nav_btn _eli3_bd_guided_nav_next";
    next.textContent = "Next →";
    next.onclick = function () {
      currentIdx++;
      _renderField();
      _emitProgress();
      _emitChange();
      // Auto-locate the new field in the document
      if (currentIdx < placeholders.length) {
        try { onLocate(placeholders[currentIdx], values[placeholders[currentIdx]] || ""); } catch (_e) {}
      }
    };
    nav.appendChild(next);
    if (_gfEmailLabels.size > 0) {
      var emailNavBtn = document.createElement("button");
      emailNavBtn.type = "button";
      emailNavBtn.style.cssText = "padding:4px 8px;border:1px solid #c9a227;border-radius:6px;background:linear-gradient(135deg,#fefce8,#fef9c3);color:#92400e;font:600 9px/1 Inter,sans-serif;cursor:pointer;white-space:nowrap;";
      emailNavBtn.textContent = "✉️ " + _gfEmailLabels.size;
      emailNavBtn.title = "Email Requester (" + _gfEmailLabels.size + " field" + (_gfEmailLabels.size === 1 ? "" : "s") + ")";
      emailNavBtn.onclick = function () { onEmailRequester(Array.from(_gfEmailLabels)); };
      nav.appendChild(emailNavBtn);
    }
    var startOver = document.createElement("button");
    startOver.type = "button";
    startOver.className = "_eli3_bd_guided_nav_btn _eli3_bd_guided_nav_startover";
    startOver.textContent = "↺ Start Over";
    startOver.onclick = function () {
      currentIdx = 0;
      _gfEmailLabels.clear();
      placeholders.forEach(function (p) { values[p] = ""; });
      _renderField();
      _emitProgress();
      _emitChange();
    };
    nav.appendChild(startOver);
    left.appendChild(nav);

    // Progress bar
    var progWrap = document.createElement("div");
    progWrap.className = "_eli3_bd_guided_progress_bar";
    progWrap.innerHTML =
      '<div class="_eli3_bd_guided_progress_fill" id="_eli3_bd_gf_fill"></div>' +
      '<div class="_eli3_bd_guided_progress_label" id="_eli3_bd_gf_plabel"></div>';
    left.appendChild(progWrap);

    card.appendChild(left);

    // Drag handle
    var drag = document.createElement("div");
    drag.className = "_eli3_bd_guided_drag";
    drag.title = "Drag to resize columns";
    card.appendChild(drag);
    drag.addEventListener("mousedown", function (e) {
      e.preventDefault();
      var isVertical = window.getComputedStyle(card).flexDirection === "column";
      var startPos = isVertical ? e.clientY : e.clientX;
      var cardSize = isVertical ? card.getBoundingClientRect().height : card.getBoundingClientRect().width;
      var leftSize0 = isVertical ? left.getBoundingClientRect().height : left.getBoundingClientRect().width;
      function onMove(ev) {
        var delta = (isVertical ? ev.clientY : ev.clientX) - startPos;
        var newLeft = Math.max(80, Math.min(cardSize - 80, leftSize0 + delta));
        left.style.flex = "0 0 " + newLeft + "px";
        right.style.flex = "1 1 0";
      }
      function onUp() {
        document.removeEventListener("mousemove", onMove);
        document.removeEventListener("mouseup", onUp);
        document.body.style.cursor = "";
        document.body.style.userSelect = "";
      }
      document.body.style.cursor = isVertical ? "row-resize" : "col-resize";
      document.body.style.userSelect = "none";
      document.addEventListener("mousemove", onMove);
      document.addEventListener("mouseup", onUp);
    });

    // Right column
    var right = document.createElement("div");
    right.className = "_eli3_bd_guided_right";
    var colHeader = document.createElement("div");
    colHeader.className = "_eli3_bd_guided_col_header";

    var rightBody = document.createElement("div");
    rightBody.className = "_eli3_bd_guided_right_body";

    if (isPayment) {
      // Payment placeholder — OARS data compact on top, Payment Helper inline below
      colHeader.innerHTML = '<span class="_eli3_bd_guided_col_icon">💰</span><span>PAYMENT HELPER</span>';
      rightBody.style.cssText = "flex:1 1 0;display:flex;flex-direction:column;min-height:0;overflow:hidden;padding:0;";
      // Compact OARS strip on top (collapsible)
      var oarsStrip = document.createElement("div");
      oarsStrip.style.cssText = "flex:0 0 auto;max-height:120px;overflow-y:auto;padding:8px 14px;background:#f0f9ff;border-bottom:1px solid #e2e8f0;";
      // Find fee-related OARS fields for quick reference
      var feeTerms = ["fee", "amount", "payment", "cost", "price", "total"];
      var feeFields = Object.keys(oarsFields).filter(function (k) {
        var kl = k.toLowerCase();
        return feeTerms.some(function (t) { return kl.indexOf(t) !== -1; });
      });
      if (feeFields.length) {
        oarsStrip.innerHTML = '<div style="font:700 8px/1 Inter,sans-serif;color:#0c4a6e;letter-spacing:.1em;margin-bottom:6px;">OARS FEE DATA</div>' +
          feeFields.map(function (k) {
            return '<div style="display:flex;gap:6px;padding:2px 0;font-size:11px;"><span style="font-weight:700;color:#0c4a6e;">' + _esc(k) + '</span><span style="color:#1e293b;">' + _esc(oarsFields[k]) + '</span></div>';
          }).join("");
      } else {
        oarsStrip.innerHTML = '<div style="font:500 10px/1.3 Inter,sans-serif;color:#94a3b8;">No fee-related OARS fields found.</div>';
      }
      rightBody.appendChild(oarsStrip);
      // Find total fee from other filled values ($![[...]] placeholders)
      var _payTotalFee = "";
      placeholders.forEach(function (p) {
        if (/^\$!\[\[/.test(p) && values[p] && values[p] !== ph) _payTotalFee = values[p];
      });
      // Also check OARS fields for fee amount
      if (!_payTotalFee) {
        feeFields.forEach(function (k) {
          if (!_payTotalFee && oarsFields[k]) {
            var n = parseFloat(String(oarsFields[k]).replace(/[^0-9.\-]/g, ""));
            if (!isNaN(n) && n > 0) _payTotalFee = oarsFields[k];
          }
        });
      }
      // Payment Helper widget inline — renders directly into the column.
      // Must be in the live DOM before showPaymentScheduleModal runs
      // because the modal uses document.getElementById on its own elements.
      var payWidget = document.createElement("div");
      payWidget.style.cssText = "flex:1 1 0;overflow-y:auto;min-height:0;padding:0;background:linear-gradient(180deg,#fffef5,#fef9e7);";
      rightBody.appendChild(payWidget);
      right.appendChild(colHeader);
      right.appendChild(rightBody);
      card.appendChild(right);
      bodyEl.appendChild(card);
      // Now the DOM tree is live — safe to call showPaymentScheduleModal
      var _payApplyCb = function (formattedString) {
        if (formattedString == null) return;
        inp.value = formattedString;
        values[ph] = formattedString;
        _updateProgress();
        _emitChange();
      };
      if (typeof window.showPaymentScheduleModal === "function") {
        var _origMount = window._eliMountOverlay;
        var _mountRestored = false;
        window._eliMountOverlay = function (overlay) {
          try {
            var cards = overlay.querySelectorAll(".tool-box");
            if (cards.length > 0) {
              var mainCard = cards[0];
              mainCard.style.cssText = "background:#fff;width:100%;padding:0;border-radius:8px;box-shadow:none;border:1px solid #e2e8f0;display:flex;flex-direction:column;overflow:hidden;";
              payWidget.appendChild(mainCard);
            }
          } catch (_e) {}
          if (!_mountRestored) { window._eliMountOverlay = _origMount; _mountRestored = true; }
        };
        try {
          window.showPaymentScheduleModal(_payTotalFee || "", inp.value || "", _payApplyCb);
        } catch (_payErr) {
          payWidget.innerHTML = '<div style="color:#b91c1c;font:500 12px/1.4 Inter,sans-serif;padding:12px;">Payment helper error: ' + (_payErr && _payErr.message || "unknown") + '</div>';
        }
        if (!_mountRestored) { window._eliMountOverlay = _origMount; _mountRestored = true; }
      } else {
        payWidget.innerHTML = '<div style="color:#94a3b8;font:500 12px/1.4 Inter,sans-serif;padding:12px;">Payment helper not available.</div>';
      }
      _updateProgress();
      return; // DOM already assembled above — skip the common append below
    } else {
      // Normal field — full OARS tables (default) with Filtered toggle
      colHeader.innerHTML = '<span class="_eli3_bd_guided_col_icon">📋</span><span>OARS DATA</span>' +
        '<button type="button" class="_eli3_bd_guided_col_viewall">🔎 Filtered</button>';
      var viewAllBtn2 = colHeader.querySelector("._eli3_bd_guided_col_viewall");
      var oarsContent = document.createElement("div");
      var _showingFiltered = false;
      function _renderOarsPanel() {
        oarsContent.innerHTML = "";
        if (_showingFiltered) {
          // Filtered — key-value grid from parsed fields
          if (viewAllBtn2) viewAllBtn2.textContent = "📋 Full";
          var fKeys = Object.keys(oarsFields);
          if (!fKeys.length) { oarsContent.innerHTML = '<div class="_eli3_bd_guided_ctx_empty">No parsed OARS fields.</div>'; return; }
          var searchTerm = String(ck.aiKey || "").toLowerCase().trim();
          // For lookup fields, also try the lookup reference as search term
          var _oarsSearchKey = ck.aiKey || "";
          if (ck.lookup) { _oarsSearchKey = ck.lookup; searchTerm = String(ck.lookup).toLowerCase().trim(); }
          var html = '';
          if (searchTerm) html += '<div class="_eli3_bd_guided_ctx_header">🔎 Showing: ' + _esc(_oarsSearchKey) + '</div>';
          html += '<div class="_eli3_bd_guided_oars_grid">' + fKeys.map(function (k) {
            var v = String(oarsFields[k] || "");
            var kl = k.toLowerCase(), vl = v.toLowerCase();
            var hit = searchTerm && (kl.indexOf(searchTerm) !== -1 || vl.indexOf(searchTerm) !== -1);
            return '<div class="_eli3_bd_guided_oars_row' + (hit ? ' _eli3_bd_guided_oars_hit' : '') + '">' +
              '<span class="_eli3_bd_guided_oars_k">' + _esc(k) + '</span>' +
              '<span class="_eli3_bd_guided_oars_v">' + _esc(v) + '</span>' +
            '</div>';
          }).join("") + '</div>';
          oarsContent.innerHTML = html;
          var hit2 = oarsContent.querySelector("._eli3_bd_guided_oars_hit");
          if (hit2) setTimeout(function () { hit2.scrollIntoView({ block: "center", behavior: "smooth" }); }, 80);
        } else {
          // Full tables (default) with auto-highlight
          if (viewAllBtn2) viewAllBtn2.textContent = "🔎 Filtered";
          oarsContent.innerHTML = _renderOarsTables();
          var _fullSearchKey = ck.lookup || ck.aiKey;
          if (_fullSearchKey) {
            var term2 = String(_fullSearchKey).toLowerCase().trim();
            if (term2) {
              var cells2 = oarsContent.querySelectorAll("._eli3_bd_guided_oars_tbl_td");
              for (var ci2 = 0; ci2 < cells2.length; ci2++) {
                if (String(cells2[ci2].textContent).toLowerCase().indexOf(term2) !== -1) {
                  var tr2 = cells2[ci2].parentElement;
                  if (tr2) { tr2.querySelectorAll("._eli3_bd_guided_oars_tbl_td").forEach(function (c) { c.style.cssText = "background:#fef3c7;color:#92400e;font-weight:700;font-size:13px;"; }); }
                  setTimeout((function (el) { return function () { el.scrollIntoView({ block: "center", behavior: "smooth" }); }; })(cells2[ci2]), 80);
                  break;
                }
              }
            }
          }
        }
      }
      if (viewAllBtn2) viewAllBtn2.onclick = function () { _showingFiltered = !_showingFiltered; _renderOarsPanel(); };
      _renderOarsPanel();
      rightBody.appendChild(oarsContent);
    }

    right.appendChild(colHeader);
    right.appendChild(rightBody);
    card.appendChild(right);
    bodyEl.appendChild(card);
    _updateProgress();
    // Auto-scroll right column to highlighted row
    try {
      var hit = right.querySelector("._eli3_bd_guided_oars_tbl_td[style]");
      if (hit) setTimeout(function () { hit.scrollIntoView({ block: "center", behavior: "smooth" }); }, 80);
    } catch (_e) {}
  }

  // Auto-fill first, then render the first field
  if (sourceText && !Object.keys(prefillValues).length) {
    // Show loading state
    bodyEl.innerHTML =
      '<div style="display:flex;flex-direction:column;align-items:center;justify-content:center;gap:16px;padding:48px 24px;text-align:center;">' +
        '<div style="font-size:36px;">⚡</div>' +
        '<div style="font:700 16px/1.2 Inter,sans-serif;color:#0f172a;">Auto-Filling Fields</div>' +
        '<div style="font:400 12px/1.5 Inter,sans-serif;color:#64748b;max-width:240px;">Analyzing OARS data to pre-fill your placeholders…</div>' +
        '<div style="width:120px;height:4px;background:#e2e8f0;border-radius:2px;overflow:hidden;">' +
          '<div style="width:60%;height:100%;background:linear-gradient(90deg,#c9a227,#d4af37);animation:_eli3_bd_guided_fadein 1s infinite alternate;"></div>' +
        '</div>' +
      '</div>';
    onAutoFill(placeholders, function (mapping, err) {
      if (!err && mapping) {
        autoFillMapping = mapping;
        placeholders.forEach(function (ph) {
          var ck2 = _cleanLabel(ph);
          var v = mapping[ph] || mapping[ck2.aiKey];
          if (v) values[ph] = v;
        });
      }
      autoFillDone = true;
      currentIdx = 0;
      _renderField();
      _emitProgress();
      // Auto-locate first field in the document
      if (placeholders.length) { try { onLocate(placeholders[0], values[placeholders[0]] || ""); } catch (_e) {} }
    });
  } else {
    // Already have prefill values or no source — skip auto-fill
    if (Object.keys(prefillValues).length) autoFillDone = true;
    _renderField();
    _emitProgress();
    // Auto-locate first field in the document
    if (placeholders.length) { try { onLocate(placeholders[0], values[placeholders[0]] || ""); } catch (_e) {} }
  }
}

// renderBracketCleaner — Step 2 v3-native port of v2's showBracketCleaner
// (line 22706). Lists [bracket] placeholders + locate buttons + 💡 SOW
// helper trigger when a cleaner_rules match exists.

view.renderBracketCleaner:
function renderBracketCleaner(opts) {
  var mount = opts.mount || document.getElementById("_eli3_dashboard_root");
  if (!mount) return;
  var brackets = (opts.brackets && opts.brackets.items) || [];
  var financial = (opts.financial && opts.financial.items) || [];
  var cleanerRules = opts.cleanerRules || [];
  var onBack = opts.onBack || function () {};
  var onLocate = opts.onLocate || function () {};
  var onSowHelper = opts.onSowHelper || function () {};
  var onDone = opts.onDone || function () {};

  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }
  // Find a cleaner_rules match for an inner bracket label.
  function _ruleFor(inner) {
    var lower = String(inner || "").toLowerCase();
    for (var i = 0; i < cleanerRules.length; i++) {
      var r = cleanerRules[i];
      if (!r || !r.id || r.id.indexOf("__") === 0) continue;
      if (lower.indexOf(String(r.id).toLowerCase()) !== -1) return r;
      if (r.title && lower.indexOf(String(r.title).toLowerCase().replace(/[^a-z]/g, "")) !== -1) return r;
    }
    return null;
  }

  mount.innerHTML = "";
  var root = document.createElement("div");
  root.className = "_eli3_bd_root _eli3_bd_cleaner";
  root.innerHTML =
    '<div class="_eli3_bd_bar">' +
      '<button class="_eli3_bd_back">←</button>' +
      '<div class="_eli3_bd_title">📝 Fill Placeholders</div>' +
      '<div class="_eli3_bd_overview">' + brackets.length + ' bracket' + (brackets.length === 1 ? "" : "s") +
        (financial.length ? ' · ' + financial.length + ' $ amount' + (financial.length === 1 ? "" : "s") : '') +
      '</div>' +
    '</div>' +
    '<div class="_eli3_bd_cleaner_intro">' +
      (brackets.length || financial.length
        ? '<b>' + brackets.length + ' placeholder' + (brackets.length === 1 ? "" : "s") + '</b> + ' +
          '<b>' + financial.length + ' $ amount' + (financial.length === 1 ? "" : "s") + '</b> detected. ' +
          'Use Locate to jump to each in Word; click 💡 for SOW Helper suggestions when available.'
        : 'No placeholders or $ amounts detected in the body.') +
    '</div>' +
    '<div class="_eli3_bd_cleaner_list" id="_eli3_bd_cleaner_list"></div>' +
    '<div class="_eli3_bd_cleaner_done">' +
      '<button class="_eli3_bd_run_all" id="_eli3_bd_done_btn">I\'M DONE ➜</button>' +
    '</div>';
  root.querySelector("._eli3_bd_back").onclick = onBack;
  root.querySelector("#_eli3_bd_done_btn").onclick = onDone;

  var list = root.querySelector("#_eli3_bd_cleaner_list");
  // Combined list: brackets first, $ amounts after.
  var rows = brackets.map(function (b) { return { type: "bracket", text: b.text, inner: b.inner, rule: _ruleFor(b.inner) }; })
    .concat(financial.map(function (f) { return { type: "financial", text: f.text, inner: f.text }; }));
  if (!rows.length) {
    var empty = document.createElement("div");
    empty.className = "_eli3_bd_cleaner_empty";
    empty.textContent = "Nothing to review.";
    list.appendChild(empty);
  } else {
    rows.forEach(function (r, idx) {
      var row = document.createElement("div");
      row.className = "_eli3_bd_cleaner_row";
      var typeTag = r.type === "financial"
        ? '<span class="_eli3_bd_cleaner_tag _eli3_bd_cleaner_tag_money">$</span>'
        : '<span class="_eli3_bd_cleaner_tag">[</span>';
      var helperBtn = r.rule
        ? '<button class="_eli3_bd_action_btn _eli3_bd_action_help" data-eli-bd-help="' + idx + '">💡 Suggestions</button>'
        : '';
      row.innerHTML =
        '<div class="_eli3_bd_cleaner_left">' +
          typeTag +
          '<span class="_eli3_bd_cleaner_text">' + _esc(r.text) + '</span>' +
        '</div>' +
        '<div class="_eli3_bd_cleaner_right">' +
          '<button class="_eli3_bd_action_btn _eli3_bd_action_locate" data-eli-bd-locate="' + idx + '">📍 Locate</button>' +
          helperBtn +
        '</div>';
      row.querySelector("[data-eli-bd-locate]").onclick = function () { onLocate(r); };
      var help = row.querySelector("[data-eli-bd-help]");
      if (help) help.onclick = function () { onSowHelper(r); };
      list.appendChild(row);
    });
  }
  mount.appendChild(root);
}

// renderSowHelper — modal overlay listing cleaner_rules options for a
// detected bracket. FROM v2 showGenericCleanerHelper (line 22780).
// Uses showEliDialog for tier:premium consistency.

view.renderSowHelper:
function renderSowHelper(opts) {
  var rule = opts.rule || {};
  var target = opts.target || "";
  var onPick = opts.onPick || function () {};
  if (typeof showEliDialog !== "function") {
    if (window.eli && window.eli.log) window.eli.log.event("tool", "build_draft_no_dialog", {});
    if (typeof showToast === "function") showToast("Dialog primitive unavailable", "err");
    return;
  }
  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
  }
  var optsHtml = (rule.options || []).map(function (o, i) {
    return '<button class="_eli3_bd_sow_option" data-eli-bd-sow-pick="' + i + '">' +
      '<span class="_eli3_bd_sow_option_label">' + _esc(o.label) + '</span>' +
      '<span class="_eli3_bd_sow_option_desc">' + _esc(o.desc || o.text || "") + '</span>' +
    '</button>';
  }).join("");
  showEliDialog({
    variant: "info",
    tier: "premium",
    icon: "💡",
    title: "SOW Helper · " + (rule.title || rule.id || "Suggestions"),
    body:
      '<div class="_eli3_bd_sow_intro">Select a clause to replace ' +
      '<b>' + _esc(target) + '</b>:</div>' +
      '<div class="_eli3_bd_sow_options">' + optsHtml + '</div>',
    secondary: { label: "Cancel" },
    onMount: function (overlay) {
      overlay.querySelectorAll("[data-eli-bd-sow-pick]").forEach(function (btn) {
        btn.onclick = function () {
          var i = parseInt(btn.getAttribute("data-eli-bd-sow-pick"), 10);
          var picked = (rule.options || [])[i];
          if (picked) onPick(picked);
          if (overlay.parentNode) overlay.parentNode.removeChild(overlay);
        };
      });
    },
  });
}

// renderTemplatesView — FROM v2 showFileNameSettings (line 20740). Two
