    // templates are MasterXML — they all bunched up in arbitrary order.
    function _getSortPref() {
      try { return localStorage.getItem("eli_bd_tpl_sort") || "alpha"; }
      catch (_e) { return "alpha"; }
    }
    function _setSortPref(v) {
      try { localStorage.setItem("eli_bd_tpl_sort", v); } catch (_e) {}
    }
    // 2026-05-27: helpers for the grouped-by-type render. _typeRaw +
    // _typeKey + _typeLabel use the same normalization the picker uses
    // in init.js so priors group with their core regardless of casing or
    // " - party" suffix on the name.
    function _typeRaw(t) {
      var raw = String(t.agreementType || "").trim();
      if (!raw && t.name) raw = String(t.name).split(/\s+-\s+/)[0].trim();
      return raw || "Other";
    }
    function _typeKey(t) {
      return _typeRaw(t).toLowerCase().replace(/[^a-z0-9]+/g, "") || "other";
