    function _typeLabel(t) {
      return _typeRaw(t).replace(/\b\w/g, function (c) { return c.toUpperCase(); });
    }
    function _isMaster(t) {
      return t.type === "MasterXML" || /__masterxml__/i.test(t.id || "");
    }
    function _sortTemplates(arr, mode) {
      var copy = arr.slice();
      if (mode === "date") {
        // Newest first. Fall back chain: savedDate (legacy) → modifiedAt
        // (template_manager) → timestamp (numeric ms) → 0.
        copy.sort(function (a, b) {
          var aT = _tsOf(a), bT = _tsOf(b);
          return bT - aT;
        });
      } else {
        copy.sort(function (a, b) {
