          var bn = String(b.name || b.agreementType || b.id || "").toLowerCase();
          return an.localeCompare(bn);
        });
      }
      return copy;
    }
    function _tsOf(t) {
      // Prefer modifiedAt (ISO), then publishedAt, then timestamp (ms),
      // then savedDate (toLocaleString — parseable but lossy).
      if (t.modifiedAt) { var d1 = new Date(t.modifiedAt).getTime(); if (!isNaN(d1)) return d1; }
      if (t.publishedAt) { var d2 = new Date(t.publishedAt).getTime(); if (!isNaN(d2)) return d2; }
      if (typeof t.timestamp === "number") return t.timestamp;
      if (t.savedDate) { var d3 = new Date(t.savedDate).getTime(); if (!isNaN(d3)) return d3; }
      return 0;
    }
    var sortMode = _getSortPref();
    // Highlight whichever button matches the current pref.
    function _paintSortBtns() {
      ["alpha", "date"].forEach(function (m) {
        var btn = m === "alpha"
          ? body.querySelector("#_eli3_bd_tpl_sort_az")
          : body.querySelector("#_eli3_bd_tpl_sort_date");
        if (!btn) return;
        var active = (m === sortMode);
        btn.style.background = active ? "linear-gradient(180deg,#0d47a1,#0a3a82)" : "#fff";
        btn.style.color = active ? "#fff" : "#475569";
        btn.style.borderColor = active ? "#0a3a82" : "#cbd5e1";
      });
    }
    _paintSortBtns();
    body.querySelectorAll("#_eli3_bd_tpl_sort_az, #_eli3_bd_tpl_sort_date").forEach(function (btn) {
      btn.onclick = function () {
        sortMode = btn.getAttribute("data-sort");
        _setSortPref(sortMode);
        _paintSortBtns();
        _renderRows();
      };
    });
    // 2026-05-27: group-by-type render. Same key logic as the picker.
    // Cores first within each group, priors below + indented so the
    // ownership is visible at a glance. Groups themselves order by the
    // user's sort pref (alpha by label OR newest-first by group's
    // most-recently-modified row).
    function _renderRows() {
      list.innerHTML = "";
      var groupsMap = {};
      (templates || []).forEach(function (t) {
        if (!t) return;
        var k = _typeKey(t);
        if (!groupsMap[k]) {
          groupsMap[k] = { label: _typeLabel(t), master: null, priors: [], newestTs: 0 };
        }
        var ts = _tsOf(t);
        if (ts > groupsMap[k].newestTs) groupsMap[k].newestTs = ts;
        if (_isMaster(t)) {
          if (!groupsMap[k].master) groupsMap[k].master = t;
          else groupsMap[k].priors.push(t);
        } else {
          groupsMap[k].priors.push(t);
        }
      });
      var keys = Object.keys(groupsMap);
      if (sortMode === "date") {
        keys.sort(function (a, b) { return groupsMap[b].newestTs - groupsMap[a].newestTs; });
      } else {
        keys.sort(function (a, b) {
          return groupsMap[a].label.toLowerCase().localeCompare(groupsMap[b].label.toLowerCase());
        });
      }
      keys.forEach(function (k) {
        var g = groupsMap[k];
        g.priors.sort(function (a, b) {
          var an = String(a.party || a.name || "").toLowerCase();
          var bn = String(b.party || b.name || "").toLowerCase();
          return an.localeCompare(bn);
        });
        if (g.master) _renderRow(g.master, /*isPrior*/ false);
        g.priors.forEach(function (p) { _renderRow(p, /*isPrior*/ true); });
      });
    }
    function _renderRow(t, isPrior) {
      // CORE vs PRIOR — v2 template TYPE distinction:
      //   • type: "MasterXML"     → canonical master template (CORE)
      //   • type: "PriorAgreement" → reusable past contract (PRIOR)
      //
      // 2026-05-22 v3: also detect MasterXML from the slug. Some
      // templates were imported with the type encoded in the ID
      // (e.g. `bd_doc__amendment__masterxml___`) but the explicit
      // `type` field never got set. Treat slug-encoded MasterXML
      // as an authoritative signal so the badge reflects reality.
      // Same for slug-encoded prior (templates with `__prior__`
      // in the ID).
      var isMaster = t.type === "MasterXML" || /__masterxml__/i.test(t.id || "");
      var icon = isMaster ? "🏗️" : "📂";
      var badge = isMaster ? "CORE" : "PRIOR";
      // Show the actual size in IDB right now — compressed bytes if the
      // row is zipped, raw string length otherwise. Falls back to
      // content.length for any row the decompress helper hasn't decorated.
      var _storedKB = (typeof t._storedBytes === "number")
        ? (t._storedBytes / 1024)
        : (String(t.content || "").length / 1024);
      var size = _storedKB.toFixed(1) + " KB";
      var row = document.createElement("div");
      row.className = "_eli3_bd_tpl_row " + (isMaster ? "_eli3_bd_tpl_row_core" : "_eli3_bd_tpl_row_prior");
      // 2026-05-27: indent prior rows so the relationship to the core
      // above them is visually clear. Left padding + thin gray border
      // on the left edge reads as a tree-child.
      if (isPrior) {
        row.style.paddingLeft = "28px";
        row.style.borderLeft = "3px solid #cbd5e1";
        row.style.background = "#fafbfc";
      }
      // 2026-05-22 v2: date fallback chain MATCHES the sort priority
      // in _tsOf so the displayed timestamp is the one being sorted on.
      // Previously display preferred legacy `savedDate` while sort
      // preferred `modifiedAt` — the two could diverge by hours, making
      // the visible date appear out-of-order in Date sort mode.
      // Unified priority: modifiedAt → publishedAt → savedDate.
      var rawDate = t.modifiedAt || t.publishedAt || t.savedDate || "";
      var dateStr = "";
      if (rawDate) {
        try {
          var d = new Date(rawDate);
          dateStr = !isNaN(d.getTime())
            ? d.toLocaleString("en-US", {
                month: "short", day: "numeric", year: "numeric",
                hour: "numeric", minute: "2-digit",
              })
            : rawDate;
        } catch (_e) { dateStr = rawDate; }
      }
      // Initials of whoever last pushed this template to the CDN — shown
      // in parentheses on the meta line. "andrew_nemiroff@…" → "(AN)".
      // Empty when the row has no publishedBy (local-only / pre-feature).
      function _initialsFromEmail(email) {
        var local = String(email || "").split("@")[0].trim();
        if (!local) return "";
        var parts = local.split(/[._\-]+/).filter(Boolean);
        var ini = parts.length >= 2 ? (parts[0].charAt(0) + parts[1].charAt(0)) : local.slice(0, 2);
        return ini.toUpperCase();
      }
      var pushedIni = _initialsFromEmail(t.publishedBy);
      // Assemble meta line — skip badge segment when empty so we
      // don't render an orphan leading bullet ("· 4.2 KB · …").
      var metaSegs = [];
      if (badge) metaSegs.push(badge);
      metaSegs.push(size + " KB");
      if (dateStr) metaSegs.push(_esc(dateStr));
      if (pushedIni) metaSegs.push("(" + _esc(pushedIni) + ")");
      row.innerHTML =
        '<div class="_eli3_bd_tpl_row_main">' +
          '<div class="_eli3_bd_tpl_row_name">' + icon + " " + _esc(t.name || t.agreementType || "Untitled") + '</div>' +
          '<div class="_eli3_bd_tpl_row_meta">' + metaSegs.join(" · ") + '</div>' +
        '</div>' +
        '<button class="_eli3_bd_tpl_row_load" title="Load into doc">📥</button>' +
        '<button class="_eli3_bd_tpl_row_del" title="Delete">🗑️</button>';
      row.querySelector("._eli3_bd_tpl_row_load").onclick = function () { onLoadTemplate(t); };
      row.querySelector("._eli3_bd_tpl_row_del").onclick = function () { onDeleteTemplate(t); };
      list.appendChild(row);
    }
    _renderRows();
  }

  _setActiveTab(initialTab);
  mount.appendChild(root);
}

// renderSavePanel — FROM v2 showSaveAsManager (line 18930). REPURPOSED
// 2026-05-16: in-app save was unreliable (didn't carry OARS attach
// metadata, occasional sync failures). Replaced with a copy-paste
// flow: form generates a clean filename, big copy button puts it on
// the clipboard, instructions tell user to invoke Word's native Save
// As (Fn+F12 / Ctrl+Shift+S) and paste. Native save preserves everything
// the in-app save was losing. Skip → Email kept.

view.renderSavePanel:
function renderSavePanel(opts) {
  var mount = opts.mount || document.getElementById("_eli3_dashboard_root");
  if (!mount) return;
  var prefill = opts.prefill || {};
  var agTypes = opts.agTypes || []; // array of strings, e.g. ["NDA", "MSA", ...]
  var agTypeRows = opts.agTypeRows || []; // full rows: { id, label, abbrev, aliases }
  var patterns = opts.patterns || {
    colgate: "[Ref] [Party] - [Type] (CP DRAFT [Date])",
    hills: "[Ref] [Party] - [Type] (HPN DRAFT [Date])",
  };
  // Filename-only abbreviation: match the chosen type against each row's
  // label / id / aliases (case-insensitive); use its `abbrev` if non-blank,
  // else fall back to the full type string. Used ONLY for [Type] in the
  // filename — the type displays in full everywhere else.
  function _abbrevForType(typeStr) {
    var t = String(typeStr == null ? "" : typeStr).trim();
    if (!t) return t;
    var tl = t.toLowerCase();
    for (var i = 0; i < agTypeRows.length; i++) {
      var r = agTypeRows[i]; if (!r) continue;
      var hit = (String(r.label || "").toLowerCase() === tl) ||
                (String(r.id || "").toLowerCase() === tl) ||
                (Array.isArray(r.aliases) && r.aliases.some(function (a) { return String(a || "").toLowerCase() === tl; }));
      if (hit) {
        var ab = String(r.abbrev || "").trim();
        return ab || t; // blank abbrev → full name
      }
    }
    return t; // no match → use as typed
  }
  // onSave kept for backward-compat but unused in the copy-paste flow.
  // The form's primary action is now copy-to-clipboard; the save path
  // (formerly onSave → _runSaveAsDocx) is bypassed entirely.
  var onSkip = opts.onSkip || function () {};
  var onSettings = opts.onSettings || function () {};
  var onBack = opts.onBack || function () {};
  var scanning = !!opts.scanning;

  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }

  mount.innerHTML = "";
  var root = document.createElement("div");
  root.className = "_eli3_bd_root _eli3_bd_save";

  var typeOpts = '<option value="Other">Other (type below)</option>' +
    agTypes.map(function (t) { return '<option value="' + _esc(t) + '">' + _esc(t) + '</option>'; }).join("");

  root.innerHTML =
    '<div class="_eli3_bd_bar">' +
      '<button class="_eli3_bd_back">←</button>' +
      '<div class="_eli3_bd_title">📋 Build Filename</div>' +
      '<button class="_eli3_bd_save_settings" title="File-name settings">⚙️</button>' +
    '</div>' +
    (scanning
      ? '<div class="_eli3_bd_save_scanloader">' +
          '<div class="_eli3_bd_save_spinner"></div>' +
          '<div>Scanning document for metadata…</div>' +
        '</div>'
      : '') +
    '<div class="_eli3_bd_save_form">' +
      '<label class="_eli3_bd_save_label">CP Contracting Entity</label>' +
      '<select class="_eli3_bd_save_input" id="_eli3_bd_save_entity">' +
        '<option value="Colgate">Colgate-Palmolive Company</option>' +
        '<option value="Hills">Hill\'s Pet Nutrition</option>' +
      '</select>' +
      '<label class="_eli3_bd_save_label">Agreement Type</label>' +
      '<select class="_eli3_bd_save_input" id="_eli3_bd_save_type">' + typeOpts + '</select>' +
      '<input type="text" class="_eli3_bd_save_input _eli3_bd_save_hidden" id="_eli3_bd_save_typeManual" placeholder="Type Agreement Name…">' +
      '<label class="_eli3_bd_save_label">Third Party Name</label>' +
      '<input type="text" class="_eli3_bd_save_input" id="_eli3_bd_save_party" placeholder="e.g. Acme Corp">' +
      '<label class="_eli3_bd_save_label">CP Ref #</label>' +
      '<input type="text" class="_eli3_bd_save_input" id="_eli3_bd_save_ref" placeholder="e.g. 12345">' +
      // Big copy-target filename block — large monospace, click-to-select.
      '<div class="_eli3_bd_fn_block">' +
        '<div class="_eli3_bd_fn_label">YOUR FILENAME</div>' +
        '<div class="_eli3_bd_fn_value" id="_eli3_bd_save_preview" title="Click to select then copy">…</div>' +
        '<button class="_eli3_bd_fn_copy" id="_eli3_bd_save_copy" type="button">📋 Copy filename</button>' +
        '<div class="_eli3_bd_fn_copy_ack" id="_eli3_bd_save_copy_ack" style="display:none;">✓ Copied — <strong>click into your Word document</strong>, then hit <kbd>Fn+F12</kbd> (or <kbd>F12</kbd>, or <kbd>Ctrl+Shift+S</kbd>) and paste</div>' +
      '</div>' +
      // Step-by-step instructions.
      '<div class="_eli3_bd_fn_steps">' +
        '<div class="_eli3_bd_fn_steps_head">HOW TO SAVE</div>' +
        '<ol class="_eli3_bd_fn_steps_list">' +
          '<li>Click <strong>Copy filename</strong> above</li>' +
          '<li><strong>Click anywhere in your Word document first</strong> — this puts focus in Word (the taskpane swallows keystrokes otherwise)</li>' +
          '<li>Press <kbd>Fn+F12</kbd> (or <kbd>F12</kbd>, or <kbd>Ctrl+Shift+S</kbd>) to open <strong>Save As</strong></li>' +
          '<li>Paste (<kbd>Ctrl+V</kbd>) into the <em>File name</em> box</li>' +
          '<li>Pick your folder and click <strong>Save</strong></li>' +
        '</ol>' +
        '<div class="_eli3_bd_fn_why">Why copy-paste? Word\'s native Save As preserves everything (formatting, OARS attachments, doc settings). The in-app save dropped some of that.</div>' +
      '</div>' +
      '<div class="_eli3_bd_save_actions">' +
        '<button class="_eli3_bd_save_skip" id="_eli3_bd_save_skip" type="button">Skip → Email</button>' +
        '<button class="_eli3_bd_save_btn" id="_eli3_bd_save_btn" type="button">' +
          '<span class="_eli3_bd_save_btn_icon">📋</span>' +
          '<span class="_eli3_bd_save_btn_label">Copy + Continue → Email</span>' +
        '</button>' +
      '</div>' +
    '</div>';
  root.querySelector("._eli3_bd_back").onclick = onBack;
  root.querySelector("._eli3_bd_save_settings").onclick = onSettings;

  var entitySel = root.querySelector("#_eli3_bd_save_entity");
  var typeSel = root.querySelector("#_eli3_bd_save_type");
  var typeManual = root.querySelector("#_eli3_bd_save_typeManual");
  var partyInp = root.querySelector("#_eli3_bd_save_party");
  var refInp = root.querySelector("#_eli3_bd_save_ref");
  var previewEl = root.querySelector("#_eli3_bd_save_preview");

  // Apply prefill.
  if (prefill.entity) entitySel.value = prefill.entity;
  if (prefill.third_party_entity) partyInp.value = prefill.third_party_entity;
  if (prefill.cp_ref) refInp.value = prefill.cp_ref;
  // Match agreement type by case-insensitive substring.
  var prefType = (prefill.type || "").toLowerCase();
  if (prefType) {
    var found = false;
    for (var i = 0; i < typeSel.options.length; i++) {
      var v = typeSel.options[i].value.toLowerCase();
      if (v && v !== "other" && (prefType.indexOf(v) !== -1 || v.indexOf(prefType) !== -1)) {
        typeSel.selectedIndex = i; found = true; break;
      }
    }
    if (!found) {
      typeSel.value = "Other";
      typeManual.classList.remove("_eli3_bd_save_hidden");
      typeManual.value = prefill.type;
    }
  }

  // execChk removed 2026-05-12 — checkbox no longer rendered. Kept
  // var as null so the legacy guards (`execChk && execChk.checked`)
  // still short-circuit to false without touching the DOM.
  var execChk = null;

  function _genName() {
    var entity = entitySel.value;
    var typeFull = typeSel.value === "Other" ? (typeManual.value || "Agreement") : typeSel.value;
    // Filename uses the abbreviation when one is set for this type; blank → full.
    var type = _abbrevForType(typeFull);
    var party = partyInp.value.trim() || "Unknown";
    var ref = refInp.value.trim() || "Draft";
    var d = new Date();
    // m.dd.yy — month with NO leading zero (so Oct/Nov/Dec are naturally
    // 2-digit, satisfying the "Nov/Dec → mm.dd.yy" rule automatically),
    // day zero-padded, 2-digit year.
    var pad2 = function (n) { return n < 10 ? "0" + n : String(n); };
    var date = (d.getMonth() + 1) + "." + pad2(d.getDate()) + "." + String(d.getFullYear()).slice(-2);
    var pat = entity === "Hills" ? patterns.hills : patterns.colgate;
    function _build(partyStr) {
      var nm = String(pat || "")
        .replace("[Ref]", ref).replace("[Party]", partyStr)
        .replace("[Type]", type).replace("[Date]", date);
      // FROM v2 line 19064 — execution-mode filename mutation (execChk is
      // null today, so this is dormant): strip the DRAFT label.
      if (execChk && execChk.checked) {
        nm = nm.replace(/\(DRAFT\s+/gi, "(").replace(/\bDRAFT\b/gi, "").replace(/\s+/g, " ").trim();
      }
      return nm + ".docx";
    }
    var name = _build(party);
    // 92-char cap: if the full filename is too long, shorten ONLY the party
    // name until it fits ([Party] appears once, so length tracks 1:1).
    if (name.length > 92 && party.length > 1) {
      var over = name.length - 92;
      var keep = Math.max(1, party.length - over);
      name = _build(party.slice(0, keep).replace(/[\s,\-]+$/, ""));
    }
    return name;
  }
  function _updatePreview() { previewEl.textContent = _genName(); }

  typeSel.onchange = function () {
    typeManual.classList.toggle("_eli3_bd_save_hidden", typeSel.value !== "Other");
    _updatePreview();
  };
  [entitySel, typeManual, partyInp, refInp].forEach(function (el) {
    el.addEventListener("input", _updatePreview);
    el.addEventListener("change", _updatePreview);
  });
  if (execChk) execChk.addEventListener("change", _updatePreview);
  _updatePreview();

  // Copy-to-clipboard with success acknowledgement. Falls back to a
  // selection-based execCommand("copy") on browsers where the async
  // clipboard API isn't available (Script Lab iframe quirks).
  function _copyFilename(showAck) {
    var name = _genName();
    var ackEl = root.querySelector("#_eli3_bd_save_copy_ack");
    function _onCopied() {
      // Report the copy back so the audit can mark the save step — in this
      // copy-paste flow, copying the filename IS the user's save action.
      try { if (opts && typeof opts.onCopyName === "function") opts.onCopyName({ filename: name }); } catch (_e) {}
      if (!showAck || !ackEl) return;
      ackEl.style.display = "block";
      setTimeout(function () { if (ackEl) ackEl.style.display = "none"; }, 4000);
    }
    if (navigator.clipboard && typeof navigator.clipboard.writeText === "function") {
      return navigator.clipboard.writeText(name).then(_onCopied).catch(function () {
        _copyViaSelection(name, _onCopied);
      });
    }
    _copyViaSelection(name, _onCopied);
    return Promise.resolve();
  }
  function _copyViaSelection(text, done) {
    var ta = document.createElement("textarea");
    ta.value = text;
    ta.style.position = "fixed";
    ta.style.left = "-9999px";
    document.body.appendChild(ta);
    ta.select();
    try { document.execCommand("copy"); } catch (_e) {}
    document.body.removeChild(ta);
    if (typeof done === "function") done();
  }
  // Click the filename block itself to copy (large target).
  var fnValueEl = root.querySelector("#_eli3_bd_save_preview");
  if (fnValueEl) fnValueEl.onclick = function () {
    // Visually-select the text first (matches the "click to select"
    // tooltip + works as a fallback if clipboard write fails).
    var range = document.createRange();
    range.selectNodeContents(fnValueEl);
    var sel = window.getSelection();
    sel.removeAllRanges();
    sel.addRange(range);
    _copyFilename(true);
  };
  var copyBtn = root.querySelector("#_eli3_bd_save_copy");
  if (copyBtn) copyBtn.onclick = function () { _copyFilename(true); };

  // Primary action — copy + continue to email composer. Preserves the
  // formData hand-off (the email composer reads entity/type/party to
  // seed subject + body), just skips the .docx-write step.
  root.querySelector("#_eli3_bd_save_btn").onclick = function () {
    _copyFilename(true);
    // Brief delay so the user sees the "✓ Copied" ack before the
    // panel transitions out into the email step.
    setTimeout(function () {
      onSkip();  // → _runStep5Email — uses same hand-off as Skip path
    }, 300);
  };
  root.querySelector("#_eli3_bd_save_skip").onclick = onSkip;

  mount.appendChild(root);
}

view.renderStepStub:
function renderStepStub(opts) {
  var mount = opts.mount || document.getElementById("_eli3_dashboard_root");
  if (!mount) return;
  var step = opts.step || {};
  var onBack = opts.onBack || function () {};
  mount.innerHTML = "";
  var root = document.createElement("div");
  root.className = "_eli3_bd_root";
  root.innerHTML =
    '<div class="_eli3_bd_bar">' +
      '<button class="_eli3_bd_back" title="Back">←</button>' +
      '<div class="_eli3_bd_title">' + (step.icon || "🛠️") + ' ' + (step.label || "Step") + '</div>' +
    '</div>' +
    '<div class="_eli3_bd_step_body">' +
      '<div class="_eli3_bd_step_pending">' +
        '<div class="_eli3_bd_step_pending_icon">🛠️</div>' +
        '<div class="_eli3_bd_step_pending_title">' + (step.label || "Step") + ' — pending v3 migration</div>' +
        '<div class="_eli3_bd_step_pending_desc">' +
          'This wizard step still runs in v2 mode. Migration to v3 lands once the engine ' +
          'logic is ported. For now, use Templates or Run All to invoke the v2 wizard.' +
        '</div>' +
      '</div>' +
    '</div>';
  root.querySelector("._eli3_bd_back").onclick = onBack;
  mount.appendChild(root);
}

jsonTools.init:
function init(eli) {
  // Magic-string constants — single source of truth across this tool.
  var SETTINGS_NAME = "AgreementDataName";
  var SETTINGS_TYPE = "AgreementDataType";
  var SETTINGS_DETAILS = "AgreementDataDetails";
  var BUS_OARS_FILE = "oars:file_selected";
  var BUS_OARS_CLEARED = "oars:cleared";
  var BUS_OARS_DETECTED = "oars:detected";
  var HF_TYPES = ["Primary", "FirstPage", "EvenPages"];
  var STEP2_APPLY_BATCH = 4; // keys per runRaw to keep under 100ms.

  // Wizard mode flag: when true, Step 1 → Step 2 → preSave → Step 3
  // chain auto-advances. Toggled by Run-All; cleared after Step 3 fires.
  var _wizardMode = false;

  // Kernel guarantees eli.events; if it's missing the kernel itself is
  // broken — fail loudly rather than paper over with a no-op shim.
  if (!eli.events || !eli.events.guard || !eli.events.safeAsync) {
    if (eli.log) eli.log.event("tool", "build_draft_missing_events", {});
    if (typeof showToast === "function") showToast("Build Draft failed: kernel events missing", "err");
    return;
  }
  var bundle = eli.tools._loaded["build_draft"];
  if (!bundle) return;
  var engineFns = bundle._eliEngineFns || {};
  var viewFns = bundle._eliViewFns || {};
  var analyze = engineFns.analyze;
  var evalLogicCondition = engineFns.evalLogicCondition;
  var extractTemplatePlaceholders = engineFns.extractTemplatePlaceholders;
  var renderHub = viewFns.renderHub;
  var renderStepStub = viewFns.renderStepStub;
  var renderBracketCleaner = viewFns.renderBracketCleaner;
  var renderSowHelper = viewFns.renderSowHelper;
  var renderLogicForm = viewFns.renderLogicForm;
  var renderGuidedLogicForm = viewFns.renderGuidedLogicForm;
  var renderTemplateFillForm = viewFns.renderTemplateFillForm;
  var renderGuidedFillForm = viewFns.renderGuidedFillForm;
  var renderTemplatesView = viewFns.renderTemplatesView;
  var renderSavePanel = viewFns.renderSavePanel;
  if (!analyze || !renderHub) {
    eli.log.event("tool", "build_draft_load_failed", { hasEngine: !!analyze, hasView: !!renderHub });
    return;
  }

  var providers = { host: eli.host, ai: eli.ai };

  // ─── Multi-line fill insertion (2026-05-27) ──────────────────────────
  // Step 2 fill values can contain newlines (OARS multi-line fields,
  // user-typed bullets, etc.). Default insertText collapses to single
  // line. _bdInsertText uses insertHtml with <br> soft line breaks for
  // multi-line values — proved as method 4 in inserter_lab (single
  // paragraph, no autoformat triggers, inherits surrounding formatting).
  // Kill switch: build_draft.multilineInsert (default ON). Flip OFF in
  // user settings to fall back to single-line insertText for every fill.
  try {
    eli.settings.register("build_draft.multilineInsert", {
      default: true,
      type: "boolean",
      storage: { type: "ls_blob_field", key: "eli_user_settings", field: "buildDraftMultilineInsert" },
      adminPushable: true,
      describe: "Build Draft: render multi-line fill values as <br> soft breaks (off = single-line insertText fallback)",
    });
  } catch (_e) {}
  // Review-Changes nav: drop a bookmark on every body fill so the
  // post-fill dialog can walk the user through them in document order.
  // Bookmarks are session-prefixed so multiple builds in the same doc
  // don't collide. Word.js has no public deleteBookmark — they persist
  // in the saved doc (invisible). Body-only for now (cross-scope H/F
  // bookmark resolution deferred). Kill switch: flip OFF to skip the
  // bookmark insert + hide the nav UI in the dialog.
  try {
    eli.settings.register("build_draft.reviewNavigation", {
      default: true,
      type: "boolean",
      storage: { type: "ls_blob_field", key: "eli_user_settings", field: "buildDraftReviewNavigation" },
      adminPushable: true,
      describe: "Build Draft: walk-the-fills nav arrows in Review Changes dialog (off = no bookmarks, no arrows)",
    });
  } catch (_e) {}
  // Auto-update Word fields (TOC, page numbers, cross-refs, dates) right
  // after Step 2 fill completes. Programmatic equivalent of select-all +
  // F9. Fully wrapped — per-field + per-section try/catch + safeAsync at
  // call site so a broken field never blocks the verification dialog.
  // Flip OFF if a template has fields that misbehave on .update().
  try {
    eli.settings.register("build_draft.refreshFieldsAfterStep2", {
      default: true,
      type: "boolean",
      storage: { type: "ls_blob_field", key: "eli_user_settings", field: "buildDraftRefreshFieldsAfterStep2" },
      adminPushable: true,
      describe: "Build Draft: auto-refresh all Word fields (TOC, page numbers, cross-refs, etc.) after Step 2 fill (off = manual F9 only)",
    });
  } catch (_e) {}
  // OARS auto-load confirmation. ON: show premium mascot dialog before
  // loading the detected template (lets user confirm / pick different /
  // skip). OFF: silent auto-load (legacy behavior). Flip OFF if you want
  // ELI to load templates without asking on every OARS document.
  try {
    eli.settings.register("build_draft.confirmOarsAutoLoad", {
      default: true,
      type: "boolean",
      storage: { type: "ls_blob_field", key: "eli_user_settings", field: "buildDraftConfirmOarsAutoLoad" },
      adminPushable: true,
      describe: "Build Draft: show confirmation dialog when OARS detection auto-matches a template (off = silent auto-load)",
    });
  } catch (_e) {}
  // Audit privacy gate. Step 2 fills (third-party names, $ amounts, cpRef
  // values) are the sensitive part of the audit recipe. They are ALWAYS
  // captured + stored locally (so the user's own viewer can fully recreate
  // a draft), but only UPLOADED to the CDN when this is ON. Default OFF —
  // admin turns it on PER PERSON via admin-overrides.json (set_setting,
  // audienceEmails: [that user]). When off, the pushed record carries
  // metadata + Step 1 answers + a marker that fills were withheld.
  try {
    eli.settings.register("build_draft.shareStep2FillsToCdn", {
      default: false,
      type: "boolean",
      storage: { type: "ls_blob_field", key: "eli_user_settings", field: "buildDraftShareStep2FillsToCdn" },
      adminPushable: true,
      describe: "Build Draft audit: upload Step 2 fill values (third-party names, amounts) to the shared CDN audit. OFF = fills stay local-only; metadata + Step 1 choices still upload. Admin enables per person.",
    });
  } catch (_e) {}
  // Require steps 1-3 before finishing (Save / Send). ON: if Logic, Fill, or
  // Error Review is incomplete when the user opens Step 4, warn them and let
  // them continue anyway (soft gate, not a hard block). A step that doesn't
  // apply to the template (no logic defs / no placeholders) is never required.
  // Admin-pushable so the requirement is enforced fleet-wide; flip OFF to
  // disable the warning entirely (kill switch).
  try {
    eli.settings.register("build_draft.requireAllSteps", {
      default: true,
      type: "boolean",
      storage: { type: "ls_blob_field", key: "eli_user_settings", field: "buildDraftRequireAllSteps" },
      adminPushable: true,
      describe: "Build Draft: warn before Save/Send if Logic, Fill, or Error Review wasn't completed (off = no warning). Only applicable steps are required.",
    });
  } catch (_e) {}
  // Guided mode for Step 1 logic — one question at a time with button
  // choices (left) and OARS/guidance context (right) instead of the
  // all-at-once dropdown form. Premium step-by-step UX.
  try {
    eli.settings.register("build_draft.guidedMode", {
      default: true,
      type: "boolean",
      storage: { type: "ls_blob_field", key: "eli_user_settings", field: "buildDraftGuidedMode" },
      adminPushable: true,
      describe: "Build Draft: step-by-step guided mode for Step 1 logic (one question at a time with button choices + OARS context). Off = classic all-at-once dropdown form.",
    });
  } catch (_e) {}
  // Filename patterns — admin-pushable so a single canonical naming
  // convention can be enforced fleet-wide via admin-overrides.json.
  // Tokens: [Ref] [Party] [Type] [Date]. Stored as flat top-level fields
  // on eli_user_settings (the settings registry doesn't support nested
  // paths). The previous nested location was eli_user_settings.
  // fileNamePatterns.{colgate,hills} — migration below preserves
  // existing user values.
  try {
    eli.settings.register("build_draft.fileNamePattern.colgate", {
      default: "[Ref] [Party] - [Type] (CP DRAFT [Date])",
      type: "string",
      storage: { type: "ls_blob_field", key: "eli_user_settings", field: "fileNamePatternColgate" },
      adminPushable: true,
      describe: "Build Draft: filename pattern for Colgate templates (tokens: [Ref] [Party] [Type] [Date])",
    });
  } catch (_e) {}
  try {
    eli.settings.register("build_draft.fileNamePattern.hills", {
      default: "[Ref] [Party] - [Type] (HPN DRAFT [Date])",
      type: "string",
      storage: { type: "ls_blob_field", key: "eli_user_settings", field: "fileNamePatternHills" },
      adminPushable: true,
      describe: "Build Draft: filename pattern for Hills templates (tokens: [Ref] [Party] [Type] [Date])",
    });
  } catch (_e) {}
  // One-time migration: nested fileNamePatterns.{colgate,hills} → flat
  // top-level fields. Idempotent — skips when flat fields already set.
  // Safe to run on every boot; the lsSet only fires when a copy happens.
  try {
    var _bdMigrRaw = eli.compat && eli.compat.lsGet ? eli.compat.lsGet("eli_user_settings") : null;
    var _bdMigrBlob = _bdMigrRaw ? JSON.parse(_bdMigrRaw) : {};
    var _bdMigrDirty = false;
    if (_bdMigrBlob && _bdMigrBlob.fileNamePatterns) {
      if (_bdMigrBlob.fileNamePatterns.colgate && _bdMigrBlob.fileNamePatternColgate == null) {
        _bdMigrBlob.fileNamePatternColgate = _bdMigrBlob.fileNamePatterns.colgate;
        _bdMigrDirty = true;
      }
      if (_bdMigrBlob.fileNamePatterns.hills && _bdMigrBlob.fileNamePatternHills == null) {
        _bdMigrBlob.fileNamePatternHills = _bdMigrBlob.fileNamePatterns.hills;
        _bdMigrDirty = true;
      }
    }
    if (_bdMigrDirty) eli.compat.lsSet("eli_user_settings", JSON.stringify(_bdMigrBlob));
  } catch (_e) {}
  var _bdReviewTrail = [];
  var _bdReviewIndex = 0;
  var _bdReviewSessionId = 0;
  function _bdReviewNavEnabled() {
    try { return eli.settings.get("build_draft.reviewNavigation") !== false; }
    catch (_e) { return true; }
  }
