      });
      return "";
    });
  }

  // === AI cache layer (FROM v2 PROMPTS.saveAICacheToDB / saveDocToDB) ===
  // Caches per-source AI extraction so re-opens skip the AI call. Keyed
  // by a content hash so cache bust is automatic when source text changes.
  // Stored in STORE_CONFIG with id "_bd_ai_cache_<hash>" — leading "_"
  // marks it as kernel-internal (skipped by tool listings).
  // 2026-05-19: deterministic template id from (agreementType, type, party).
  // Replaces the legacy "bd_doc_" + Date.now() scheme — that gave each save
  // a unique timestamp id, so admin pushes never UPSERTed into colleagues'
  // existing rows (different id every time). With this slug-based id every
  // re-save / cross-machine push of the same (agreementType, type, party)
  // tuple lands on the same id → IDB UPSERT replaces cleanly.
  //
  // Slug rules:
  //   - lowercase
  //   - all non-alphanumeric → "_"
  //   - collapse repeats, trim ends
  // So "Non-Disclosure Agreement", "non disclosure agreement", and
  // "Non  Disclosure  Agreement" all collapse to "non_disclosure_agreement"
  // — variants the user almost always means as the same template.
  function _bd_slug(s) {
    return String(s == null ? "" : s)
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, "_")
      .replace(/^_+|_+$/g, "")
      .replace(/_+/g, "_");
  }
  function _bd_templateId(agreementType, type, party) {
    return "bd_doc__" +
      (_bd_slug(agreementType) || "_") + "__" +
      (_bd_slug(type)          || "_") + "__" +
      (_bd_slug(party)         || "_");
  }
  // 2026-05-19: money formatter for placeholder values. OARS data ships
  // fees as raw numerics like "58925.0" — without this, that string goes
  // straight into the doc instead of "$58,925.00". Triggered on two
  // signals: explicit $-prefixed placeholders ($[ / $![) and plain
  // placeholders whose label contains money keywords (fee/payment/cost/
  // price/amount/usd/dollar). When the value parses as a pure number,
  // it's rendered with comma thousands separators + two decimals.
  function _bd_formatMoneyValue(raw) {
    var s = String(raw == null ? "" : raw).trim();
    if (!s) return null;
    var hadDollar = /^\$\s*/.test(s);
    s = s.replace(/^\$\s*/, "").replace(/,/g, "");
    // Must be a clean number; anything with letters/extra text → bail
    // (caller keeps raw value).
    if (!/^-?\d+(?:\.\d+)?$/.test(s)) return null;
    var n = parseFloat(s);
    if (!isFinite(n)) return null;
    var formatted = n.toLocaleString("en-US", {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2,
    });
    return { formatted: formatted, hadDollar: hadDollar };
  }
  function _bd_isLikelyMoneyPlaceholder(placeholder) {
    return /\b(fee|fees|payment|payments|cost|costs|price|amount|usd|dollar|dollars)\b/i.test(String(placeholder || ""));
  }
  function _bd_hashContent(text) {
    var s = String(text || "");
    var h = 0;
    for (var i = 0; i < s.length; i++) {
      h = ((h << 5) - h) + s.charCodeAt(i);
      h |= 0;
    }
    return "h" + (h >>> 0).toString(16);
  }

  function _bd_aiCacheKey(text) {
    return "_bd_ai_cache_" + _bd_hashContent(text);
  }

  function _bd_aiCacheGet(text) {
    var key = _bd_aiCacheKey(text);
    return eli.storage.get("config", key)
      .then(function (row) {
        if (row && row.value && Date.now() - (row.cachedAt || 0) < 7 * 24 * 60 * 60 * 1000) return row.value;
        return null;
      })
      .catch(function () { return null; });
  }

  function _bd_aiCachePut(text, value) {
    var key = _bd_aiCacheKey(text);
    // STORE_CONFIG's keyPath is "key" (kernel taskpane_v3.js:160) — NOT
    // "id" like every other store. The original v3 port wrote `{id: key,
    // ...}` which made every put throw "Evaluating the object store's
    // key path did not yield a value" and silently fail to cache. The
    // .catch swallowed the error so AI re-ran on every Step 2 click.
    return eli.storage.put("config", { key: key, value: value, cachedAt: Date.now() })
      .catch(function (e) {
        eli.log.event("tool", "build_draft_ai_cache_put_failed", { msg: e && e.message });
      });
  }

  // FROM v2 PROMPTS.runBackgroundAIAnalysis (line 1585). Pre-warms the
  // AI fill cache when OARS data loads so the user's Step 2 click is
  // instant. No-op if cache already populated for this content.
  function _runBackgroundAIAnalysis(sourceText) {
    if (!sourceText || sourceText.length < 50) return Promise.resolve(null);
    return _bd_aiCacheGet(sourceText).then(function (cached) {
      if (cached) {
        eli.log.event("tool", "build_draft_ai_prewarm_hit", {});
        return cached;
      }
      // Best-effort generic field extraction. The Step 2 fill flow uses
      // its own templateMap prompt for placeholder-specific mapping; this
      // pre-warms a broader field/data list for fast re-use.
      var prompt =
        "Analyze this document content.\n" +
        "TASK: Extract pairs of Field (Left) and Data (Right) from the document.\n" +
        "RETURN JSON ARRAY: [ { \"field\": \"...\", \"data\": \"...\" } ]\n" +
        "- Exclude rows where \"Data\" is empty.\n" +
        "- For tabular docs, Left col = Field, Right col = Data.\n\n" +
        "--- DOCUMENT ---\n" + sourceText;
      return eli.events.safeAsync(eli.ai.completeJSON(prompt, null, { maxTokens: 4000 }), "build_draft.prewarm")
        .then(function (json) {
          if (Array.isArray(json) && json.length) {
            return _bd_aiCachePut(sourceText, json).then(function () { return json; });
          }
          return null;
        })
        .catch(function (e) {
          eli.log.event("tool", "build_draft_ai_prewarm_failed", { msg: e && e.message });
          return null;
        });
    });
  }

  // FROM v2 persistAgreementState (line 14463). Saves type/name/details
  // into Office settings so future scans see the loaded state.
  function _persistAgreementState(name, type, details) {
    try {
      var s = (Office && Office.context && Office.context.document && Office.context.document.settings);
      if (!s) return Promise.resolve(false);
      if (name) s.set(SETTINGS_NAME, name);
      if (type) s.set(SETTINGS_TYPE, type);
      if (details) s.set(SETTINGS_DETAILS, details);
      return new Promise(function (resolve) {
        s.saveAsync(function () { resolve(true); });
      });
    } catch (e) {
      eli.log.event("tool", "build_draft_persist_failed", { msg: e && e.message });
      return Promise.resolve(false);
    }
  }

  // Full OARS clear: delegate to the eli_oars tool. After Batch 3 the
  // OARS hub owns the wipe + sentinel + bus emit + toast. If the tool
  // isn't installed (other team's deployment), build_draft just
  // best-effort wipes its own keys and moves on.
  function _clearAgreementState() {
    if (eli.get && typeof eli.get("oars", "clear") === "function") {
      eli.dispatch("oars", "clear");
      return Promise.resolve(true);
    }
    // Tool not installed — wipe what build_draft itself owns.
    try {
      var s = (Office && Office.context && Office.context.document && Office.context.document.settings);
      if (!s) return Promise.resolve(false);
      [SETTINGS_NAME, SETTINGS_TYPE, SETTINGS_DETAILS,
       "AgreementDataText", "AgreementDataSource"].forEach(function (k) {
        try { s.remove(k); } catch (e) {}
      });
      return new Promise(function (resolve) {
        s.saveAsync(function () { resolve(true); });
      });
    } catch (e) {
      eli.log.event("tool", "build_draft_clear_failed", { msg: e && e.message });
      return Promise.resolve(false);
    }
  }

  // FROM v2 showFileNameSettings → btnSaveActiveDoc (line 20852). Reads
  // body OOXML + per-section header/footer OOXML and bundles into a JSON
  // record for storage. Two short runRaw passes (body+sections, then
  // per-section HF) keep the budget tight on multi-section docs.
  function _captureActiveDocAsTemplate() {
    return eli.host.runRaw("build_draft:tpl_capture_body", function (context) {
      var doc = context.document;
      var bodyOoxml = doc.body.getOoxml();
      var sections = doc.sections;
      sections.load("items");
      return context.sync().then(function () {
        return { body: bodyOoxml.value, sectionCount: sections.items.length };
      });
    }).then(function (state) {
      // 2026-05-24: also capture custom XML parts so tools that persist
      // state outside the body (e.g. template_indexer's section metadata)
      // survive Build Draft round-trip. Captures every namespace so future
      // tools storing custom XML get persistence for free. Fail-open: if
      // the Office.js build doesn't expose namespaceUri or getXml on a
      // part, that part is skipped and the rest still round-trips.
      return eli.host.runRaw("build_draft:tpl_capture_xml", function (context) {
        var parts = context.document.customXmlParts;
        // Load both namespaceUri AND id so we can survive partial-API builds.
        parts.load("items/namespaceUri,items/id");
        return context.sync().then(function () {
          var items = parts.items || [];
          if (!items.length) return [];
          // Stage 1: queue getXml() per part with per-part try/catch.
          var xmlReqs = items.map(function (p) {
            var info = { ns: "", id: "", xmlReq: null, err: null };
            try { info.ns = p.namespaceUri || ""; } catch (e) { info.err = "ns:" + (e && e.message); }
            try { info.id = p.id || ""; } catch (e) { info.err = (info.err || "") + " id:" + (e && e.message); }
            try { info.xmlReq = p.getXml(); } catch (e) { info.err = (info.err || "") + " getXml:" + (e && e.message); }
            return info;
          });
          return context.sync().then(function () {
            var captured = xmlReqs.map(function (r) {
              return {
                namespaceUri: r.ns,
                xml: (r.xmlReq && r.xmlReq.value) || "",
                _err: r.err || null,
              };
            });
            // Log per-part outcome so we can debug Word-build-specific failures.
            try {
              eli.log.event("tool", "build_draft_tpl_capture_xml_result", {
                total: captured.length,
                withXml: captured.filter(function (c) { return c.xml; }).length,
                withErr: captured.filter(function (c) { return c._err; }).length,
                namespaces: captured.map(function (c) { return c.ns; }),
                errs: captured.filter(function (c) { return c._err; }).map(function (c) { return c._err; }),
              });
            } catch (_logErr) {}
