              var m = xml.match(/xmlns(?::[A-Za-z0-9]+)?\s*=\s*"([^"]+)"/);
              return m ? m[1] : "";
            }
            var filtered = captured
              .filter(function (e) { return e.xml; })
              .map(function (e) {
                var ns = e.namespaceUri || _nsFromXml(e.xml);
                return { namespaceUri: ns, xml: e.xml };
              })
              .filter(function (e) { return !WORD_BUILTIN_NS[e.namespaceUri]; });
            // Log post-filter so we know what actually got round-tripped.
            try {
              eli.log.event("tool", "build_draft_tpl_capture_xml_filtered", {
                kept: filtered.length,
                namespaces: filtered.map(function (e) { return e.namespaceUri || "(unknown)"; }),
              });
            } catch (_logErr) {}
            return filtered;
          });
        });
      }).then(function (customXmlParts) {
        state.customXmlParts = customXmlParts || [];
        return state;
      }).catch(function (e) {
        try {
          eli.log.event("tool", "build_draft_tpl_capture_xml_failed", {
            msg: e && e.message, stack: e && e.stack && String(e.stack).substring(0, 300),
          });
        } catch (_logErr) {}
        state.customXmlParts = [];
        state._customXmlCaptureError = e && e.message || String(e);
        return state;
      });
    }).then(function (state) {
      // Per-section HF capture, one runRaw per section.
      var sectionsData = [];
      var chain = Promise.resolve();
      for (var i = 0; i < state.sectionCount; i++) {
        (function (idx) {
          chain = chain.then(function () {
            return eli.host.runRaw("build_draft:tpl_capture_section_" + idx, function (context) {
              var sections = context.document.sections;
              sections.load("items");
              return context.sync().then(function () {
                if (idx >= sections.items.length) return null;
                var sec = sections.items[idx];
                var grabs = {
                  primaryH: sec.getHeader("Primary").getOoxml(),
                  firstPageH: sec.getHeader("FirstPage").getOoxml(),
                  evenPagesH: sec.getHeader("EvenPages").getOoxml(),
                  primaryF: sec.getFooter("Primary").getOoxml(),
                  firstPageF: sec.getFooter("FirstPage").getOoxml(),
                  evenPagesF: sec.getFooter("EvenPages").getOoxml(),
                };
                return context.sync().then(function () {
                  return {
                    index: idx,
                    headers: {
                      primary: grabs.primaryH.value || "",
                      firstPage: grabs.firstPageH.value || "",
                      evenPages: grabs.evenPagesH.value || "",
                    },
                    footers: {
                      primary: grabs.primaryF.value || "",
                      firstPage: grabs.firstPageF.value || "",
                      evenPages: grabs.evenPagesF.value || "",
                    },
                  };
                });
              });
            }).then(function (data) { if (data) sectionsData.push(data); });
          });
        })(i);
      }
      return chain.then(function () {
        return {
          body: state.body,
          sections: sectionsData,
          customXmlParts: state.customXmlParts || [],
          savedDate: new Date().toISOString(),
        };
      });
    });
  }

  // FROM v2 loadTemplateToWord (line 23762). Inserts a saved template
  // into the active doc. contentString is JSON ({body, sections}) for
  // full-fidelity OOXML templates, or plain text for legacy fallback.
  // Split into multiple short runRaw calls so each stays under 100ms:
  //   1.   Body OOXML insert
  //   2.   Per-section header/footer OOXML inserts (one runRaw per section)
  //   3a.  Body + tables font normalization
  //   3b.  Per-section H/F font normalization (one runRaw per section,
  //        all 3 HF types batched into 2 syncs vs 6)
  // 2026-05-21: skeleton-hybrid resolver state. Set during OARS auto-
  // launch (knows the detected agreement type) + manual-load paths.
  // Used by _resolveSkeleton at template-load time to pick the active
  // variant from &[…] boundaries.
  var _skeletonActiveVariant = null;
  function _setSkeletonVariant(name) {
    _skeletonActiveVariant = String(name || "").trim() || null;
  }

  // Feature-flag gate: skeleton resolution only runs when:
  //   1. The user is on the admin allowlist (same emails as clause_library)
  //   2. AND the user has explicitly opted in via
  //      eli_user_settings.enableSkeletonResolver
  // BOTH conditions required — non-admin colleagues can't accidentally
  // enable the feature even if their settings blob has the flag set
  // (e.g., from copying a settings file or future bundle override).
  // The settings UI for the toggle is also audience-gated separately in
  // tools/eli_settings/init.js so non-admins never see the toggle.
  // 2026-05-21: narrowed to a single admin while the skeleton system
  // stabilises. Mirrors clause_library's ALLOWED list — keep these
  // two arrays in sync (both gates need to pass for the workflow to
  // function end-to-end).
  var _SKELETON_ALLOWED_EMAILS = {
    "andrew_nemiroff@colpal.com": 1,
  };
  function _skeletonResolverEnabled() {
    try {
      var ident = (eli.tools && typeof eli.tools.userIdentity === "function") ? eli.tools.userIdentity() : {};
      var email = String((ident && ident.email) || "").toLowerCase().trim();
      if (!_SKELETON_ALLOWED_EMAILS[email]) return false;
      var raw = eli.compat && eli.compat.lsGet("eli_user_settings");
      if (!raw) return false;
      var s = JSON.parse(raw);
      return s && s.enableSkeletonResolver === true;
    } catch (_e) { return false; }
  }

  function _hasSkeletonMarkers(bodyContent) {
    // 2026-05-21 fix: OOXML body strings have XML-escaped ampersands —
    // a user-typed `&[Mutual NDA]` is stored as `&amp;[Mutual NDA]` in
    // the raw body OOXML string. Match BOTH forms here at the detection
    // gate (the DOMParser path inside _resolveSkeleton decodes entities
    // to textContent, so the regex inside the resolver works on the
    // decoded `&[…]` form).
    var s = String(bodyContent || "");
    return /&\[[^\]]+\]/.test(s) || /&amp;\[[^\]]+\]/.test(s);
  }

  // Lookup clauses via the registered dispatch channel (clause_library
  // tool registers `clauses.lookup`). Returns null if the tool isn't
  // installed OR no matching clause exists.
  function _lookupClauseAsync(name, variant) {
    try {
      var fn = eli.get && eli.get("clauses", "lookup");
      if (typeof fn !== "function") return Promise.resolve(null);
      return Promise.resolve(fn(name, variant)).catch(function () { return null; });
    } catch (_e) { return Promise.resolve(null); }
  }

  // Skeleton resolution — operates on the body OOXML string from a
  // captured template. Returns a Promise resolving to the resolved
  // OOXML (with &[…] boundaries consumed + #[…] clause refs replaced).
  // Uses DOMParser for namespace-correct XML manipulation. If parsing
  // fails (or DOMParser unavailable), returns the input unchanged so
  // the load can proceed — fail-open, never block.
  function _resolveSkeleton(bodyOoxml, detectedType, opts) {
    opts = opts || {};
    if (typeof DOMParser === "undefined") return Promise.resolve(bodyOoxml);
    var parser, xmlDoc;
    try {
      parser = new DOMParser();
      xmlDoc = parser.parseFromString(bodyOoxml, "text/xml");
      if (xmlDoc.getElementsByTagName("parsererror").length) {
        eli.log.event("tool", "build_draft_skeleton_xml_parse_failed", {});
        return Promise.resolve(bodyOoxml);
      }
    } catch (_e) {
      return Promise.resolve(bodyOoxml);
    }
    var W_NS = "http://schemas.openxmlformats.org/wordprocessingml/2006/main";
    // Use getElementsByTagName with the w: prefix (Flat OPC documents
    // declare the prefix at the root). NS-aware lookup would also work
    // but adds complexity around namespace prefix discovery.
    var allParas = Array.prototype.slice.call(xmlDoc.getElementsByTagName("w:p"));
