    var variantsSeen = []; // for logging: [{variant, paraIdx}]
    var currentVariant = detectedType ? String(detectedType).trim() : null;
    var partialMarkerParas = []; // [{ para, markerText, variant }] for marker-text stripping
    var paraVariant = new Array(allParas.length); // variant active when this paragraph is processed
    // 2026-05-21 v4: find &[…] markers ANYWHERE in the paragraph (not
    // just at the start). Common case: `{{ELSE }}&[Variant]content…`
    // where the marker comes AFTER an IF/ELSE token. Word also often
    // autocorrects `-` to en-dash `–` inside the brackets — that's
    // handled at lookup-time by _normalizeVariant.
    allParas.forEach(function (p, idx) {
