    // rsid tagging) so _stripTextFromParagraph handles both single-<w:t>
    // and split-across-<w:t> cases.
    //
    // 2026-05-21: opts.keepVariantMarkers=true skips this step entirely.
    // Used by Skeleton Workshop's "Load + Resolve" mode — the user
    // wants clauses inlined for editing but the &[…] markers visible
    // so they can see variant boundaries (and so the workshop can use
    // those markers for variant detection when extracting clauses back).
    if (!opts.keepVariantMarkers) {
      partialMarkerParas.forEach(function (entry) {
        _stripTextFromParagraph(entry.para, entry.markerText);
      });
    }
    // 2026-05-21 v3: collect unique (name, variant) PAIRS — same name
    // can be looked up under DIFFERENT variants depending on which
    // `&[…]` was most recent at that point in the doc.
    // survivingParas == allParas because we no longer delete anything;
    // re-fetch via DOM query so it includes any post-strip changes.
    var survivingParas = Array.prototype.slice.call(xmlDoc.getElementsByTagName("w:p"));
    if (!survivingParas.length) survivingParas = Array.prototype.slice.call(xmlDoc.getElementsByTagNameNS(W_NS, "p"));
    var uniquePairs = {};   // key = name + "::" + (variant || "")  → {name, variant}
    var paraClauseHits = []; // [{para, variant}] in document order for substitution pass
    survivingParas.forEach(function (p, idx) {
      var v = paraVariant[idx] || currentVariant || null;
      paraClauseHits.push({ para: p, variant: v });
