      // For each <w:p> containing a #[name] token:
      //   - PLAIN clause: replace #[name] text in its containing <w:t>
      //     with the clause body. Multi-paragraph (\n\n) splits into
      //     additional <w:p> elements inserted after.
      //   - OOXML clause: replace the entire <w:p> with the clause's
      //     OOXML fragment (parsed + inserted).
      // Per-paragraph substitution. For each paragraph, look up its
      // active variant from paraClauseHits + use that variant in the
      // clauseMap key.
      paraClauseHits.forEach(function (hit) {
        var p = hit.para;
        var paraVar = hit.variant;
        var tElements = Array.prototype.slice.call(p.getElementsByTagName("w:t"));
        if (!tElements.length) tElements = Array.prototype.slice.call(p.getElementsByTagNameNS(W_NS, "t"));
        var paraText = p.textContent || "";
        if (!/#\[[^\]]+\]/.test(paraText)) return;
        // For each placeholder in this para's text:
        var re = /#\[([^\]]+)\]/g;
        var matches = [];
        var m;
        while ((m = re.exec(paraText)) !== null) {
          matches.push({ raw: m[0], name: m[1].trim() });
        }
        matches.forEach(function (mm) {
          var lookupKey = mm.name + "::" + (paraVar || "");
          var clause = clauseMap[lookupKey];
          if (!clause) return; // leave placeholder visible as missing marker
          if (clause.format === "ooxml") {
            // 2026-05-21 v3: range.getOoxml() returns a Flat OPC package:
            //   <?xml?><?mso-application?>
            //   <pkg:package>
            //     <pkg:part name="/word/document.xml">
            //       <pkg:xmlData>
            //         <w:document>
            //           <w:body>
            //             <w:p>…</w:p>  ← THIS is what we need to splice
            //             <w:sectPr>…</w:sectPr>  ← MUST be dropped (host
            //                                       doc owns section props)
            //           </w:body>
            //         </w:document>
            //       </pkg:xmlData>
            //     </pkg:part>
            //   </pkg:package>
            // Splicing the <pkg:package> envelope (or even <w:document>)
            // into <w:body> makes Word reject with GeneralException.
            // We must extract <w:body>'s direct paragraph-level children
            // (<w:p>, <w:tbl>, <w:sdt>) and splice ONLY those, dropping
            // <w:sectPr> which conflicts with the host doc's section.
            try {
              var parseInput = String(clause.body || "");
              // For non-package inputs (raw <w:p>...</w:p> fragments —
              // shouldn't happen with current capture but be defensive),
              // wrap in <root> with the w: namespace declared.
              var looksLikePackage = /<pkg:package|<w:document|<w:body/.test(parseInput);
              var frag;
              if (looksLikePackage) {
                frag = parser.parseFromString(parseInput, "text/xml");
              } else {
                frag = parser.parseFromString(
                  '<root xmlns:w="' + W_NS + '">' + parseInput + '</root>',
                  "text/xml"
                );
              }
              // Find <w:body> (may be at any depth inside the package).
              var bodyEls = frag.getElementsByTagName("w:body");
              if (!bodyEls.length) bodyEls = frag.getElementsByTagNameNS(W_NS, "body");
              var sourceContainer;
              if (bodyEls.length) {
                sourceContainer = bodyEls[0];
              } else {
                // Raw fragment path — container is the synthetic <root>.
                sourceContainer = frag.documentElement;
              }
              var paraTags = ["w:p", "w:tbl", "w:sdt"];
              var newParas = [];
              for (var ci = 0; ci < sourceContainer.childNodes.length; ci++) {
                var node = sourceContainer.childNodes[ci];
                if (node.nodeType !== 1) continue;
                // Drop <w:sectPr> — section props are owned by the host doc.
                if (node.nodeName === "w:sectPr") continue;
                // Accept paragraph-level structural elements; skip anything
                // else (sectPr fallback for namespaced lookups, comments,
                // bookmarks at body level, etc.).
                if (paraTags.indexOf(node.nodeName) !== -1 ||
                    paraTags.indexOf(node.localName ? ("w:" + node.localName) : "") !== -1) {
                  newParas.push(node);
                }
              }
              if (!newParas.length) {
                eli.log.event("tool", "build_draft_skeleton_ooxml_clause_empty", {
                  name: mm.name, bodyLen: parseInput.length,
                });
                return;
              }
              // Strip orphaning hazards from the inserted paragraphs:
              // bookmark/comment/proof markers carry IDs that conflict
              // with the host doc's existing IDs after splicing.
              newParas.forEach(function (np) {
                _stripOrphanMarkers(np);
              });
              // 2026-05-21: skeleton-sets-layout, clause-provides-content.
              // The host paragraph is the placeholder line in the skeleton
              // template — it carries the intended paragraph properties
              // (first-line indent, hanging indent, alignment, numbering,
              // pStyle). The clause was captured from a sub-paragraph
              // selection, so its <w:pPr> often comes back minimal or
              // empty (range.getOoxml on a text-only selection drops
              // <w:ind>). Layer host's <w:pPr> as the BASE on the first
              // spliced paragraph, with the clause's own <w:pPr> children
              // overriding only what they explicitly set. Subsequent
              // spliced paragraphs keep their own structure (the clause
              // owns its multi-para layout). Run-level character formatting
              // (bold / italic / font / size in <w:rPr>) is always
              // preserved — it lives inside <w:r>, not <w:pPr>.
              var hostPPrForSplice = p.getElementsByTagName("w:pPr")[0] ||
                                     p.getElementsByTagNameNS(W_NS, "pPr")[0];
              if (hostPPrForSplice && newParas.length) {
                _mergeHostPPrIntoFirst(newParas[0], hostPPrForSplice);
              }
              if (p.parentNode) {
                var ref = p.nextSibling;
                newParas.forEach(function (np) {
                  var imported = xmlDoc.importNode(np, true);
                  p.parentNode.insertBefore(imported, ref);
                });
                p.parentNode.removeChild(p);
              }
            } catch (_e) {
              eli.log.event("tool", "build_draft_skeleton_ooxml_clause_parse_failed", {
                name: mm.name, msg: _e && _e.message,
              });
            }
            return;
          }
          // PLAIN clause: substitute the #[name] text inside the para.
          // Multi-paragraph clauses (\n\n) get the first para inline +
          // additional <w:p> elements inserted after the host.
          //
          // 2026-05-21 v2: two-stage substitution. Stage 1 tries the
          // fast path — look for the FULL marker text inside a single
          // <w:t> element (preserves all surrounding run formatting).
          // Stage 2 fallback handles the split-marker case (Word's
          // spell-check / autocorrect / smart-quote frequently splits
          // text mid-marker across runs like
          // `<w:r><w:t>#[Obj</w:t></w:r><w:r><w:t>ective]</w:t></w:r>`).
          // The fallback collapses all runs in the paragraph into a
          // single run with the substituted text — loses mixed inline
          // formatting but guarantees the substitution actually lands.
          var paras = String(clause.body || "").split(/\n{2,}/);
          var firstPara = paras[0] || "";
          var substituted = false;
          for (var ti = 0; ti < tElements.length; ti++) {
            var t = tElements[ti];
            var current = t.textContent || "";
            var idx = current.indexOf(mm.raw);
            if (idx === -1) continue;
            // 2026-05-21 v3: split the host run into three runs:
            //   1. before-marker text — keeps original rPr (header styling)
            //   2. replacement text   — fresh rPr with underline/bold/italic
            //                           explicitly disabled (body styling)
            //   3. after-marker text  — keeps original rPr
            // Required because Word commonly merges adjacent runs on
            // template save: a "1.1 Trade Secrets. #[Trade Secrets]"
            // line saved with carve-time underline=none on the marker
            // run gets coalesced into ONE underlined run. Without the
            // split, the substituted clause body inherits the heading's
            // underline. With the split, the header keeps its underline
            // and the substituted body comes out plain.
            _splitRunAndStripHeadingFormat(t, mm.raw, firstPara);
            substituted = true;
            break;
          }
          // Stage 2: fallback — marker was split across multiple <w:t>
          // elements (Word's spell-check / autocorrect frequently splits
          // runs mid-marker). Walk the runs, find which runs hold the
          // marker text, replace that span with a single body-formatted
          // run. Runs BEFORE the marker keep their formatting (so the
          // section header stays underlined). Runs AFTER keep theirs.
          //
          // 2026-05-21 v3: previously this collapsed the WHOLE paragraph
          // into a single run with the first run's rPr — which inherited
          // the header's underline onto the substituted clause body. Now
          // we surgically replace only the marker-spanning runs.
          if (!substituted) {
            var joinedText = p.textContent || "";
            var fullIdx = joinedText.indexOf(mm.raw);
            if (fullIdx !== -1) {
              var markerEnd = fullIdx + mm.raw.length;
              // Walk runs in document order, accumulating character offsets.
              // Identify the runs whose text intersects [fullIdx, markerEnd).
              var allRuns = Array.prototype.slice.call(p.getElementsByTagName("w:r"));
              if (!allRuns.length) allRuns = Array.prototype.slice.call(p.getElementsByTagNameNS(W_NS, "r"));
              var runOffsets = [];
              var pos = 0;
              for (var ri = 0; ri < allRuns.length; ri++) {
                var rtext = allRuns[ri].textContent || "";
                runOffsets.push({ run: allRuns[ri], start: pos, end: pos + rtext.length, text: rtext });
                pos += rtext.length;
              }
              // First/last run whose range overlaps the marker span.
              var firstOverlap = -1, lastOverlap = -1;
              for (var oi = 0; oi < runOffsets.length; oi++) {
                var ro = runOffsets[oi];
                if (ro.end <= fullIdx) continue;        // entirely before marker
                if (ro.start >= markerEnd) break;        // entirely after marker
                if (firstOverlap === -1) firstOverlap = oi;
                lastOverlap = oi;
              }
              if (firstOverlap === -1) {
                // Couldn't locate — give up. Will leave marker visible.
                eli.log.event("tool", "build_draft_skeleton_split_marker_locate_failed", {
                  clause: mm.name, joinedLen: joinedText.length,
                });
              } else {
                // Compute leftover text on the first/last overlapping runs:
                //   firstRun's text BEFORE the marker → keep with first run's rPr
                //   lastRun's text AFTER the marker → keep with last run's rPr
                var firstRun2 = runOffsets[firstOverlap];
                var lastRun2  = runOffsets[lastOverlap];
                var beforeText = firstRun2.text.slice(0, fullIdx - firstRun2.start);
                var afterText  = lastRun2.text.slice(markerEnd - lastRun2.start);
                // Capture rPrs from first/last overlap runs.
                function _getRPr(rNode) {
                  var e = rNode.getElementsByTagName("w:rPr")[0] ||
                          rNode.getElementsByTagNameNS(W_NS, "rPr")[0];
                  return e ? e.cloneNode(true) : null;
                }
                var firstRPr2 = _getRPr(firstRun2.run);
                var lastRPr2  = _getRPr(lastRun2.run);
                // Build replacement nodes:
                //   1. <w:r rPr=firstRPr><w:t>beforeText</w:t></w:r>   (if non-empty)
                //   2. <w:r rPr=firstRPr+stripFmt><w:t>firstPara</w:t></w:r>
                //   3. <w:r rPr=lastRPr><w:t>afterText</w:t></w:r>     (if non-empty)
                function _mkRunWithRPr(text, baseRPr, stripFmt) {
                  var r = xmlDoc.createElementNS(W_NS, "w:r");
                  if (baseRPr) {
                    var rp = baseRPr.cloneNode(true);
                    if (stripFmt) {
                      _setRPrFlagOnNode(xmlDoc, rp, "w:u", "none");
                      _setRPrFlagOnNode(xmlDoc, rp, "w:b", "0");
                      _setRPrFlagOnNode(xmlDoc, rp, "w:i", "0");
                    }
                    r.appendChild(rp);
                  } else if (stripFmt) {
                    var fmt = xmlDoc.createElementNS(W_NS, "w:rPr");
                    _setRPrFlagOnNode(xmlDoc, fmt, "w:u", "none");
                    _setRPrFlagOnNode(xmlDoc, fmt, "w:b", "0");
                    _setRPrFlagOnNode(xmlDoc, fmt, "w:i", "0");
                    r.appendChild(fmt);
                  }
                  var tt = xmlDoc.createElementNS(W_NS, "w:t");
                  tt.setAttributeNS("http://www.w3.org/XML/1998/namespace", "xml:space", "preserve");
                  tt.textContent = text;
                  r.appendChild(tt);
                  return r;
                }
                var insertAnchor = firstRun2.run;
                if (beforeText) p.insertBefore(_mkRunWithRPr(beforeText, firstRPr2, false), insertAnchor);
                p.insertBefore(_mkRunWithRPr(firstPara, firstRPr2, true), insertAnchor);
                if (afterText) p.insertBefore(_mkRunWithRPr(afterText, lastRPr2, false), insertAnchor);
                // Remove all overlapping runs.
                for (var ri2 = firstOverlap; ri2 <= lastOverlap; ri2++) {
                  var rNode = runOffsets[ri2].run;
                  if (rNode.parentNode) rNode.parentNode.removeChild(rNode);
                }
                substituted = true;
                eli.log.event("tool", "build_draft_skeleton_split_marker_fixed", {
                  clause: mm.name,
                  spannedRuns: lastOverlap - firstOverlap + 1,
                  beforeLen: beforeText.length,
                  afterLen: afterText.length,
                });
              }
            }
          }
          // Additional paragraphs (multi-para plain clause body) —
          // clone the host paragraph for formatting inheritance, set
          // text content. Same logic regardless of which stage above
          // performed the inline substitution.
          //
          // 2026-05-21 fix: cloneNode(true) deep-clones EVERYTHING
          // inside the host <w:p>, including bookmark/comment/proof
          // markers. Those carry IDs that must be unique within the
          // document — duplicated IDs from the clone make Word reject
          // the spliced doc with GeneralException. We rebuild each
          // clone from scratch keeping ONLY <w:pPr> (paragraph
          // properties: alignment, indent, style) — no <w:r> children,
          // no bookmark/comment/proof markers, no orphan-prone refs.
          if (substituted && paras.length > 1) {
            var insertAfter = p;
            var hostPPr = p.getElementsByTagName("w:pPr")[0] ||
                          p.getElementsByTagNameNS(W_NS, "pPr")[0];
            for (var pp = 1; pp < paras.length; pp++) {
              var clone = xmlDoc.createElementNS(W_NS, "w:p");
              if (hostPPr) clone.appendChild(hostPPr.cloneNode(true));
              var newR2 = xmlDoc.createElementNS(W_NS, "w:r");
              var newT2 = xmlDoc.createElementNS(W_NS, "w:t");
              if (newT2.setAttributeNS) {
                newT2.setAttributeNS("http://www.w3.org/XML/1998/namespace", "xml:space", "preserve");
              }
              newT2.textContent = paras[pp];
              newR2.appendChild(newT2);
              clone.appendChild(newR2);
              if (insertAfter.parentNode) {
                insertAfter.parentNode.insertBefore(clone, insertAfter.nextSibling);
              }
              insertAfter = clone;
            }
          }
        });
      });
      eli.log.event("tool", "build_draft_skeleton_resolved", {
        pairCount: pairs.length,
        resolved: pairs.length - missing.length,
        missing: missing,
      });
      // 2026-05-21: post-resolve output validation. If our manipulations
      // produced malformed OOXML, Word.js insertOoxml throws an opaque
      // GeneralException. Round-trip-parse our output to catch breakage
      // BEFORE handing to Word — fall back to source body so the load
      // succeeds (with markers still visible, but no crash). Also stash
      // the failing output to window for inspection.
      var serialized = _serializeXml(xmlDoc);
      var validateParser = new DOMParser();
      var validateDoc = validateParser.parseFromString(serialized || "", "text/xml");
      var parseErrors = validateDoc.getElementsByTagName("parsererror");
      if (parseErrors.length || !serialized) {
        var errText = parseErrors[0] ? parseErrors[0].textContent : "empty serialization";
        eli.log.event("tool", "build_draft_skeleton_output_invalid", {
          parserError: String(errText).substring(0, 300),
          serializedLength: (serialized || "").length,
        });
        try {
          window.__bdSkeletonLastBadOutput = serialized || "";
          console.warn("[build_draft] Skeleton resolver produced invalid OOXML — falling back to source. Bad output stashed at window.__bdSkeletonLastBadOutput for inspection.");
        } catch (_e) {}
        return bodyOoxml; // fall back to original source
      }
      try {
        window.__bdSkeletonLastResolved = serialized;
        eli.log.event("tool", "build_draft_skeleton_output_ok", {
          serializedLength: serialized.length,
        });
      } catch (_e) {}
      return serialized;
    });
  }

  // 2026-05-21: bisection helper. When Word rejects insertOoxml with
  // GeneralException despite our DOMParser validation passing, the
  // user can call `window.__bdSkeletonBisect()` in the console. It
  // walks the resolved <w:body> in halves, sending each half to
  // insertOoxml until it finds the smallest range that fails. Logs
  // the failing paragraph indices + a snippet of the offending OOXML
  // so we can see exactly what Word rejected. Read-only diagnostic —
  // it does NOT alter the actual document state on success (clones
  // the doc, swaps body, restores after).
  window.__bdSkeletonBisect = function () {
    var src = window.__bdSkeletonLastResolved || window.__bdSkeletonLastBadOutput;
    if (!src) {
      console.warn("[bd] no resolver output stashed; load a skeleton template first.");
      return;
    }
    if (typeof DOMParser === "undefined" || typeof Word === "undefined") {
      console.warn("[bd] DOMParser or Word.js not available.");
      return;
    }
    // Helper: build a minimal Flat OPC package containing only the
    // given <w:p>/<w:tbl> elements, preserving the source's root
    // namespace declarations + the <w:sectPr> from the source body.
    var docParse = new DOMParser().parseFromString(src, "text/xml");
    var srcBody = docParse.getElementsByTagName("w:body")[0];
    if (!srcBody) { console.warn("[bd] resolved output has no <w:body>"); return; }
    var allKids = Array.prototype.slice.call(srcBody.childNodes).filter(function (n) {
      return n.nodeType === 1;
    });
    var sectPr = null;
    var paras = allKids.filter(function (n) {
      if (n.nodeName === "w:sectPr") { sectPr = n; return false; }
      return true;
    });
    console.log("[bd] bisect: total paragraph-level elements =", paras.length);
    // Build a sub-document by selecting [start, end) of paras + the
    // body's sectPr. Wraps in the original package structure.
    function buildSub(start, end) {
      var clone = docParse.cloneNode(true);
      var body = clone.getElementsByTagName("w:body")[0];
      while (body.firstChild) body.removeChild(body.firstChild);
      for (var i = start; i < end; i++) {
        body.appendChild(clone.importNode(paras[i], true));
      }
      if (sectPr) body.appendChild(clone.importNode(sectPr, true));
      var out = new XMLSerializer().serializeToString(clone);
      return out.replace(/\?>\s*<\?/g, "?>\r\n<?")
                .replace(/\?>\s*<pkg:package/g, "?>\r\n<pkg:package");
    }
    function tryInsert(start, end) {
      var ooxml = buildSub(start, end);
      return Word.run(function (ctx) {
        ctx.document.body.insertOoxml(ooxml, Word.InsertLocation.replace);
        return ctx.sync().then(function () { return true; });
      }).catch(function (e) {
        return { error: String(e && e.message || e) };
      });
    }
    // Iterative binary search: find the smallest contiguous range
    // [start, end) within [0, paras.length) that still fails.
    function bisect(lo, hi) {
      if (hi - lo <= 1) {
        return tryInsert(lo, hi).then(function (r) {
          if (r === true) {
            console.log("[bd] paragraph", lo, "loads OK individually.");
            return { ok: true };
          }
          console.error("[bd] FOUND OFFENDING PARAGRAPH", lo, "→", r.error);
          var snippet = new XMLSerializer().serializeToString(paras[lo]);
          console.error("[bd] paragraph", lo, "OOXML (first 500 chars):", snippet.substring(0, 500));
          return { ok: false, index: lo, snippet: snippet };
        });
      }
      var mid = Math.floor((lo + hi) / 2);
      return tryInsert(lo, mid).then(function (r) {
        if (r !== true) {
          console.log("[bd] left half [", lo, ",", mid, ") fails — recursing");
          return bisect(lo, mid);
        }
        return tryInsert(mid, hi).then(function (r2) {
          if (r2 !== true) {
            console.log("[bd] right half [", mid, ",", hi, ") fails — recursing");
            return bisect(mid, hi);
          }
          console.log("[bd] both halves OK on their own but full range fails — overlap issue at boundary", mid);
          return tryInsert(lo, hi).then(function (r3) {
            if (r3 === true) return { ok: true };
            return { ok: false, boundary: mid, error: r3.error };
          });
        });
      });
    }
    return bisect(0, paras.length).then(function (result) {
      console.log("[bd] bisect complete:", result);
      return result;
    });
  };

  function _serializeXml(xmlDoc) {
    try {
      if (typeof XMLSerializer !== "undefined") {
        var out = new XMLSerializer().serializeToString(xmlDoc);
        // 2026-05-21 fix: XMLSerializer strips whitespace between
        // processing instructions in the document preamble. Word's
        // OOXML parser is stricter than DOMParser and rejects the
        // glued-together `<?xml?><?mso-application?><pkg:package>`
        // form with GeneralException. Restore CRLF separators at
        // PI boundaries to match Word's expected Flat OPC format.
        out = out.replace(/\?>\s*<\?/g, "?>\r\n<?");
        // Also: ensure a CRLF after the last PI before the root element
        // (most commonly `<?mso-application?>` followed immediately
        // by `<pkg:package>`).
        out = out.replace(/\?>\s*<pkg:package/g, "?>\r\n<pkg:package");
        return out;
      }
    } catch (_e) {}
    return null;
  }

  // 2026-05-21: strip elements whose IDs must be unique across the
  // document. When we splice cloned/imported paragraphs into the
  // host body, any bookmark/comment/proof markers carrying numeric
  // IDs from the source doc will collide with the host's existing
  // IDs (or simply reference endpoints that don't exist), making
  // Word reject insertOoxml with GeneralException. This list covers
  // the markers we've actually seen cause rejections; add more as
  // we encounter them. We strip in-place via parent.removeChild so
  // surrounding runs / formatting are untouched.
  // 2026-05-21: set or update a w:val attribute on an <w:rPr> child
  // element (e.g. <w:u>, <w:b>, <w:i>). Used by both the stage 1 single-
  // <w:t> substitution and the stage 2 split-marker fallback in the
  // skeleton resolver. CRITICAL: use setAttributeNS, NOT setAttribute,
  // because w:val is in the wordprocessingml namespace — plain
  // setAttribute creates a literal-named attribute Word silently
  // ignores.
  function _setRPrFlagOnNode(doc, rPr, tagName, val) {
    var W_NS = "http://schemas.openxmlformats.org/wordprocessingml/2006/main";
    var existing = null;
    for (var k = 0; k < rPr.childNodes.length; k++) {
      var ch = rPr.childNodes[k];
      if (ch.nodeType !== 1) continue;
      var localTag = ch.localName ? ("w:" + ch.localName) : ch.nodeName;
      if (ch.nodeName === tagName || localTag === tagName) {
        existing = ch; break;
      }
    }
    if (existing) {
      existing.setAttributeNS(W_NS, "w:val", val);
    } else {
      var newEl = doc.createElementNS(W_NS, tagName);
      newEl.setAttributeNS(W_NS, "w:val", val);
      rPr.appendChild(newEl);
    }
  }

  // 2026-05-21: split a host run on a marker substring, applying
  // body-text formatting (underline=none, bold=0, italic=0) to ONLY
  // the replacement portion. Header text before the marker keeps its
  // original rPr; trailing text after the marker keeps it too. Lets
  // the resolver substitute plain-clause text into a heading-style
  // paragraph without dragging the heading's underline/bold/italic
  // through to the substituted body.
  //
  // Layout:
  //   <w:r rPr=ORIGINAL><w:t>before#[Marker]after</w:t></w:r>
  // becomes:
  //   <w:r rPr=ORIGINAL><w:t>before</w:t></w:r>           [if before]
  //   <w:r rPr=ORIGINAL+strip><w:t>REPLACEMENT</w:t></w:r>
  //   <w:r rPr=ORIGINAL><w:t>after</w:t></w:r>            [if after]
  //
  // The strip overlay adds explicit <w:u w:val="none"/>,
  // <w:b w:val="0"/>, <w:i w:val="0"/> to the replacement run's rPr.
  // Font/size/color from ORIGINAL pass through untouched (we want
  // the body to inherit the host paragraph's font, not force a
  // default — otherwise body text could end up in a stray default
  // font that doesn't match the doc).
  function _splitRunAndStripHeadingFormat(t, markerText, replacement) {
    var current = t.textContent || "";
    var idx = current.indexOf(markerText);
    if (idx === -1) return false;
    var W_NS = "http://schemas.openxmlformats.org/wordprocessingml/2006/main";
    var doc = t.ownerDocument;
    var run = t.parentNode;
    if (!run || !run.parentNode) return false;
    var parent = run.parentNode;
    var before = current.slice(0, idx);
    var after  = current.slice(idx + markerText.length);
    // Find the run's existing rPr (may be missing if the run has no
    // explicit formatting — properties inherited from pStyle/docDefaults).
    var origRPr = null;
    for (var ci = 0; ci < run.childNodes.length; ci++) {
      var c = run.childNodes[ci];
      if (c.nodeType !== 1) continue;
      if (c.nodeName === "w:rPr" || c.localName === "rPr") { origRPr = c; break; }
    }
    function _mkRun(text, baseRPr, stripFmt) {
      var r = doc.createElementNS(W_NS, "w:r");
      if (baseRPr) {
        var rp = baseRPr.cloneNode(true);
        if (stripFmt) {
          _setRPrFlagOnNode(doc, rp, "w:u", "none");
          _setRPrFlagOnNode(doc, rp, "w:b", "0");
          _setRPrFlagOnNode(doc, rp, "w:i", "0");
        }
        r.appendChild(rp);
      } else if (stripFmt) {
        var fmtRPr = doc.createElementNS(W_NS, "w:rPr");
        _setRPrFlagOnNode(doc, fmtRPr, "w:u", "none");
        _setRPrFlagOnNode(doc, fmtRPr, "w:b", "0");
        _setRPrFlagOnNode(doc, fmtRPr, "w:i", "0");
        r.appendChild(fmtRPr);
      }
      var tEl = doc.createElementNS(W_NS, "w:t");
      tEl.setAttributeNS("http://www.w3.org/XML/1998/namespace", "xml:space", "preserve");
      tEl.textContent = text;
      r.appendChild(tEl);
      return r;
    }
    if (before) parent.insertBefore(_mkRun(before, origRPr, false), run);
    parent.insertBefore(_mkRun(replacement, origRPr, true), run);
    if (after) parent.insertBefore(_mkRun(after, origRPr, false), run);
    parent.removeChild(run);
    return true;
  }

  function _stripOrphanMarkers(node) {
    if (!node || node.nodeType !== 1) return;
    var killTags = [
      "w:bookmarkStart", "w:bookmarkEnd",
      "w:commentRangeStart", "w:commentRangeEnd", "w:commentReference",
      "w:proofErr",
      "w:moveFromRangeStart", "w:moveFromRangeEnd",
      "w:moveToRangeStart", "w:moveToRangeEnd",
      "w:customXmlInsRangeStart", "w:customXmlInsRangeEnd",
      "w:customXmlDelRangeStart", "w:customXmlDelRangeEnd",
    ];
    killTags.forEach(function (tag) {
      var els = Array.prototype.slice.call(node.getElementsByTagName(tag));
      els.forEach(function (e) { if (e.parentNode) e.parentNode.removeChild(e); });
    });
  }

  // 2026-05-21: layer host paragraph's <w:pPr> as base properties onto
  // a spliced paragraph (the first one in an OOXML clause splice). For
  // each property element in host's pPr (e.g. <w:ind>, <w:jc>, <w:numPr>,
  // <w:pStyle>, <w:spacing>), if the spliced para doesn't already have
  // that property, inject host's copy. Result: skeleton's intended
  // layout sticks unless the clause explicitly overrides it.
  //
  // Why this is needed: range.getOoxml() on a sub-paragraph selection
  // (the common capture case) emits a minimal <w:pPr> that frequently
  // omits <w:ind>. Without this merge, captured clauses splice in with
  // no first-line indent / hanging indent / list numbering, even though
  // the skeleton placeholder paragraph had them set.
  function _mergeHostPPrIntoFirst(splicedPara, hostPPr) {
    if (!splicedPara || !hostPPr) return;
    var W_NS = "http://schemas.openxmlformats.org/wordprocessingml/2006/main";
    // Find (or create) the spliced paragraph's <w:pPr>.
    var splicedPPr = splicedPara.getElementsByTagName("w:pPr")[0] ||
                     splicedPara.getElementsByTagNameNS(W_NS, "pPr")[0];
    if (!splicedPPr) {
      // Build a fresh pPr and insert as first child of the paragraph
      // (OOXML requires pPr first, before any runs).
      splicedPPr = splicedPara.ownerDocument.createElementNS(W_NS, "w:pPr");
      splicedPara.insertBefore(splicedPPr, splicedPara.firstChild);
    }
    // Index the spliced pPr's existing property names so we don't clobber
    // explicit clause overrides. Use nodeName (with w: prefix preserved
    // by the parser); fall back to localName for namespace-only lookups.
    var existing = {};
    for (var i = 0; i < splicedPPr.childNodes.length; i++) {
      var ch = splicedPPr.childNodes[i];
      if (ch.nodeType !== 1) continue;
      existing[ch.nodeName] = true;
      if (ch.localName) existing["w:" + ch.localName] = true;
    }
    // Walk host pPr children; for each property the spliced para doesn't
    // already have, deep-clone it onto the spliced pPr. Always-inherit
    // properties (rPr inside pPr governs paragraph-mark formatting and
    // can stay clause-side) are filtered out.
    var skip = { "w:rPr": true }; // paragraph-mark run props stay clause-side
    for (var j = 0; j < hostPPr.childNodes.length; j++) {
      var hc = hostPPr.childNodes[j];
      if (hc.nodeType !== 1) continue;
      var name = hc.nodeName;
      if (skip[name]) continue;
      if (existing[name]) continue;
      var imported = splicedPara.ownerDocument.importNode(hc, true);
      splicedPPr.appendChild(imported);
    }
  }

  // 2026-05-21: helper for the relaxed variant-marker matcher. Removes
  // a known leading substring from a paragraph element. Handles two
  // cases:
  //   • Substring fits inside one <w:t>: do an in-place text edit
  //     (preserves run formatting around the removed text).
  //   • Substring is split across <w:t> elements (Word's spell-check
  //     splits runs): collapse the paragraph into a single <w:r><w:t>
  //     with the substring stripped. Loses inline formatting in that
  //     one paragraph but ensures the marker actually goes away.
  function _stripTextFromParagraph(p, substr) {
    if (!p || !substr) return false;
    var W_NS = "http://schemas.openxmlformats.org/wordprocessingml/2006/main";
    var tEls = Array.prototype.slice.call(p.getElementsByTagName("w:t"));
    if (!tEls.length) tEls = Array.prototype.slice.call(p.getElementsByTagNameNS(W_NS, "t"));
    // Try single-<w:t> first.
    for (var i = 0; i < tEls.length; i++) {
      var t = tEls[i];
      var current = t.textContent || "";
      var idx = current.indexOf(substr);
      if (idx !== -1) {
        t.textContent = current.slice(0, idx) + current.slice(idx + substr.length);
        return true;
      }
    }
    // Fallback: collapse paragraph.
    var joined = p.textContent || "";
    var fullIdx = joined.indexOf(substr);
    if (fullIdx === -1) return false;
    var newText = joined.slice(0, fullIdx) + joined.slice(fullIdx + substr.length);
    var xmlDoc = p.ownerDocument;
    // Capture first run's <w:rPr> for formatting inheritance.
    var firstRPr = null;
    var firstRun = p.getElementsByTagName("w:r")[0] || p.getElementsByTagNameNS(W_NS, "r")[0];
    if (firstRun) {
      var rPrEl = firstRun.getElementsByTagName("w:rPr")[0] || firstRun.getElementsByTagNameNS(W_NS, "rPr")[0];
      if (rPrEl) firstRPr = rPrEl.cloneNode(true);
    }
    // Preserve <w:pPr>.
    var pPr = p.getElementsByTagName("w:pPr")[0] || p.getElementsByTagNameNS(W_NS, "pPr")[0];
    while (p.firstChild) p.removeChild(p.firstChild);
    if (pPr) p.appendChild(pPr);
    var newRun = xmlDoc.createElementNS(W_NS, "w:r");
    if (firstRPr) newRun.appendChild(firstRPr);
    var newT = xmlDoc.createElementNS(W_NS, "w:t");
    if (newT.setAttributeNS) {
      newT.setAttributeNS("http://www.w3.org/XML/1998/namespace", "xml:space", "preserve");
    }
    newT.textContent = newText;
    newRun.appendChild(newT);
    p.appendChild(newRun);
    return true;
  }

  function _loadTemplateToWord(contentString, opts) {
    opts = opts || {};
    var parsed = null;
    var isJson = false;
    try {
      if (String(contentString).trim().charAt(0) === "{") {
        parsed = JSON.parse(contentString);
        isJson = true;
      }
    } catch (e) { isJson = false; }

    // 2026-05-21: skeleton-hybrid resolution. Additive, fail-open, and
    // feature-flag-gated. If the body contains &[…] boundary markers
    // AND the user has enableSkeletonResolver=true, we pick the active
    // variant + splice in clauses from the bd_clauses store BEFORE the
    // existing Phase A insert runs. Result: parsed.body becomes a
    // regular template (all #[…] and &[…] markers consumed), and
    // everything downstream (Phase A / B, Step 1, Step 2) runs unchanged.
    // If anything fails (missing clauses, no variant match, parse error)
    // we fall back to the unresolved body so the user can see + fix.
    //
    // opts.skipSkeleton (default false): bypass resolution entirely.
    // Used by Skeleton Workshop's "Load Raw" flow so admins can pull a
    // template into Word with markers intact for editing — no resolver
    // pass, no clause substitution, just the literal template body.
    var preResolve = Promise.resolve(parsed && parsed.body);
    if (!opts.skipSkeleton && isJson && parsed && parsed.body && _skeletonResolverEnabled() && _hasSkeletonMarkers(parsed.body)) {
      preResolve = _resolveSkeleton(parsed.body, _skeletonActiveVariant, {
        keepVariantMarkers: !!opts.keepVariantMarkers,
      })
        .then(function (resolved) {
          // Guard against the resolver returning the same length unchanged
          // (means no changes made). If resolved is materially different,
          // log a snapshot so we can compare on failures.
          try {
            window.__bdSkeletonSourceBody = parsed.body;
          } catch (_e) {}
          return resolved || parsed.body;
        })
        .catch(function (e) {
          eli.log.event("tool", "build_draft_skeleton_resolve_failed", {
            msg: e && e.message,
            stack: e && e.stack && String(e.stack).substring(0, 500),
          });
          return parsed.body;
        });
    }
    return preResolve.then(function (resolvedBody) {
      if (isJson && parsed) parsed.body = resolvedBody;
      return _loadTemplateToWord_inner(parsed, isJson, contentString);
    });
  }

  function _loadTemplateToWord_inner(parsed, isJson, contentString) {

    // Phase A (combined: body insert + body font + table font):
    // Previously this was Phase 1 (insertOoxml + sync) followed by a
    // separate runRaw _step3a_bodyFonts (load tables, 2 more syncs).
    // Now: insertOoxml + font.name + font.size + tables.load → sync →
    // table fonts → sync, ONE runRaw, 2 syncs. Saves a full runRaw
    // round-trip AND lets Word coalesce body-layout + font-apply into
    // a single layout pass instead of two. Returns section count.
    return eli.host.runRaw("build_draft:tpl_body_combined", function (context) {
      var body = context.document.body;
      if (isJson && parsed.body) {
        body.insertOoxml(parsed.body, Word.InsertLocation.replace);
      } else {
        body.insertText(String(contentString || ""), Word.InsertLocation.replace);
      }
      body.font.name = "Times New Roman";
      body.font.size = 11;
      var tables = body.tables;
      tables.load("items");
      var sections = context.document.sections;
      sections.load("items");
      return context.sync().then(function () {
        for (var ti = 0; ti < tables.items.length; ti++) {
          tables.items[ti].getRange().font.name = "Times New Roman";
        }
        return context.sync().then(function () { return sections.items.length; });
      });
    }).then(function (sectionCount) {
      // Phase B (combined per section: H/F inserts + H/F font normalization).
      // Previously this was two separate runRaws per section (Phase 2
      // inserts, then Phase 3b fonts). Now: one runRaw per section
      // handles both. For a 1-section doc: 4 runRaws → 2 total. For
      // a 5-section doc: 12 → 6. Each section's runRaw still stays
      // under ~100ms because H/F content is small.
      if (!isJson || !parsed.sections || !parsed.sections.length) {
        showToast("✅ Template loaded", "ok");
        return null;
      }
      // 2026-05-19 v9: per-section H/F inserts must dedupe by OOXML
      // equality across sections. Diagnostic on Services Agreement
      // template revealed: 2 sections, both with identical primaryH
      // content. Word's default "Link to Previous" means section 1's
      // Primary IS the same physical header part as section 0's. Writing
      // the same OOXML twice (once per section) APPENDS into the shared
      // physical part — producing "[[placeholder]][[placeholder]]"
      // doubling, which then fills as "ZymoResearchZymoResearch" on
      // step 2 substitution.
      //
      // Fix: track which OOXML strings have already been inserted into
      // each H/F slot (Primary/FirstPage/EvenPages + Header/Footer).
      // For each subsequent section, if its OOXML equals a slot we've
      // already written, mark that slot as "skip this section" — Word's
      // linkage will inherit the content automatically.
      //
      // Edge case: source had distinct unlinked sections with coincidentally
      // identical OOXML. Dedup wrongly skips, but the content is the same
      // anyway so the user can't tell. Worth it to fix the much-more-
      // common doubling bug.
      // 2026-05-20: dedupe on EFFECTIVE content (post-fallback), not raw
      // source OOXML. The load now falls back to Primary when source had
      // no distinct FirstPage/EvenPages — so cross-section dedup must
      // also compare against that effective value, otherwise we'd
      // double-write to linked physical parts on identical primaryH.
      var seenH = { primary: null, firstPage: null, evenPages: null };
      var seenF = { primary: null, firstPage: null, evenPages: null };
      var skipMap = []; // skipMap[idx] = { primary, firstPage, evenPages } booleans for H AND F
      parsed.sections.forEach(function (secData, idx) {
        var h = secData.headers || {};
        var f = secData.footers || {};
        var effH = {
          primary:   h.primary   || "",
          firstPage: h.firstPage || h.primary || "",
          evenPages: h.evenPages || h.primary || "",
        };
        var effF = {
          primary:   f.primary   || "",
          firstPage: f.firstPage || f.primary || "",
          evenPages: f.evenPages || f.primary || "",
        };
        var skip = {
          headerPrimary:   !!(effH.primary   && seenH.primary   === effH.primary),
          headerFirstPage: !!(effH.firstPage && seenH.firstPage === effH.firstPage),
          headerEvenPages: !!(effH.evenPages && seenH.evenPages === effH.evenPages),
          footerPrimary:   !!(effF.primary   && seenF.primary   === effF.primary),
          footerFirstPage: !!(effF.firstPage && seenF.firstPage === effF.firstPage),
          footerEvenPages: !!(effF.evenPages && seenF.evenPages === effF.evenPages),
        };
        skipMap.push(skip);
        if (effH.primary)   seenH.primary   = effH.primary;
        if (effH.firstPage) seenH.firstPage = effH.firstPage;
        if (effH.evenPages) seenH.evenPages = effH.evenPages;
        if (effF.primary)   seenF.primary   = effF.primary;
        if (effF.firstPage) seenF.firstPage = effF.firstPage;
        if (effF.evenPages) seenF.evenPages = effF.evenPages;
      });
      try {
        eli.log.event("tool", "build_draft_tpl_load_dedup", {
          sections: parsed.sections.length,
          skipMap: skipMap,
        });
      } catch (_e) {}
      var chain = Promise.resolve();
      parsed.sections.forEach(function (secData, idx) {
        chain = chain.then(function () {
          return _loadTemplateSectionCombined(idx, secData, skipMap[idx]);
        });
      });
      return chain.then(function () { showToast("✅ Template loaded", "ok"); });
    }).then(function () {
      // 2026-05-24 Phase C: restore captured customXmlParts (e.g.
      // template_indexer's section metadata). Chained on the outer Phase B
      // promise so it runs after the body + H/F finish AND after the
      // showToast in either path (early return OR full per-section chain).
      // Fail-open: any error logs but doesn't fail the overall load.
      // Backward compat: old templates lacking customXmlParts skip this.
      if (!isJson || !parsed || !parsed.customXmlParts || !parsed.customXmlParts.length) {
        return null;
      }
      return eli.host.runRaw("build_draft:tpl_restore_xml", function (context) {
        // Recover namespace from XML root if stored field is null (some
        // Word builds return null for Bookmark/CustomXmlPart.namespaceUri).
        function _nsFromXml(xml) {
          if (!xml) return "";
          var m = xml.match(/xmlns(?::[A-Za-z0-9]+)?\s*=\s*"([^"]+)"/);
          return m ? m[1] : "";
        }
        var restoreSet = (parsed.customXmlParts || []).map(function (p) {
          if (!p || !p.xml) return null;
          return { xml: p.xml, namespaceUri: p.namespaceUri || _nsFromXml(p.xml) };
        }).filter(function (p) { return p && p.namespaceUri; });
        // Pre-clear existing parts in each restored namespace so we don't
        // duplicate (capture-side already filtered out Word built-ins, so
        // this only touches tool-owned namespaces like template_indexer/v1).
        var nsSet = {};
        restoreSet.forEach(function (p) { nsSet[p.namespaceUri] = true; });
        var collections = Object.keys(nsSet).map(function (ns) {
          var col = context.document.customXmlParts.getByNamespace(ns);
          col.load("items");
          return col;
        });
        return context.sync().then(function () {
          collections.forEach(function (col) {
            (col.items || []).forEach(function (p) {
              try { p.delete(); } catch (_e) {}
            });
          });
          return context.sync().then(function () {
            var added = 0, skipped = 0;
            restoreSet.forEach(function (p) {
              try { context.document.customXmlParts.add(p.xml); added++; }
              catch (e) {
                skipped++;
                eli.log.event("tool", "build_draft_tpl_xml_restore_skip", {
                  ns: p.namespaceUri, msg: e && e.message,
                });
              }
            });
            return context.sync().then(function () {
              eli.log.event("tool", "build_draft_tpl_xml_restore_result", {
                desired: restoreSet.length, added: added, skipped: skipped,
                namespaces: restoreSet.map(function (p) { return p.namespaceUri; }),
              });
              return { added: added, skipped: skipped };
            });
          });
        });
      }).catch(function (e) {
        eli.log.event("tool", "build_draft_tpl_xml_restore_failed", {
          msg: e && e.message, partCount: (parsed.customXmlParts || []).length,
        });
        return null;
      });
    });
  }

  // 2026-05-19 v8: convert the saved template's original counterparty
  // name into a [[Counterparty Name]] placeholder across body + every
  // header/footer. Templates capture raw OOXML at save — any plain-text
  // occurrences of the original drafter's party name come along for the
  // ride. On step-2 fill, placeholders get substituted but those baked
  // names stay, producing "OldNameNewName" doubling (the user-reported
  // "Zymo researchZymoResearch" on the first-page header).
  //
  // Linkage-aware H/F search reuses the same titlePg / evenAndOdd OOXML
  // detection as _step2_applyBatch v7 — no point searching FirstPage /
  // EvenPages when they alias Primary; one replace becomes three.
  function _scrubOldPartyAsPlaceholder(oldParty) {
    oldParty = String(oldParty == null ? "" : oldParty).trim();
    // Two-char minimum guards against typos like party="X" matching every
    // capital X in the doc. Real counterparty names are always longer.
    if (oldParty.length < 2) return Promise.resolve(0);
    var sentinel = "[[Counterparty Name]]";
    return eli.host.runRaw("build_draft:scrub_old_party", function (context) {
      var sections = context.document.sections;
      sections.load("items");
      return context.sync().then(function () {
        var searchOpts = { matchCase: false, ignoreSpace: false, ignorePunctuation: false };
        var bodyRes = context.document.body.search(oldParty, searchOpts);
        bodyRes.load("items");
        var sectionOoxmlReqs = [];
        for (var si = 0; si < sections.items.length; si++) {
          try { sectionOoxmlReqs.push(sections.items[si].body.getOoxml()); }
          catch (_e) { sectionOoxmlReqs.push(null); }
        }
        return context.sync().then(function () {
          var hfRanges = [];
          for (var si2 = 0; si2 < sections.items.length; si2++) {
            var sec = sections.items[si2];
            var secOoxml = "";
            try { secOoxml = String((sectionOoxmlReqs[si2] && sectionOoxmlReqs[si2].value) || ""); }
            catch (_e) {}
            var hasDiffFirstPage = /<w:titlePg\b/i.test(secOoxml);
            var hasEvenAndOdd    = /<w:evenAndOddHeaders\b/i.test(secOoxml);
            var typesToSearch = ["Primary"];
            if (hasDiffFirstPage) typesToSearch.push("FirstPage");
            if (hasEvenAndOdd)    typesToSearch.push("EvenPages");
            typesToSearch.forEach(function (t) {
              try {
                var hr = sec.getHeader(t).search(oldParty, searchOpts);
                hr.load("items");
                hfRanges.push(hr);
              } catch (_e) {}
              try {
                var fr = sec.getFooter(t).search(oldParty, searchOpts);
                fr.load("items");
                hfRanges.push(fr);
              } catch (_e) {}
            });
          }
          return context.sync().then(function () {
            var count = 0;
            // Body first.
            for (var bk = bodyRes.items.length - 1; bk >= 0; bk--) {
              try { bodyRes.items[bk].insertText(sentinel, "Replace"); count++; } catch (_e) {}
            }
            hfRanges.forEach(function (rng) {
              for (var k = rng.items.length - 1; k >= 0; k--) {
                try { rng.items[k].insertText(sentinel, "Replace"); count++; } catch (_e) {}
              }
            });
            return context.sync().then(function () {
              eli.log.event("tool", "build_draft_scrub_old_party", {
                oldParty: oldParty,
                replaced: count,
                sentinel: sentinel,
              });
              return count;
            });
          });
        });
      });
    }).catch(function (err) {
      // Non-fatal — load already succeeded; scrub is a cleanup pass.
      eli.log.event("tool", "build_draft_scrub_old_party_failed", {
        msg: err && err.message,
      });
      return 0;
    });
  }

  // Combined per-section H/F insert + font normalization. One runRaw,
  // 2 syncs total: insert all 6 HF OOXML + load all HF paragraphs →
  // sync → set fonts + delete trailing empties → sync. Word does the
  // HF inserts and the font apply in the same layout pass.
  //
  // 2026-05-19 v9: accepts a `skipMap` from the caller marking which
  // H/F slots have already been written by a previous section (same
  // OOXML — likely linked to previous via Word's default). Skipping
  // these avoids the doubling bug where a second insert into a linked
  // physical part appends instead of replaces.
  function _loadTemplateSectionCombined(idx, secData, skipMap) {
    skipMap = skipMap || {};
    return eli.host.runRaw("build_draft:tpl_section_combined_" + idx, function (context) {
      var sections = context.document.sections;
      sections.load("items");
      return context.sync().then(function () {
        if (idx >= sections.items.length) return;
        var sec = sections.items[idx];
        // 2026-05-19: linkage-aware header/footer insertion. When a Word
        // section doesn't have DifferentFirstPage / DifferentOddEven
        // enabled, getHeader("FirstPage") and getHeader("EvenPages")
        // resolve to the SAME physical header part as Primary. Blindly
        // inserting into all three then stamps the same content three
        // times into the shared header — producing the "BASFBASFBASF"
        // doubling the user reported. Detection: compare the captured
        // source OOXML; if FirstPage/EvenPages are identical to Primary
        // (or empty), they're linked → skip the insert. Primary alone
        // populates the shared header; the linked variants inherit
        // automatically without doubling.
        var hpXml  = (secData.headers && secData.headers.primary)   || "";
        var hf1Xml = (secData.headers && secData.headers.firstPage) || "";
        var hfeXml = (secData.headers && secData.headers.evenPages) || "";
        var fpXml  = (secData.footers && secData.footers.primary)   || "";
        var ff1Xml = (secData.footers && secData.footers.firstPage) || "";
        var ffeXml = (secData.footers && secData.footers.evenPages) || "";
        // 2026-05-19 v5: definitive linkage check via section OOXML.
        // The earlier text-equality approach missed cases because
        // insertOoxml + load("text") within one sync didn't always
        // return the post-insert value. Now we read the section's
        // OOXML BEFORE any inserts and inspect <w:sectPr> for the
        // <w:titlePg/> flag — Word's actual setting for "Different
        // First Page". When absent, FirstPage is linked to Primary
        // and inserting into it doubles content into the shared
        // physical header (the ZymoCorpZymo Corp bug).
        //
        // For EvenPages: the equivalent flag (<w:evenAndOddHeaders/>)
        // lives in word/settings.xml which we can't read via Word.js
        // Section.getOoxml(). Default conservative: skip EvenPages
        // inserts unless the source had a distinct EvenPages and the
        // dest section has explicit `<w:evenAndOddHeaders/>` somewhere
        // visible (almost never via section OOXML). Result: rare
        // distinct-even-page headers get lost; doubling never happens.
        var secBodyReq = sec.body.getOoxml();
        return context.sync().then(function () {
          var secOoxml = String((secBodyReq && secBodyReq.value) || "");
          var destHasDifferentFirstPage = /<w:titlePg\b/i.test(secOoxml);
          var destHasEvenAndOdd        = /<w:evenAndOddHeaders\b/i.test(secOoxml);
          // 2026-05-20 v10: when destination has a physically-distinct
          // FirstPage / EvenPages slot, ALWAYS populate it. If source
          // had a distinct variant, use that; otherwise FALL BACK to
          // Primary's content so the first page (or even pages) match
          // subsequent pages. Prior logic skipped the variant when
          // source matched Primary — but the dest's distinct FirstPage
          // slot then stayed empty, causing the "CP REF # missing from
          // FirstPage footer" bug the user reported. Phase A's body
          // insert doesn't reliably populate all H/F parts, so we
          // can't rely on it as a fallback.
          var hf1Content = hf1Xml || hpXml; // FirstPage header: distinct or fallback to Primary
          var hfeContent = hfeXml || hpXml; // EvenPages header: distinct or fallback to Primary
          var ff1Content = ff1Xml || fpXml; // FirstPage footer: distinct or fallback to Primary
          var ffeContent = ffeXml || fpXml; // EvenPages footer: distinct or fallback to Primary
          // Insertion decision: variant goes in iff the destination
          // slot is its own physical part (titlePg / evenAndOdd set).
          // Skip when there's nothing to write (no Primary either).
          var doH_first = !!(hf1Content && destHasDifferentFirstPage);
          var doH_even  = !!(hfeContent && destHasEvenAndOdd);
          var doF_first = !!(ff1Content && destHasDifferentFirstPage);
          var doF_even  = !!(ffeContent && destHasEvenAndOdd);
          // Keep the *Xml vars wired through to the inserts below
          // (no rename needed downstream).
          hf1Xml = hf1Content;
          hfeXml = hfeContent;
          ff1Xml = ff1Content;
          ffeXml = ffeContent;
          // ALWAYS insert Primary (covers the shared header when linked).
          //
          // 2026-05-19 v11: clear the H/F BEFORE insertOoxml. Phase A
          // (`body.insertOoxml(parsed.body, "replace")`) imports the
          // template's body package — and Word treats body packages as
          // full documents, so header parts referenced in the body
          // ALSO get populated. Phase B's `header.insertOoxml(xml,
          // "Replace")` then runs against a non-empty header, and
          // Word's "Replace" insertLocation behaves like "End" for
          // package-format OOXML inserts — it APPENDS instead of
          // overwriting. Net: the placeholder ends up in the header
          // twice, fill substitutes both, doubled output ("ZymoZymo").
          //
          // Fix: explicitly clear the header's body via insertText("",
          // Replace) before insertOoxml. After the clear the header is
          // a single empty paragraph; insertOoxml then replaces THAT,
          // producing exactly the OOXML's content. Tested 2026-05-19
          // against the Services Agreement template's 2-section pattern.
          function _safeInsertHF(getter, xml, label) {
            try {
              var hf = getter();
              try { hf.insertText("", Word.InsertLocation.replace); } catch (_e) {}
              hf.insertOoxml(xml, Word.InsertLocation.replace);
            }
            catch (e) { eli.log.event("tool", "build_draft_tpl_hf_skip", { type: label, msg: e && e.message }); }
          }
          // 2026-05-19 v9: skipMap from the caller marks slots already
          // written by a previous section (identical OOXML, likely
          // linked-to-previous). Writing them again concatenates into
          // the shared physical part — the doubling bug.
          if (hpXml && !skipMap.headerPrimary)
            _safeInsertHF(function () { return sec.getHeader("Primary"); }, hpXml, "PrimaryH");
          if (fpXml && !skipMap.footerPrimary)
            _safeInsertHF(function () { return sec.getFooter("Primary"); }, fpXml, "PrimaryF");
          if (doH_first && !skipMap.headerFirstPage)
            _safeInsertHF(function () { return sec.getHeader("FirstPage"); }, hf1Xml, "FirstPageH");
          if (doH_even && !skipMap.headerEvenPages)
            _safeInsertHF(function () { return sec.getHeader("EvenPages"); }, hfeXml, "EvenPagesH");
          if (doF_first && !skipMap.footerFirstPage)
            _safeInsertHF(function () { return sec.getFooter("FirstPage"); }, ff1Xml, "FirstPageF");
          if (doF_even && !skipMap.footerEvenPages)
            _safeInsertHF(function () { return sec.getFooter("EvenPages"); }, ffeXml, "EvenPagesF");
          // Diagnostic — paste from the console with eli.debug(true).
          try {
            eli.log.event("tool", "build_draft_hf_insert_plan", {
              section: idx,
              destDifferentFirstPage: destHasDifferentFirstPage,
              destEvenAndOdd:         destHasEvenAndOdd,
              primaryH_xml:           !!hpXml,
              firstPageH_src_distinct: !!hf1SrcDistinct,
              firstPageH_inserted:     !!doH_first,
              evenPagesH_src_distinct: !!hfeSrcDistinct,
              evenPagesH_inserted:     !!doH_even,
              primaryF_xml:           !!fpXml,
              firstPageF_src_distinct: !!ff1SrcDistinct,
              firstPageF_inserted:     !!doF_first,
              evenPagesF_src_distinct: !!ffeSrcDistinct,
              evenPagesF_inserted:     !!doF_even,
              sectionOoxmlBytes: secOoxml.length,
            });
          } catch (_e) {}
          // Queue the font-normalization paragraph loads in the SAME
          // sync as the variant inserts to keep round-trips tight.
          var jobs = [];
          HF_TYPES.forEach(function (t) {
            try {
              var h = sec.getHeader(t);
              var f = sec.getFooter(t);
              h.paragraphs.load("items");
              f.paragraphs.load("items/text");
              jobs.push({ h: h, f: f });
            } catch (e) {
              eli.log.event("tool", "build_draft_tpl_font_load_skip", { type: t, msg: e && e.message });
            }
          });
          return context.sync().then(function () {
            jobs.forEach(function (j) {
              for (var pi = 0; pi < j.h.paragraphs.items.length; pi++) {
                var hpara = j.h.paragraphs.items[pi];
                hpara.font.name = "Times New Roman";
                hpara.font.size = 9;
              }
              for (var k = j.f.paragraphs.items.length - 1; k >= 0; k--) {
                var pp = j.f.paragraphs.items[k];
                var clean2 = pp.text.replace(/\s+/g, "").trim();
                pp.font.name = "Times New Roman";
                pp.font.size = 9;
                if (clean2.length === 0 && k > 0) {
                  try { pp.delete(); }
                  catch (e2) { eli.log.event("tool", "build_draft_tpl_footer_del_skip", { msg: e2 && e2.message }); }
                }
              }
            });
            return context.sync();
          });
        });
      });
    });
  }

  // 3a. Body font + tables. One runRaw, 2 syncs. Returns section count
  // so the caller knows how many _step3b iterations to chain.
  function _step3a_bodyFonts() {
    return eli.host.runRaw("build_draft:tpl_fonts_body", function (context) {
      var body = context.document.body;
      body.font.name = "Times New Roman";
      body.font.size = 11;
      var tables = body.tables;
      tables.load("items");
      var sections = context.document.sections;
      sections.load("items");
      return context.sync().then(function () {
        for (var ti = 0; ti < tables.items.length; ti++) {
          tables.items[ti].getRange().font.name = "Times New Roman";
        }
        return context.sync().then(function () { return sections.items.length; });
      });
    });
  }

  // 3b. One section's H/F font normalization. Batches all 3 HF types
  // (Primary/FirstPage/EvenPages) into 2 syncs total: one to load every
  // header + footer paragraph, one to commit font + trailing-empty
  // delete changes. Six round trips → two.
  function _step3b_sectionFonts(idx) {
    return eli.host.runRaw("build_draft:tpl_fonts_section_" + idx, function (context) {
      var sections = context.document.sections;
      sections.load("items");
      return context.sync().then(function () {
        if (idx >= sections.items.length) return;
        var sec = sections.items[idx];
        var jobs = [];
        HF_TYPES.forEach(function (t) {
          try {
            var h = sec.getHeader(t);
            var f = sec.getFooter(t);
            h.paragraphs.load("items");
            f.paragraphs.load("items/text");
            jobs.push({ h: h, f: f, t: t });
          } catch (e) {
            eli.log.event("tool", "build_draft_tpl_font_load_skip", { type: t, msg: e && e.message });
          }
        });
        return context.sync().then(function () {
          jobs.forEach(function (j) {
            for (var pi = 0; pi < j.h.paragraphs.items.length; pi++) {
              var hp = j.h.paragraphs.items[pi];
              hp.font.name = "Times New Roman";
              hp.font.size = 9;
            }
            for (var k = j.f.paragraphs.items.length - 1; k >= 0; k--) {
              var pp = j.f.paragraphs.items[k];
              var clean2 = pp.text.replace(/\s+/g, "").trim();
              pp.font.name = "Times New Roman";
              pp.font.size = 9;
              if (clean2.length === 0 && k > 0) {
                try { pp.delete(); }
                catch (e2) { eli.log.event("tool", "build_draft_tpl_footer_del_skip", { msg: e2 && e2.message }); }
              }
            }
          });
          return context.sync();
        });
      });
    });
  }

  // Canonicalize an agreement-type string so singular ↔ plural variants
  // collapse to the same form. "Service Agreement" ↔ "Services Agreement",
  // "Master Service" ↔ "Master Services", etc. Rules: lowercase, trim,
  // collapse whitespace; strip trailing "s" from every word > 3 chars
  // (so "Services" → "service", "Agreement" unchanged, "Master" unchanged).
  // Also strips common joiner punctuation. Eventual agreement-type editor
  // can derive aliases by un-canonicalizing (showing both forms).
  function _canonicalAgreementType(s) {
    return String(s || "")
      .toLowerCase()
      .replace(/[-_.,;:/]+/g, " ")
      .replace(/\s+/g, " ")
      .trim()
      .split(" ")
      .map(function (w) {
        if (w.length > 3 && w.charAt(w.length - 1) === "s") return w.slice(0, -1);
        return w;
      })
      .join(" ");
  }
  // Surface canonicalization on the tool so the future agreement-type
  // editor + UI tests can call it consistently.
  window._eliBuildDraftCanonicalize = _canonicalAgreementType;

  function _findTemplateByType(detectedType) {
    if (!detectedType) return Promise.resolve(null);
    return _bdGetAll().then(function (rows) {
      if (!Array.isArray(rows) || !rows.length) return null;
      var target = _canonicalAgreementType(detectedType);
      var match = rows.find(function (t) {
        if (!t) return false;
        var a = _canonicalAgreementType(t.agreementType || "");
        var n = _canonicalAgreementType(t.name || "");
        return (a && a === target) || (n && n === target);
      });
      return match || null;
    }).catch(function () { return null; });
  }

  function _goHome() {
    if (eli.dashboard && eli.dashboard.goHome) eli.dashboard.goHome();
    else if (eli.dashboard && eli.dashboard.refresh) eli.dashboard.refresh();
  }

  // === Step 1: logic generation ===
  // FROM v2 generateDocumentFromLogic (line 21595) + runSegmentedLogic
  // (line 21716). Split into 5 short runRaw phases so each stays under
  // the 100ms Word.run budget — phase boundaries make recovery clear,
  // unblock the UI thread between phases, and keep token counts low.
  // Phases:
  //   1a. Execute IF/ELSE plan (delete losing branches)
  //   1b. Replace {{key}} placeholders (one runRaw per key)
  //   1c. Delete DEF + TITLE scaffolding
  //   1d. {{DELETE_LINE}} → paragraph delete; {{ENTER}} → ZWSP
  //   1e. (deferred 300ms) collapse adjacent empty paragraphs
  // Audit: bump the current run's furthest-step-reached and re-save the
  // recipe (progressive upsert by runId). Called when Step 3/4 complete so
  // the record reflects how far the build got. No-op if no run is open.
  // Persist the active run's id to the DOCUMENT (Office settings) so a build
  // that's stopped and resumed later — even in a new session, after the
  // taskpane closed and window state was lost — re-associates with the same
  // audit record. Travels with the .docx, same mechanism as EliEmailerPrefill.
  function _bdAuditPersistRun() {
    try {
      var m = window._bdActiveDraftMeta || {};
      if (!m.auditRunId) return;
      var s = Office.context.document.settings;
      s.set("BdAuditRun", { runId: m.auditRunId, startedAt: m.auditStartedAt || null });
      if (typeof s.saveAsync === "function") s.saveAsync(function () {});
    } catch (_e) {}
  }
  // Guarantee a run is established before a step is recorded. Order: in-memory
  // meta → document setting (resume) → mint a fresh one. Returns the runId.
  // Sync — the record's step1/step2 data is recovered by _bdAuditSave's
  // merge, so we don't need to decode the IDB row here.
  function _bdAuditEnsureRun() {
    window._bdActiveDraftMeta = window._bdActiveDraftMeta || {};
    var m = window._bdActiveDraftMeta;
    if (m.auditRunId) return m.auditRunId;
    try {
      var saved = Office.context.document.settings.get("BdAuditRun");
      if (saved && saved.runId) {
        m.auditRunId = saved.runId;
        if (saved.startedAt && !m.auditStartedAt) m.auditStartedAt = saved.startedAt;
        return m.auditRunId;
      }
    } catch (_e) {}
    if (typeof _bdAuditUuid === "function") {
      m.auditRunId = _bdAuditUuid();
      m.auditStartedAt = m.auditStartedAt || (eli.now ? eli.now() : Date.now());
      _bdAuditPersistRun();
    }
    return m.auditRunId;
  }

  // Snapshot of WHICH steps have run this build, from the live _bdCompleted
  // flags + the emailed marker. Merged (OR'd) into the record on every save,
  // so the final record shows exactly which of the 5 steps were done vs
  // skipped — not just the furthest one reached.
  function _bdStepsDoneSnapshot() {
    var m = window._bdActiveDraftMeta || {};
    return {
      logic: !!_bdCompleted.logic,
      fill: !!_bdCompleted.templates,
      errorReview: !!_bdCompleted.error_review,
      // "saved" = a real .docx write OR the Copy Name click (the user's
      // actual save action — they paste the name into Word's Save As).
      saved: !!(_bdCompleted.save || m.auditNameCopied),
      emailed: !!m.auditEmailed,
    };
  }

  // Stamp the completion time of a step (record keys: logic/fill/errorReview/
  // saved/emailed) ONCE — first completion wins, so a resumed re-run never
  // overwrites the original time. Lives on the active meta; persisted into the
  // record so the hub can show "completed at" after pause/resume.
  function _bdStampStepTime(key) {
    try {
      window._bdActiveDraftMeta = window._bdActiveDraftMeta || {};
      var m = window._bdActiveDraftMeta;
      m.auditStepTimes = m.auditStepTimes || {};
      if (!m.auditStepTimes[key]) m.auditStepTimes[key] = (eli.now ? eli.now() : Date.now());
    } catch (_e) {}
  }
  function _bdStepTimesSnapshot() {
    var m = window._bdActiveDraftMeta || {};
    return m.auditStepTimes || {};
  }
  // Map the record's step-time keys → hub step ids, for the hub's per-step
  // "completed at" line. (record: logic/fill/errorReview/saved/emailed;
  //  hub ids: logic/templates/error_review/save)
  function _bdHubStepTimes() {
    var st = (window._bdActiveDraftMeta && window._bdActiveDraftMeta.auditStepTimes) || {};
    return {
      logic: st.logic || null,
      templates: st.fill || null,
      error_review: st.errorReview || null,
      save: st.saved || st.emailed || null,
    };
  }

  // Pause/resume: when the hub opens for a doc that already carries a build
  // run (BdAuditRun in doc settings, persisted with the .docx), restore the
  // step flags + times + answers from the audit record so the user continues
  // where they left off. Once per session; a fresh template load supersedes it.
  function _bdHydrateFromAudit() {
    if (_bdHydrated) return Promise.resolve(null);
    _bdHydrated = true;
    var runId = null;
    try {
      var saved = Office.context.document.settings.get("BdAuditRun");
      if (saved && saved.runId) runId = saved.runId;
    } catch (_e) {}
    if (!runId || typeof _bdAuditDecode !== "function") return Promise.resolve(null);
    var prefix = (typeof _bdAuditConst === "function" ? _bdAuditConst().PREFIX : "bdaudit_");
    return eli.events.safeAsync(eli.storage.get("bd_history", prefix + runId), "build_draft.hydrate_get")
      .then(function (row) { return row ? _bdAuditDecode(eli, row) : null; })
      .then(function (rec) {
        if (!rec) return null;
        var sd = rec.stepsDone || {};
        _bdCompleted.logic = !!sd.logic;
        _bdCompleted.templates = !!sd.fill;
        _bdCompleted.error_review = !!sd.errorReview;
        _bdCompleted.save = !!sd.saved;
        // Restore the active meta so a resumed step continues the SAME run.
        window._bdActiveDraftMeta = window._bdActiveDraftMeta || {};
        var m = window._bdActiveDraftMeta;
        m.auditRunId = rec.runId;
        m.auditStartedAt = rec.startedAt || m.auditStartedAt;
        m.auditStepsReached = Math.max(m.auditStepsReached || 0, rec.stepsReached || 0);
        m.auditStep1Answers = rec.step1Answers || m.auditStep1Answers || {};
        m.auditStep2Fills = rec.step2Fills || m.auditStep2Fills || {};
        m.auditStepTimes = rec.stepTimes || {};
        if (!m.templateId && rec.templateId) m.templateId = rec.templateId;
        if (!m.templateName && rec.templateName) m.templateName = rec.templateName;
        if (sd.saved) m.auditNameCopied = true;
        if (sd.emailed) m.auditEmailed = true;
        eli.log.event("tool", "build_draft_resume_hydrated", {
          runId: rec.runId, steps: rec.stepsReached,
        });
        return rec;
      })
      .catch(function () { return null; });
  }

  function _bdAuditBumpStep(stepNum) {
    try {
      if (typeof _bdAuditSave !== "function") return;
      _bdAuditEnsureRun(); // resume: recover runId from the doc if memory was lost
      var m = window._bdActiveDraftMeta || {};
      if (!m.auditRunId) return; // couldn't establish a run; skip
      m.auditStepsReached = Math.max(m.auditStepsReached || 0, stepNum);
      var oars = {};
      try {
        var st = (eli.dispatch && typeof eli.dispatch === "function") ? eli.dispatch("oars", "getState") : null;
        if (typeof _extractOarsMetadata === "function") oars = _extractOarsMetadata(st) || {};
      } catch (_e) {}
      eli.events.safeAsync(_bdAuditSave(eli, {
        runId: m.auditRunId,
        startedAt: m.auditStartedAt,
        stepsReached: m.auditStepsReached,
        stepsDone: _bdStepsDoneSnapshot(),
        stepTimes: _bdStepTimesSnapshot(),
        step1Answers: m.auditStep1Answers || {},
        step2Fills: m.auditStep2Fills || {},
        cpRef: oars.cpRef || "",
        agreementType: String(m.draftType || m.templateType || oars.agreementType || ""),
        cpEntity: oars.colgateEntity || "",
        thirdParty: oars.thirdPartyEntity || "",
        requesterName: oars.requesterName || "",
        templateId: m.templateId || null,
        templateName: m.templateName || null,
        templateVersion: m.templateVersion || m.publishedAt || null,
      }), "build_draft.audit_bump_" + stepNum);
    } catch (_e) {}
  }

  function _runStep1Generation(answers) {
    showToast("⚙️ Generating document…", "info");
    // Emit start event BEFORE substitution begins so listeners (e.g.
    // bd_template_tester) can show a "rendering in progress"
    // indicator and know when the doc is mid-update. Paired with the
    // existing step1_done emit further down.
    try {
      if (eli.bus && typeof eli.bus.emit === "function") {
        eli.bus.emit("build_draft:step1_start", {
          ts: Date.now(),
          fieldCount: Object.keys(answers).length,
        });
      }
    } catch (_step1StartBusErr) { /* tolerate */ }
    return _step1a_executePlans(answers)
      .then(function () { return _step1b_replaceKeys(answers); })
      .then(function () { return _step1c_deleteScaffolds(); })
      .then(function () { return _step1d_specialTags(); })
      .then(function () { return _step1f_stripRemaining(); })
      .then(function () {
        // Background pass kicked off but not awaited — UX returns now.
        setTimeout(function () {
          _step1e_collapseEmpties().catch(function (e) {
            eli.log.event("tool", "build_draft_step1e_failed", { msg: e && e.message });
          });
        }, 300);
        _bdCompleted.logic = true;
        // Audit: stash Step 1 answers + open a run on the active-draft meta
        // so the Step 2 capture can finalize the recipe record. runId is the
        // UUID dedup key; startedAt anchors the run.
        try {
          if (typeof _bdAuditEnsureRun === "function") _bdAuditEnsureRun(); // resume or open the run
          window._bdActiveDraftMeta = window._bdActiveDraftMeta || {};
          var _adm = window._bdActiveDraftMeta;
          _adm.auditStep1Answers = Object.assign({}, answers);
          _adm.auditStepsReached = Math.max(_adm.auditStepsReached || 0, 1);
          _bdStampStepTime("logic");
          // Persist the record NOW (not just at Step 2) so pausing right after
          // Step 1 survives close/reopen with logic marked done + its time.
          if (typeof _bdAuditBumpStep === "function") _bdAuditBumpStep(1);
        } catch (_auditE) {}
        showToast("✅ Step 1 complete", "ok");
        if (eli.activity && eli.activity.add) {
          eli.activity.add({
            type: "build-draft", icon: "🏗️", label: "Build Draft",
            summary: Object.keys(answers).length + " field(s) populated",
            payload: { fieldCount: Object.keys(answers).length },
          });
        }
        // Notify subscribers (e.g. bd_template_tester) that Step 1
        // substitution just finished. They can use this to refresh
        // their view of the doc state, prompt for a fresh snapshot,
        // etc. Fire-and-forget; never let subscriber failure poison
        // the wizard.
        try {
          if (eli.bus && typeof eli.bus.emit === "function") {
            eli.bus.emit("build_draft:step1_done", {
              ts: Date.now(),
              fieldCount: Object.keys(answers).length,
            });
          }
        } catch (_step1BusErr) { /* tolerate */ }
        // Return to hub so the user sees progress and picks the next step
        setTimeout(function () { _show({}); }, 400);
      })
      .catch(function (err) {
        _wizardMode = false; // failed run shouldn't poison the next manual click
        // Reset any "rendering" UI in subscribers — they need to know
        // the chain aborted, otherwise the spinner hangs forever.
        try {
          if (eli.bus && typeof eli.bus.emit === "function") {
            eli.bus.emit("build_draft:step1_failed", {
              ts: Date.now(),
              msg: err && err.message,
            });
          }
        } catch (_) { /* tolerate */ }
        eli.log.event("tool", "build_draft_step1_failed", { msg: err && err.message });
        showToast("Step 1 failed: " + (err && err.message), "err");
      });
  }

  // 1a. Execute IF/ELSE plans — collect tags, build plans, delete losing
  // branches. Single short pass over all tags; deepest-first sort so
  // nested deletions don't invalidate outer ranges.
  function _step1a_executePlans(answers) {
    return eli.host.runRaw("build_draft:step1a_plans", function (context) {
      var body = context.document.body;
      var tagSearch = body.search("\\{\\{[!\\}]@\\}\\}", { matchWildcards: true });
      tagSearch.load(["text", "index"]);
      return context.sync().then(function () {
        var tags = [];
        for (var i = 0; i < tagSearch.items.length; i++) {
          var rawTxt = tagSearch.items[i].text.replace(/[{}]/g, "").trim();
          if (rawTxt.indexOf("IF:") === 0 || rawTxt.indexOf("ELSEIF:") === 0
              || rawTxt.indexOf("ELSE") === 0 || rawTxt.indexOf("ENDIF") === 0) {
            tags.push({ range: tagSearch.items[i], text: rawTxt, index: i });
          }
        }
        var blockStack = [];
        var executionPlans = [];
        for (var j = 0; j < tags.length; j++) {
          var t = tags[j];
          var txt = t.text;
          if (txt.indexOf("IF:") === 0) {
            var blk = { segments: [], startTagIndex: j, depth: blockStack.length };
            blk.segments.push({ condition: txt.substring(3).trim(), tagIndex: j });
            blockStack.push(blk);
          } else if (txt.indexOf("ELSEIF:") === 0) {
            var blk2 = blockStack.length ? blockStack[blockStack.length - 1] : null;
            if (blk2) {
              blk2.segments[blk2.segments.length - 1].endTagIndex = j;
              blk2.segments.push({ condition: txt.substring(7).trim(), tagIndex: j });
            }
          } else if (txt.indexOf("ELSE") === 0) {
            var blk3 = blockStack.length ? blockStack[blockStack.length - 1] : null;
            if (blk3) {
              blk3.segments[blk3.segments.length - 1].endTagIndex = j;
              blk3.segments.push({ condition: "true", tagIndex: j });
            }
          } else if (txt.indexOf("ENDIF") === 0) {
            var done = blockStack.pop();
            if (done) {
              done.segments[done.segments.length - 1].endTagIndex = j;
              executionPlans.push({ segments: done.segments, finalEndTagIndex: j, depth: done.depth });
            }
          }
        }
        executionPlans.sort(function (a, b) { return b.depth - a.depth; });
        for (var p = 0; p < executionPlans.length; p++) {
          var plan = executionPlans[p];
          var winning = -1;
          for (var s = 0; s < plan.segments.length; s++) {
            if (evalLogicCondition(plan.segments[s].condition, answers)) { winning = s; break; }
          }
          if (winning > -1) {
            for (var s2 = 0; s2 < plan.segments.length; s2++) {
              var seg = plan.segments[s2];
              var startTag = tags[seg.tagIndex].range;
              if (seg.endTagIndex === undefined) continue;
              var endTag = tags[seg.endTagIndex].range;
              if (s2 === winning) {
                startTag.delete();
              } else {
                var rng = startTag.getRange("Start").expandTo(endTag.getRange("Start"));
                rng.delete();
              }
            }
            if (tags[plan.finalEndTagIndex]) tags[plan.finalEndTagIndex].range.delete();
          } else if (plan.segments.length && plan.finalEndTagIndex !== undefined) {
            var firstTag = tags[plan.segments[0].tagIndex].range;
            var finalTag = tags[plan.finalEndTagIndex].range;
            var del = firstTag.getRange("Start").expandTo(finalTag.getRange("End"));
            del.delete();
          }
        }
        return context.sync();
      });
    });
  }

  // 1b. Replace every {{key}} / {{key:formatter}} with the answer.
  // Batched into a single runRaw — N queued searches commit in ONE
  // sync, then a single insertText/font pass commits in a second.
  // Previously this ran one runRaw per key (30–50 sequential Word.run
  // round-trips for typical templates → multi-second freeze, Word
  // sometimes jammed). Now: 1 runRaw, 2 syncs, regardless of key count.
  function _step1b_replaceKeys(answers) {
    var keys = Object.keys(answers);
    if (!keys.length) return Promise.resolve();
    return eli.host.runRaw("build_draft:step1b_keys_batched", function (context) {
      var body = context.document.body;
      var searches = keys.map(function (key) {
        var pattern = "\\{\\{" + key + "*\\}\\}";
        var res = body.search(pattern, { matchWildcards: true });
        res.load("text");
        return { key: key, res: res };
      });
      return context.sync().then(function () {
        searches.forEach(function (s) {
          var answer = answers[s.key];
          for (var i = s.res.items.length - 1; i >= 0; i--) {
            var item = s.res.items[i];
            var tagContent = item.text.replace(/^\{\{|\}\}$/g, "").trim();
            var pair = tagContent.split(":");
            var tagKey = pair[0].trim();
            var fmt = pair.length > 1 ? pair[1].trim().toUpperCase() : null;
            if (tagKey !== s.key) continue;
            var finalVal = answer;
            if (fmt === "UPPER") finalVal = String(finalVal).toUpperCase();
            else if (fmt === "LOWER") finalVal = String(finalVal).toLowerCase();
            else if (fmt === "TITLE") {
              finalVal = String(finalVal).replace(/\w\S*/g, function (w) {
                return w.charAt(0).toUpperCase() + w.substr(1).toLowerCase();
              });
            }
            var clean = String(finalVal).trim().toLowerCase().replace(/['"’]/g, "");
            var isOther = clean === "other";
            var isUnknown = clean.indexOf("dont know") !== -1 || clean.indexOf("don't know") !== -1;
            if (isOther) finalVal = "[" + finalVal + "]";
            else if (isUnknown) finalVal = "[THIRD PARTY TO FILL IN - " + s.key.toUpperCase() + "]";
            var inserted = _bdInsertText(item, finalVal);
            if (isOther || isUnknown) {
              inserted.font.color = "#c62828";
              inserted.font.bold = true;
            }
          }
        });
        return context.sync();
      });
    });
  }

  // 1c. Delete DEF + TITLE scaffolding tags (no longer needed once
  // the visible content has been resolved).
  function _step1c_deleteScaffolds() {
    return eli.host.runRaw("build_draft:step1c_scaffolds", function (context) {
      var body = context.document.body;
      var defs = body.search("\\{\\{DEF:*\\}\\}", { matchWildcards: true });
      var titles = body.search("\\{\\{TITLE:*\\}\\}", { matchWildcards: true });
      defs.load("items");
      titles.load("items");
      return context.sync().then(function () {
        for (var i = defs.items.length - 1; i >= 0; i--) defs.items[i].delete();
        for (var k = titles.items.length - 1; k >= 0; k--) titles.items[k].delete();
        return context.sync();
      });
    });
  }

  // 1d. {{DELETE_LINE}} → drop paragraph; {{ENTER}} → zero-width space.
  function _step1d_specialTags() {
    return eli.host.runRaw("build_draft:step1d_special", function (context) {
      var body = context.document.body;
      var del = body.search("\\{\\{DELETE_LINE\\}\\}", { matchWildcards: true });
      var ent = body.search("\\{\\{ENTER\\}\\}", { matchWildcards: true });
      del.load("items");
      ent.load("items");
      return context.sync().then(function () {
        for (var i = del.items.length - 1; i >= 0; i--) {
          try { del.items[i].paragraphs.getFirst().delete(); }
          catch (e) { eli.log.event("tool", "build_draft_delete_line_skip", { msg: e && e.message }); }
        }
        for (var k = ent.items.length - 1; k >= 0; k--) {
          ent.items[k].insertText("​", "Replace");
        }
        return context.sync();
      });
    });
  }

  // 1f. Final tidy: strip ANY surviving {{...}} tags. Catches keys with
  // no answer (user removed input), malformed tags, etc. Runs after the
  // main chain so the wizard advances even if the doc had stragglers.
  function _step1f_stripRemaining() {
    return eli.host.runRaw("build_draft:step1f_strip", function (context) {
      var body = context.document.body;
      var leftovers = body.search("\\{\\{*\\}\\}", { matchWildcards: true });
      leftovers.load("text");
      return context.sync().then(function () {
        for (var i = leftovers.items.length - 1; i >= 0; i--) {
          try { leftovers.items[i].delete(); }
          catch (e) { eli.log.event("tool", "build_draft_strip_skip", { msg: e && e.message }); }
        }
        return context.sync();
      });
    });
  }

  // 1e. Collapse adjacent empty paragraphs. Background pass — not
  // awaited by main flow.
  function _step1e_collapseEmpties() {
    return eli.host.runRaw("build_draft:step1e_collapse", function (context) {
      var paras = context.document.body.paragraphs;
      paras.load("items/text");
      return context.sync().then(function () {
        for (var i = paras.items.length - 1; i > 0; i--) {
          var curr = paras.items[i];
          var above = paras.items[i - 1];
          if (curr.text.trim().length === 0
              && curr.text.indexOf("​") === -1
              && curr.text.indexOf("\f") === -1
              && above.text.trim().length === 0) {
            try { curr.delete(); }
            catch (e) { eli.log.event("tool", "build_draft_collapse_skip", { msg: e && e.message }); }
          }
        }
        return context.sync();
      });
    });
  }

  // === Step 2: template fill ===
  // Scan body+headers+footers, detect placeholders, route to
  // showStep1Reminder if {{ still present, else render fill form.
  function _runStep2() {
    showToast("🔍 Scanning placeholders…", "info");
    return eli.events.safeAsync(_scanForFill(), "build_draft.fill_scan")
      .then(function (text) {
        var phs = extractTemplatePlaceholders(text);
        eli.log.event("tool", "build_draft_step2_scan", {
          textLen: text.length,
          placeholderCount: phs.length,
          sample: phs.slice(0, 5),
        });
        if (text.indexOf("{{") !== -1 || text.indexOf("}}") !== -1) {
          _showStep1Reminder(function () { _showStep2Form(text, true); });
          return;
        }
        _showStep2Form(text, false);
      })
      .catch(function (err) {
        eli.log.event("tool", "build_draft_step2_scan_failed", { msg: err && err.message });
        showToast("Step 2 scan failed: " + (err && err.message), "err");
      });
  }

  function _showStep1Reminder(onIgnore) {
    if (typeof showEliDialog !== "function") { onIgnore && onIgnore(); return; }
    showEliDialog({
      variant: "warning",
      icon: "🚧",
      title: "Unprocessed Logic Detected",
      paragraphs: [
        "I found <b>{{Curly Braces}}</b> in this document.",
        "Did you remember to run <b>Step 1 (Customize Template)</b> to process the IF/ELSE rules first?",
      ],
      primary: { label: "🔙 Go to Step 1", onclick: function () {
        var mount = document.getElementById("_eli3_dashboard_root");
        if (mount) _show({});
        setTimeout(function () { _renderLogicPanel(); }, 50);
      } },
      secondary: { label: "⏩ Ignore & Continue", onclick: function () {
        if (onIgnore) onIgnore();
      } },
    });
  }

  // 2026-05-19: track the live activity entry for the fill form so
  // its payload stays in sync with whatever the user has typed. Restored
  // from `restoreOpts.prefillValues` when re-entered from the session
  // feed, so values persist across visits.
  var _bdFillActivityId = null;
  // 2026-05-27: extract a bundle of OARS fields needed by Step 2's UI and
  // the Email Requester flow. Returns { requesterName, requesterEmail,
  // colgateEntity, thirdPartyEntity, agreementType, cpRef }. Tablesdata
  // first (structured 2-col tables in the OARS docx), regex fallback on
  // raw text. Each field accepts multiple label variants. Empty strings
  // for missing.
  function _extractOarsMetadata(oarsState) {
    var out = {
      requesterName: "", requesterEmail: "",
      colgateEntity: "", thirdPartyEntity: "",
      agreementType: "", cpRef: "",
    };
    if (!oarsState) return out;

    // Each spec: [outKey, regex, priority]. Higher priority wins per key.
    // Lets us prefer "Third Party Name" over "Third Party Entity" when
    // both exist in the same OARS doc — the filename's [Party] slot
    // canonically takes the party NAME (e.g. "Acme Corp"), not the
    // legal entity descriptor.
    var specs = [
      ["requesterName",    /^\s*(?:requester|requestor)\s+name\s*$/i, 20],
      ["requesterName",    /^\s*(?:requester|requestor)\s*$/i, 10],
      ["requesterEmail",   /^\s*(?:requester|requestor)(?:\s+|s\s+)?(?:e[\s-]?mail|email|email address)\s*$/i, 10],
      ["colgateEntity",    /^\s*(?:colgate|cp|hpn|hill(?:'s|s)?)\s+entity\s*$/i, 10],
      // Party precedence: Name > Entity > Company > bare "Third Party" > Counterparty.
      ["thirdPartyEntity", /^\s*third[\s-]?party\s+name\s*$/i, 40],
      ["thirdPartyEntity", /^\s*third[\s-]?party\s+entity\s*$/i, 30],
      ["thirdPartyEntity", /^\s*third[\s-]?party\s+company\s*$/i, 25],
      ["thirdPartyEntity", /^\s*third[\s-]?party\s*$/i, 20],
      ["thirdPartyEntity", /^\s*counterparty\s+name\s*$/i, 15],
      ["thirdPartyEntity", /^\s*counterparty\s*$/i, 10],
      ["agreementType",    /^\s*(?:agreement\s+type|type\s+of\s+agreement|type)\s*$/i, 10],
      ["cpRef",            /^\s*(?:cp[\s-]?ref(?:erence)?(?:\s*#)?|ref(?:erence)?(?:\s*#)?|a[\s-]?number|agreement\s+request\s+number)\s*$/i, 10],
    ];

    // Track best-priority match per key so higher-priority labels can
    // overwrite earlier lower-priority ones regardless of doc order.
    var bestPriority = {};
    function _set(key, val, priority) {
      if (!val) return;
      var v = String(val).trim();
      if (!v) return;
      if (bestPriority[key] == null || priority > bestPriority[key]) {
        out[key] = v;
        bestPriority[key] = priority;
      }
    }

    // Strip trailing parentheticals so labels like "Third Party Name
    // (Contracting Entity)" or "CP Ref (Internal)" still match the
    // base-form regexes. Most OARS docs annotate fields this way.
    function _normLabel(s) {
      return String(s || "").replace(/\s*\([^)]*\)\s*$/, "").trim();
    }
    if (oarsState.tablesData && oarsState.tablesData.length) {
      oarsState.tablesData.forEach(function (table) {
        if (!table || !table.length) return;
        table.forEach(function (row) {
          if (!row || row.length < 2) return;
          var k = _normLabel(row[0]);
          specs.forEach(function (s) {
            if (s[1].test(k)) _set(s[0], row[1], s[2]);
          });
        });
      });
    }
    if (oarsState.text) {
      var lines = String(oarsState.text).split(/\r?\n/);
      lines.forEach(function (ln) {
        var m = ln.match(/^\s*(.+?)\s*[:=]\s*(.+?)\s*$/);
        if (!m) return;
        var key = _normLabel(m[1]), val = m[2];
        specs.forEach(function (s) {
          if (s[1].test(key)) _set(s[0], val, s[2]);
        });
      });
    }
    return out;
  }

  // First-name extractor used by Email Requester salutation + sign-off.
  function _firstNameOf(full) {
    return String(full || "").trim().split(/\s+/)[0] || "";
  }

  var _bdFillSnapshot = null;
  function _showStep2Form(scannedText, forced, restoreOpts) {
    var placeholders = extractTemplatePlaceholders(scannedText);
    var mount = document.getElementById("_eli3_dashboard_root");
    // Source context: prefer the in-tool _footerFile (current session
    // upload), fall back to the restoreOpts so reopening from the feed
    // brings back the same "loaded source" chip if it was set.
    var sourceText = (_footerFile && _footerFile.text)
      || (restoreOpts && restoreOpts.sourceText)
      || "";
    var sourceName = (_footerFile && _footerFile.name)
      || (restoreOpts && restoreOpts.sourceName)
      || null;
    // OARS metadata lookup (best-effort, never throws).
    var _oarsMeta = {
      requesterName: "", requesterEmail: "",
      colgateEntity: "", thirdPartyEntity: "",
      agreementType: "", cpRef: "",
    };
    try {
      var _oarsState = (eli.dispatch && typeof eli.dispatch === "function")
        ? eli.dispatch("oars", "getState") : null;
      _oarsMeta = _extractOarsMetadata(_oarsState);
    } catch (_oarsErr) {}
    var prefillValues = (restoreOpts && restoreOpts.prefillValues) || {};
    // Open a fresh activity entry for this fill session so the feed
    // shows "Fill in progress (N filled)" and one click restores the
    // user right back into the form with their values intact.
    _bdFillSnapshot = {
      phase: "step2-fill",
      scannedText: scannedText,
      sourceText: sourceText,
      sourceName: sourceName,
      values: Object.assign({}, prefillValues),
      placeholderCount: placeholders.length,
    };
    function _filledCount(vals) {
      var n = 0;
      Object.keys(vals || {}).forEach(function (k) {
        if (vals[k] != null && String(vals[k]).trim().length > 0) n++;
      });
      return n;
    }
    function _summary(vals) {
      var filled = _filledCount(vals);
      return filled + " of " + placeholders.length + " field" +
        (placeholders.length === 1 ? "" : "s") + " filled";
    }
    if (eli.activity && typeof eli.activity.add === "function") {
      try {
        var entry = eli.activity.add({
          type: "build-draft",
          icon: "📝",
          label: "Build Draft · Fill",
          summary: _summary(prefillValues),
          payload: _bdFillSnapshot,
          restoreChannel: "activity_restore",
          restoreKey: "build-draft",
        });
        _bdFillActivityId = (entry && entry.id) || null;
      } catch (_e) {
        _bdFillActivityId = null;
      }
    }
    function _persistSnapshot(currentValues) {
      _bdFillSnapshot.values = Object.assign({}, currentValues || {});
      if (!_bdFillActivityId || !eli.activity || typeof eli.activity.update !== "function") return;
      try {
        eli.activity.update(_bdFillActivityId, {
          summary: _summary(_bdFillSnapshot.values),
          payload: _bdFillSnapshot,
        });
      } catch (_e) {}
    }
    // Guided fill mode — same setting as Step 1 guided mode
    var _useGuidedFill = false;
    try { _useGuidedFill = eli.settings.get("build_draft.guidedMode") === true; } catch (_e) {}
    var _fillRenderer = (_useGuidedFill && renderGuidedFillForm) ? renderGuidedFillForm : renderTemplateFillForm;
    var _restoreIdx = (restoreOpts && typeof restoreOpts.guidedIdx === "number") ? restoreOpts.guidedIdx : 0;
    _fillRenderer({
      mount: mount,
      placeholders: placeholders,
      startIdx: _restoreIdx,
      diag: { textLen: scannedText.length },
      docText: scannedText,
      sourceText: sourceText,
      sourceName: sourceName,
      requesterName: _oarsMeta.requesterName,
      requester: _oarsMeta,
      prefillValues: prefillValues,
      onValuesChange: _persistSnapshot,
      // OARS data for guided mode right column
      oarsFields: (function () {
        try {
          var st = eli.dispatch ? eli.dispatch("oars", "getState") : null;
          if (!st || !st.text) return {};
          var oarsBundle = eli.tools._loaded["oars_loader"];
          var extractFn = oarsBundle && oarsBundle._eliEngineFns && oarsBundle._eliEngineFns.extractFieldsFromTablesData;
          if (extractFn && st.tablesData && st.tablesData.length) {
            var f = extractFn(st.tablesData);
            if (f && Object.keys(f).length) return f;
          }
          var parseFn = oarsBundle && oarsBundle._eliEngineFns && oarsBundle._eliEngineFns.parseOarsFields;
          if (parseFn) return parseFn(st.text) || {};
        } catch (_e) {}
        return {};
      })(),
      oarsTablesData: (function () {
        try {
          var st = eli.dispatch ? eli.dispatch("oars", "getState") : null;
          return (st && st.tablesData && st.tablesData.length) ? st.tablesData : [];
        } catch (_e) { return []; }
      })(),
      onProgress: function (info) {
        // Activity feed updates for guided fill progress — include currentIdx for restore
        if (!_useGuidedFill) return;
        var summ = info.filled + " of " + info.total + " filled";
        if (info.currentKey) summ += " · " + info.currentKey;
        _bdFillSnapshot.guidedIdx = info.currentIdx;
        if (_bdFillActivityId && eli.activity && typeof eli.activity.update === "function") {
          try {
            eli.activity.update(_bdFillActivityId, {
              summary: summ,
              payload: _bdFillSnapshot,
            });
          } catch (_e) {}
        }
      },
      onEmailRequester: function (missingLabels) {
        // Build subject from the user's filename pattern (minus DRAFT).
        // Reads from the settings registry so admin pushes apply.
        var patterns = {
          colgate: eli.settings.get("build_draft.fileNamePattern.colgate"),
          hills:   eli.settings.get("build_draft.fileNamePattern.hills"),
        };
        var isHills = /^h(ill|pn)/i.test(_oarsMeta.colgateEntity);
        var pat = isHills ? patterns.hills : patterns.colgate;
        // Strip the trailing (… DRAFT [Date]) tail per user spec —
        // handles the CP/HPN-prefixed parenthetical, e.g. "(CP DRAFT [Date])".
        var subject = pat
          .replace(/\s*\((?:CP |HPN )?DRAFT\s+\[Date\]\)\s*$/i, "")
          .replace("[Ref]",   _oarsMeta.cpRef            || "[CP Ref]")
          .replace("[Party]", _oarsMeta.thirdPartyEntity || "[Third Party]")
          .replace("[Type]",  _oarsMeta.agreementType    || "[Agreement Type]")
          .trim();

        // Salutation = requester's first name; sign-off = current user's
        // first name. Identity surface preferred; LS keys are the v2
        // fallback (and still in use today).
        var myName = "";
        try {
          if (eli.tools && typeof eli.tools.userIdentity === "function") {
            var ident = eli.tools.userIdentity() || {};
            myName = ident.firstName || ident.name || "";
          }
        } catch (_idErr) {}
        if (!myName) {
          try {
            myName = (eli.compat && eli.compat.lsGet)
              ? (eli.compat.lsGet("eli_user_first_name") || eli.compat.lsGet("userFirstName") || "")
              : "";
          } catch (_e) {}
        }
        var theirFirst = _firstNameOf(_oarsMeta.requesterName);
        var myFirst    = _firstNameOf(myName);

        var bulletList = (missingLabels || []).map(function (l) { return "  • " + l; }).join("\n");
        var body =
          "Dear " + (theirFirst || "team") + ":\n\n" +
          "Your OARS request for the above agreement is missing the following fields:\n" +
          bulletList + "\n\n" +
          "Can you please let me know the missing information?\n\n" +
          "Thanks,\n" +
          (myFirst || "");

        // 2026-05-27: Gmail compose URL (matches auto_emailer's pattern).
        // mailto: doesn't work in the Script Lab sandbox — Office.js
        // can't trigger the default mail client. Gmail web works because
        // it's a normal https:// URL that openBrowserWindow accepts.
        // CC tech_agreements@colpal.com to match auto_emailer's convention.
        var to = _oarsMeta.requesterEmail || "";
        var ccList = ["tech_agreements@colpal.com"];
        var toLower = String(to).toLowerCase().trim();
        ccList = ccList.filter(function (e) { return e.toLowerCase() !== toLower; });
        var url = "https://mail.google.com/mail/?view=cm&fs=1" +
          "&to="   + encodeURIComponent(to) +
          "&cc="   + encodeURIComponent(ccList.join(",")) +
          "&su="   + encodeURIComponent(subject) +
          "&body=" + encodeURIComponent(body);

        var hasObw = false;
        try {
          hasObw = !!(typeof Office !== "undefined" && Office.context && Office.context.ui &&
            typeof Office.context.ui.openBrowserWindow === "function");
        } catch (_e) {}
        try {
          eli.log.event("tool", "build_draft_email_requester_open", {
            missingCount: (missingLabels || []).length,
            hasRequesterEmail: !!to,
            isHills: isHills,
            hasObw: hasObw,
            urlLen: url.length,
          });
        } catch (_) {}

        if (hasObw) {
          try {
            Office.context.ui.openBrowserWindow(url);
            try { showToast("📧 Opening Gmail draft…", "ok"); } catch (_) {}
            return;
          } catch (_obwErr) {
            try { eli.log.event("tool", "build_draft_email_requester_obw_threw", { msg: _obwErr && _obwErr.message }); } catch (_) {}
          }
        }
        // Manual-open fallback dialog — copy link or open in browser.
        try {
          if (typeof showEliDialog === "function") {
            var bodyEl = document.createElement("div");
            var p = document.createElement("p");
            p.textContent = "Open your pre-filled Gmail draft, or copy the link and paste it into a new tab.";
            var urlBox = document.createElement("div");
            urlBox.textContent = url;
            urlBox.style.cssText = "margin-top:8px;padding:6px 8px;background:#f1f5f9;border:1px solid #cbd5e1;font-size:10px;color:#475569;word-break:break-all;max-height:54px;overflow:auto;user-select:all;";
            bodyEl.appendChild(p);
            bodyEl.appendChild(urlBox);
            showEliDialog({
              title: "Email Requester",
              icon: "✉️",
              body: bodyEl,
              primary: {
                label: "🌐 Open in Browser",
                onclick: function () {
                  try {
                    var a = document.createElement("a");
                    a.href = url; a.target = "_blank"; a.rel = "noopener noreferrer";
                    document.body.appendChild(a); a.click(); document.body.removeChild(a);
                  } catch (_e2) {
                    try { window.open(url, "_blank", "noopener,noreferrer"); } catch (_e3) {}
                  }
                },
              },
              secondary: {
                label: "📋 Copy Link",
                onclick: function () {
                  try { navigator.clipboard.writeText(url); } catch (_e) {}
                  try { showToast("Gmail link copied", "ok"); } catch (_) {}
                  return false; // keep dialog open
                },
              },
            });
          } else {
            try { navigator.clipboard.writeText(url); showToast("Gmail link copied", "ok"); } catch (_) {}
          }
        } catch (_dialogErr) {
          try { navigator.clipboard.writeText(url); showToast("Gmail link copied", "ok"); } catch (_) {}
        }
        try {
          eli.log.event("tool", "build_draft_email_requester_opened", {
            missingCount: (missingLabels || []).length,
            hasRequesterEmail: !!_oarsMeta.requesterEmail,
            isHills: isHills,
          });
        } catch (_) {}
      },
      onBack: function () {
        // Final snapshot before navigating away — make sure the feed
        // entry reflects what the user typed even if they didn't apply.
        _captureFillFormDom();
        _show({});
      },
      onLocate: eli.events.guard(function (placeholder, val) {
        _smartLocate(placeholder, val);
      }, "build_draft.fill_locate"),
      onPaymentHelper: eli.events.guard(function (placeholder, label, currentVal, cb) {
        // 2026-05-20: pre-fill flow. Opens the payment schedule modal
        // BEFORE Step 2 apply runs. The modal's apply callback returns
        // the formatted "due as follows: …" string which we write back
        // into the input field. Then during apply, the auto-modal that
        // normally fires for ![…] candidates is SKIPPED because the
        // field is already non-empty (see _runStep2Apply guard).
        //
        // Total-fee seed: if the form has a $![…] placeholder with a
        // filled value, use that. Otherwise pass empty so the modal
        // works in standalone "build a schedule" mode.
        var totalFee = "";
        try {
          var inputs = document.querySelectorAll("._eli3_bd_fill_input");
          for (var k = 0; k < inputs.length; k++) {
            var t = inputs[k].dataset.target || "";
            if (t.indexOf("$![") === 0 && inputs[k].value) {
              totalFee = inputs[k].value;
