        } catch (e) {
          eli.log.event("tool", "build_draft_payment_helper_failed", { msg: e && e.message });
          showToast("Payment helper failed: " + (e && e.message), "err");
        }
      }, "build_draft.fill_payment_helper"),
      onOarsLookup: eli.events.guard(function (placeholder, aiKey, label) {
        // 2026-05-20: open the OARS viewer and jump to the field/text
        // that matches the placeholder's OARS-side key. The viewer
        // accepts an optional searchTerm; oars_loader highlights the
        // first match in the Processed tab (parsed fields grid) or
        // falls back to highlighting in the Unprocessed raw text.
        var term = String(aiKey || label || "").trim();
        if (!term) { showToast("No OARS key to look up.", "warn"); return; }
        if (!_footerFile || !_footerFile.text) {
          showToast("No OARS data loaded — open a doc with OARS data first.", "warn");
          return;
        }
