        });
      }, "build_draft.autofill"),
      onUpload: eli.events.guard(function (file, phs, cb) {
        _readFileForFill(file, function (text, err) {
          if (err) { cb(null, err); return; }
          _aiFillPlaceholders(phs, text, function (mapping, err2) {
            try { cb(mapping, err2); } finally { setTimeout(_captureFillFormDom, 100); }
          });
        });
      }, "build_draft.fill_upload"),
      onApply: eli.events.guard(function (values) {
