        try {
          if (typeof _bdAuditSave === "function") {
            if (typeof _bdAuditEnsureRun === "function") _bdAuditEnsureRun(); // resume-safe
            var _aMeta = window._bdActiveDraftMeta || {};
            // Stash fills on the meta so later step-bumps (3/4) re-save them.
            try { _aMeta.auditStep2Fills = Object.assign({}, values || {}); } catch (_sfErr) {}
            var _aOars = {};
            try {
              var _aState = (eli.dispatch && typeof eli.dispatch === "function") ? eli.dispatch("oars", "getState") : null;
              if (typeof _extractOarsMetadata === "function") _aOars = _extractOarsMetadata(_aState) || {};
            } catch (_oarsErr) {}
            eli.events.safeAsync(_bdAuditSave(eli, {
              runId: _aMeta.auditRunId,
              startedAt: _aMeta.auditStartedAt,
              stepsReached: Math.max(_aMeta.auditStepsReached || 0, 2),
              stepsDone: _bdStepsDoneSnapshot(),
              stepTimes: _bdStepTimesSnapshot(),
              step1Answers: _aMeta.auditStep1Answers || {},
              step2Fills: values || {},
              cpRef: _aOars.cpRef || "",
              agreementType: String(_aMeta.draftType || _aMeta.templateType || _aOars.agreementType || ""),
              cpEntity: _aOars.colgateEntity || "",
              thirdParty: _aOars.thirdPartyEntity || "",
              requesterName: _aOars.requesterName || "",
              templateId: _aMeta.templateId || null,
              templateName: _aMeta.templateName || null,
              templateVersion: _aMeta.templateVersion || _aMeta.publishedAt || null,
            }), "build_draft.audit_capture");
          }
        } catch (_auditCapErr) {}
