        if (eli.activity && eli.activity.add) {
          eli.activity.add({
            type: "build-draft", icon: "📝", label: "Build Draft · Fill",
            summary: totalCount + " replacement(s) applied",
            payload: { count: totalCount },
          });
        }
        // ─── Field auto-refresh (2026-05-28) ──────────────────────────
        // Refresh every Word field NOW that the body content has
        // settled. TOC entries, page numbers, cross-refs, DATE/TIME,
        // STYLEREF, FORMULA all reflect the post-fill layout. Wrapped
        // with safeAsync — a misbehaving field can never block the
        // verification dialog or save flow that follows.
