          ? eli.events.safeAsync(_refreshAllFields(), "build_draft.refresh_fields")
              .catch(function (err) {
                eli.log.event("tool", "build_draft_refresh_fields_failed", { msg: err && err.message });
                // Swallow — fields-not-refreshed is a soft failure.
