        });
      })
      .catch(function (err) {
        _wizardMode = false;
        eli.log.event("tool", "build_draft_step2_apply_failed", { msg: err && err.message });
        showToast("Apply failed: " + (err && err.message), "err");
      });
  }

  // FROM v2 runPreSaveScan (line 22657). Searches for residual [...] bracket
  // markers that aren't red (red = "other"/"don't know" placeholders user
  // chose to leave). If any survive, opens the bracket cleaner; else
  // auto-advances per wizard mode.
  function _runPreSaveScan() {
    return eli.host.runRaw("build_draft:pre_save_scan", function (context) {
      var results = context.document.body.search("\\[[!]]@\\]", { matchWildcards: true });
      results.load("items");
      return context.sync().then(function () {
        for (var i = 0; i < results.items.length; i++) {
          results.items[i].font.load("color");
          results.items[i].load("text");
        }
        return context.sync().then(function () {
          var bracketsFound = [];
          for (var i2 = 0; i2 < results.items.length; i2++) {
            var item = results.items[i2];
            var color = (item.font.color || "").toLowerCase();
            var isRed = color === "#c62828" || color === "red" || color === "#ff0000";
            if (!isRed) {
              var text = item.text;
              if (text.indexOf("[[") === 0 && text.lastIndexOf("]]") !== text.length - 2) text = text + "]";
              bracketsFound.push({ text: text, inner: text.replace(/^\[+|\]+$/g, "") });
            }
          }
          return bracketsFound;
        });
      });
    }).then(function (items) {
      if (items.length) {
        showToast("🧹 " + items.length + " placeholder(s) need review.", "warn");
        _showPreSaveCleaner(items);
        return;
      }
      if (_wizardMode) {
        showToast("🚀 Clean. Proceeding to Step 3…", "ok");
        setTimeout(function () { _runStep3ErrorReview(); }, 600);
      } else {
        showToast("✅ Clean & Verified", "ok");
        setTimeout(function () { _show({}); }, 600);
      }
    }).catch(function (err) {
      eli.log.event("tool", "build_draft_presave_failed", { msg: err && err.message });
      // Fall through to hub on scan failure — user can retry.
      _show({});
    });
  }

  // Mounts the bracket cleaner panel on the pre-save items. onDone wires
  // back into the wizard chain (advance to Step 3) or the hub.
  function _showPreSaveCleaner(items) {
    if (!renderBracketCleaner) { _show({}); return; }
    var mount = document.getElementById("_eli3_dashboard_root");
    eli.events.safeAsync(eli.storage.getAll("cleaner_rules"), "build_draft.cleaner_rules")
      .then(function (rules) {
        renderBracketCleaner({
          mount: mount,
          brackets: { items: items },
          financial: { items: [] },
          cleanerRules: rules || [],
          onBack: function () { _show({}); },
          onDone: function () {
            if (_wizardMode) {
              showToast("🚀 Proceeding to Step 3…", "ok");
              setTimeout(function () { _runStep3ErrorReview(); }, 400);
            } else {
              _show({});
            }
          },
          onLocate: eli.events.guard(function (row) {
            eli.events.safeAsync(
              eli.host.runRaw("build_draft:locate", function (context) {
                var body = context.document.body;
                var found = body.search(row.text, { matchCase: false, matchWholeWord: false });
                found.load("items");
                return context.sync().then(function () {
                  if (found.items.length) { found.items[0].select(); return context.sync(); }
                });
              }),
              "build_draft.locate"
            );
          }, "build_draft.locate"),
          onSowHelper: eli.events.guard(function (row) {
            if (!row.rule || !renderSowHelper) return;
            renderSowHelper({
              rule: row.rule,
              target: row.text,
              onPick: eli.events.guard(function (picked) {
                eli.events.safeAsync(
                  eli.host.runRaw("build_draft:replace", function (context) {
                    var body = context.document.body;
                    var found = body.search(row.text, { matchCase: false, matchWholeWord: false });
                    found.load("items");
                    return context.sync().then(function () {
                      if (found.items.length) {
                        found.items[0].insertText(picked.text, "Replace");
                        return context.sync();
                      }
                    });
                  }),
                  "build_draft.replace"
                ).then(function () { showToast("✅ Inserted: " + picked.label, "ok"); });
              }, "build_draft.sow.pick"),
            });
          }, "build_draft.sow"),
        });
      });
  }

  // One batch = up to STEP2_APPLY_BATCH keys × (body + per-section
  // headers/footers). Returns the count of replacements made.
  //
  // 2026-05-19 v10: linkage detection rewritten to text-equality runtime
  // check. Prior v7 inspected each section's body OOXML for <w:titlePg/>
  // (DifferentFirstPage) and <w:evenAndOddHeaders/> (EvenAndOdd) to
  // decide which H/F types to search. That worked for single-section
  // docs with clear sectPr flags but missed two cases the diagnostic
  // surfaced on the Services Agreement template:
  //   1. <w:evenAndOddHeaders/> lives in word/settings.xml, NOT in
  //      sec.body.getOoxml() — so the v7 check was almost always
  //      false-negative for EvenPages.
  //   2. Multi-section docs with Word's default "Link to Previous"
  //      have section 1's Primary/FirstPage/EvenPages physically
  //      aliased to section 0's. v7 happily searched all sections,
  //      hitting the same physical placeholder twice through different
  //      section aliases — producing the "ZymoZymo" doubling on fill.
  //
  // The v10 approach: load each (section, type, header/footer) slot's
  // current text BEFORE searching. Build a "unique slots" set by
  // skipping any slot whose text matches a slot already seen. Only
  // queue searches on unique slots. Linked aliases drop out automatically.
  function _step2_applyBatch(batch, values, tagsToKill, paymentCandidates) {
    var hl = _highlightFillEnabled();
    return eli.host.runRaw("build_draft:step2_apply_batch_batched", function (context) {
      var sections = context.document.sections;
      sections.load("items");
      return context.sync().then(function () {
        var searchOpts = { matchCase: false, ignoreSpace: true, ignorePunctuation: false };
        var HF_TYPES_LOCAL = ["Primary", "FirstPage", "EvenPages"];
        // 2026-05-20 v11: load section OOXML alongside H/F text. Need
        // OOXML to detect <w:titlePg/> (DifferentFirstPage) and
        // <w:evenAndOddHeaders/> per section. Text alone can't
        // distinguish "physically distinct but identical text" from
        // "linked alias" — the OOXML flag is the authoritative signal.
        var sectionOoxmlReqs = [];
        for (var __osi = 0; __osi < sections.items.length; __osi++) {
          try { sectionOoxmlReqs.push(sections.items[__osi].body.getOoxml()); }
          catch (_e) { sectionOoxmlReqs.push(null); }
        }
        // Pre-load every section's H/F text so we can dedupe linked
        // physical parts by text equality after the sync.
        var slotLoads = []; // [{section, type, isHeader, ref}]
        for (var __spi = 0; __spi < sections.items.length; __spi++) {
          var __sec = sections.items[__spi];
          HF_TYPES_LOCAL.forEach(function (t) {
            try {
              var h = __sec.getHeader(t);
              h.load("text");
              slotLoads.push({ section: __spi, type: t, isHeader: true, ref: h });
            } catch (_e) {}
            try {
              var f = __sec.getFooter(t);
              f.load("text");
              slotLoads.push({ section: __spi, type: t, isHeader: false, ref: f });
            } catch (_e) {}
          });
        }
        var jobs = [];
        batch.forEach(function (key) {
          var rawVal = String(values[key]);
          var isPaymentTrigger = key.indexOf("$![") === 0;
          // FROM v2 line 6821: ![ (no leading $) → schedule candidate.
          // $![ already starts with $, so check is exclusive.
          var isPaymentCandidate = !isPaymentTrigger && key.indexOf("![") === 0;
          var isCurrency = isPaymentTrigger || key.indexOf("$[") === 0;
          var finalVal = rawVal;
          // 2026-05-19: format numeric money values as XX,XXX.XX.
          // - Currency placeholders ($[ / $![) always try to format and
          //   prepend $ (replacing any leading $ that was already there).
          // - Plain placeholders with money-keyword labels (fee/payment/
          //   cost/price/amount/dollar/usd) format the number but do NOT
          //   prepend $ — the template author likely already wrote $ in
          //   surrounding prose ("Total fee: $[[Total Fee]]").
          // - Non-numeric values bail and pass through unchanged.
          if (isCurrency || _bd_isLikelyMoneyPlaceholder(key)) {
            var m = _bd_formatMoneyValue(rawVal);
            if (m) {
              finalVal = isCurrency ? ("$" + m.formatted)
                : (m.hadDollar ? ("$" + m.formatted) : m.formatted);
            } else if (isCurrency && finalVal.trim().charAt(0) !== "$") {
              finalVal = "$" + finalVal;
            }
          }
          // Preserve newlines — _bdInsertText decides single-line vs <br>.
          var insertVal = String(finalVal);
          if (isPaymentTrigger) tagsToKill.push(key);
          if (isPaymentCandidate && paymentCandidates) {
            // Record the candidate but DON'T replace its marker in this
            // batch — leave "![[…]]" in the doc so the payment-schedule
            // modal callback can find it and overwrite it with the
            // "due as follows: …" string. Previously the standard batch
            // replaced it with the raw value first, so the modal's
            // search missed it and the schedule string (incl. "due as
            // follows") was silently dropped. (paymentCandidates is null
            // on the modal-callback re-entry, so that path still fills it.)
            paymentCandidates.push({ target: key, val: rawVal });
            return;
          }
          // Body search: queue immediately (no linkage concern in body).
          // Tagged shape ({rng, isBody}) — review-nav only bookmarks body
          // fills (cross-scope H/F bookmark resolution isn't worth it yet).
          var ranges = [];
          var bodyRes = context.document.body.search(key, searchOpts);
          bodyRes.load("items");
          ranges.push({ rng: bodyRes, isBody: true });
          // Defer header/footer searches — we need the resolved slot
          // texts first (next sync) so we can dedupe linked aliases.
          jobs.push({ insertVal: insertVal, ranges: ranges, key: key });
        });
        // First sync: resolve body searches + all H/F text loads +
        // per-section OOXML.
        return context.sync().then(function () {
          // 2026-05-20 v11 hybrid dedup. Two-pass:
          //   PASS 1 (within section): drop FirstPage/EvenPages slots
          //   that are aliases of Primary. The OOXML flag is the
          //   authoritative signal — <w:titlePg/> means FirstPage is
          //   physically distinct; without it, FirstPage IS Primary
          //   under the hood. Same logic for EvenPages with
          //   <w:evenAndOddHeaders/>. Reported bug 2026-05-20: previous
          //   text-only dedup wrongly removed FirstPage footer when its
          //   text happened to match Primary footer (both just
          //   `[[CP Ref #]]`), even though titlePg WAS set — leaving
          //   the FirstPage footer unfilled.
          //
          //   PASS 2 (cross-section): drop slots whose text matches a
          //   same-type slot from an earlier section. Word's default
          //   "Link to Previous" makes section N's Primary the same
          //   physical part as section N-1's Primary; we can't detect
          //   that via section OOXML, so text equality is the signal.
          // 2026-05-20 v12: cross-section dedup switched from text
          // equality to <w:headerReference> / <w:footerReference>
          // presence in sectPr. User reported: section 1's Primary
          // footer has same TEXT as section 0's ("[[CP Ref #]]" in
          // both), but they're physically DISTINCT (Link to Previous
          // is off). v11's text-equality wrongly skipped section 1 →
          // unfilled footer on the last pages.
          //
          // The OOXML signal: Word writes an explicit
          // <w:headerReference w:type="default" r:id="..."/> only
          // when the section owns its header. Absent reference =
          // inherits from previous section (linked). Same for footers.
          // This is the AUTHORITATIVE linkage signal — works regardless
          // of whether the text matches.
          var sectionFlags = [];
          for (var __sfi = 0; __sfi < sections.items.length; __sfi++) {
            var __secOoxml = "";
            try { __secOoxml = String((sectionOoxmlReqs[__sfi] && sectionOoxmlReqs[__sfi].value) || ""); }
            catch (_e) {}
            sectionFlags.push({
              hasDiffFirstPage: /<w:titlePg\b/i.test(__secOoxml),
              hasEvenAndOdd:    /<w:evenAndOddHeaders\b/i.test(__secOoxml),
              // Explicit references — presence means "this section owns
              // its own H/F for this type" (not linked to previous).
              headerRefs: {
                Primary:   /<w:headerReference[^>]+w:type="default"/i.test(__secOoxml),
                FirstPage: /<w:headerReference[^>]+w:type="first"/i.test(__secOoxml),
                EvenPages: /<w:headerReference[^>]+w:type="even"/i.test(__secOoxml),
              },
              footerRefs: {
                Primary:   /<w:footerReference[^>]+w:type="default"/i.test(__secOoxml),
                FirstPage: /<w:footerReference[^>]+w:type="first"/i.test(__secOoxml),
                EvenPages: /<w:footerReference[^>]+w:type="even"/i.test(__secOoxml),
              },
            });
          }
          var uniqueSlots = [];
          var skippedDiag = [];
          slotLoads.forEach(function (slot) {
            var flags = sectionFlags[slot.section] || {
              hasDiffFirstPage: false, hasEvenAndOdd: false,
              headerRefs: {}, footerRefs: {},
            };
            // PASS 1 — within-section physicality (titlePg / evenAndOdd).
            var isOwnPhysicalPart;
            if (slot.type === "Primary") isOwnPhysicalPart = true;
            else if (slot.type === "FirstPage") isOwnPhysicalPart = flags.hasDiffFirstPage;
            else if (slot.type === "EvenPages") isOwnPhysicalPart = flags.hasEvenAndOdd;
            else isOwnPhysicalPart = false;
            if (!isOwnPhysicalPart) {
              skippedDiag.push({
                section: slot.section, type: slot.type, isHeader: slot.isHeader,
                reason: "within-section alias of Primary (no " +
                  (slot.type === "FirstPage" ? "titlePg" : "evenAndOddHeaders") + " flag)",
              });
              return;
            }
            // PASS 2 — cross-section linkage via explicit reference
            // presence. Section 0 always owns its slot. Sections >0
            // own their slot iff sectPr has an explicit reference for
            // that type; absence means inherits-from-previous → skip.
            if (slot.section > 0) {
              var refMap = slot.isHeader ? flags.headerRefs : flags.footerRefs;
              var hasOwnRef = refMap && refMap[slot.type];
              if (!hasOwnRef) {
                skippedDiag.push({
                  section: slot.section, type: slot.type, isHeader: slot.isHeader,
                  reason: "linked to previous section (no explicit " +
                    (slot.isHeader ? "headerReference" : "footerReference") +
                    " w:type=\"" +
                    (slot.type === "Primary" ? "default" :
                     slot.type === "FirstPage" ? "first" : "even") +
                    "\")",
                });
                return;
              }
            }
            uniqueSlots.push(slot);
          });
          try {
            eli.log.event("tool", "build_draft_apply_slot_dedup", {
              version: "v12-ooxml-refs",
              totalSlots: slotLoads.length,
              uniqueSlots: uniqueSlots.length,
              sectionFlags: sectionFlags,
              skippedAliases: skippedDiag,
            });
          } catch (_e) {}
          // Queue searches on every unique slot for every job.
          jobs.forEach(function (j) {
            uniqueSlots.forEach(function (slot) {
              try {
                var hr = slot.ref.search(j.key, searchOpts);
                hr.load("items");
                j.ranges.push({ rng: hr, isBody: false });
              } catch (e) {
                eli.log.event("tool",
                  slot.isHeader ? "build_draft_apply_header_skip" : "build_draft_apply_footer_skip",
                  { msg: e && e.message, section: slot.section, type: slot.type });
              }
            });
          });
          // Second sync: resolve all H/F searches.
          return context.sync().then(function () {
            var count = 0;
            var navOn = _bdReviewNavEnabled();
            jobs.forEach(function (j) {
              j.ranges.forEach(function (entry) {
                var rng = entry.rng;
                var isBody = entry.isBody;
                // Back-to-front insert order = forward doc order after
                // all replacements land. Reverse the per-range trail
                // additions below so _bdReviewTrail ends up in doc order.
                var trailAdditions = [];
                for (var k = rng.items.length - 1; k >= 0; k--) {
                  var ins = _bdInsertText(rng.items[k], j.insertVal);
                  if (hl) ins.font.highlightColor = "Yellow";
                  count++;
                  if (navOn && isBody && ins) {
                    // Bookmark name assigned later (after doc-order sort)
                    // so we just stash the range + meta here.
                    trailAdditions.push({
                      ins: ins,
                      key: j.key,
                      value: String(j.insertVal == null ? "" : j.insertVal).substring(0, 200),
                    });
                  }
                }
                // Reverse so the first item in the doc lands first in the trail.
                trailAdditions.reverse().forEach(function (t) {
                  var n = _bdReviewTrail.length + 1;
                  var name = _bdReviewBookmarkName(n);
                  try { t.ins.insertBookmark(name); } catch (_e) {}
                  _bdReviewTrail.push({ name: name, key: t.key, value: t.value });
                });
              });
            });
            return context.sync().then(function () { return count; });
          });
        });
      });
    });
  }

  // FROM v2 findSmartMatch (line 12700). Body → smart-quote-normalized
  // body → headers/footers across all sections → mid-string fallback.
  // Selects the first match it finds and toasts the location, so the
  // user knows whether it was in the body or a header/footer.
  function _smartLocate(needle, fallbackVal) {
    var text = String(needle || "").replace(/[\r\n\t]+/g, " ").trim();
    if (!text) { showToast("Nothing to locate.", "warn"); return Promise.resolve(); }
    return eli.host.runRaw("build_draft:smart_locate", function (context) {
      var searchOpts = { matchCase: false, ignoreSpace: true };
      var query = text.substring(0, 250);
      var body = context.document.body;
      var bodyRes = body.search(query, searchOpts);
      bodyRes.load("items");
      return context.sync().then(function () {
        if (bodyRes.items.length) {
          bodyRes.items[0].select();
          return context.sync().then(function () { return "body"; });
        }
        // Smart-quote normalization fallback (curly quotes vs straight).
        var smartQuoted = query
          .replace(/"/g, function (m, off, s) {
            var prior = (s.substring(0, off).match(/"/g) || []).length;
            return prior % 2 === 0 ? "“" : "”";
          })
          .replace(/'/g, "’");
        if (smartQuoted !== query) {
          var sq = body.search(smartQuoted, searchOpts);
          sq.load("items");
          return context.sync().then(function () {
            if (sq.items.length) {
              sq.items[0].select();
              return context.sync().then(function () { return "body (smart quotes)"; });
            }
            return _searchHF(context, query, searchOpts);
          });
        }
        return _searchHF(context, query, searchOpts);
      });
    }).then(function (where) {
      if (where) { showToast("📍 Found in " + where, "ok"); return; }
      // Fallback: search the filled value if locate-by-placeholder failed.
      if (fallbackVal && String(fallbackVal).trim().length > 1) {
        return _smartLocate(String(fallbackVal).trim(), null).then(function () {});
      }
      showToast("⚠️ Not found in document", "warn");
    }).catch(function (err) {
      eli.log.event("tool", "build_draft_locate_failed", { msg: err && err.message });
      showToast("Locate failed: " + (err && err.message), "err");
    });
  }

  // Helper: walk every section's H/F looking for the query. Selects
  // first match; returns where (string) or null.
  function _searchHF(context, query, searchOpts) {
    var sections = context.document.sections;
    sections.load("items");
    return context.sync().then(function () {
      var chain = Promise.resolve(null);
      for (var s = 0; s < sections.items.length; s++) {
        (function (sec, idx) {
          for (var ti = 0; ti < HF_TYPES.length; ti++) {
            (function (t) {
              chain = chain.then(function (found) {
                if (found) return found;
                try {
                  var f = sec.getFooter(t).search(query, searchOpts);
                  f.load("items");
                  return context.sync().then(function () {
                    if (f.items.length) {
                      f.items[0].select();
                      return context.sync().then(function () { return "footer (" + t + ", section " + idx + ")"; });
                    }
                    var h = sec.getHeader(t).search(query, searchOpts);
                    h.load("items");
                    return context.sync().then(function () {
                      if (h.items.length) {
                        h.items[0].select();
                        return context.sync().then(function () { return "header (" + t + ", section " + idx + ")"; });
                      }
                      return null;
                    });
                  });
                } catch (e) { return null; }
              });
            })(HF_TYPES[ti]);
          }
        })(sections.items[s], s);
      }
      return chain;
    });
  }

  // Read v2 user-setting `highlightFill` (default true). Stored in
  // eli_user_settings as a JSON object.
  function _highlightFillEnabled() {
    try {
      var raw = eli.compat.lsGet("eli_user_settings");
      if (!raw) return true; // default ON
      var s = JSON.parse(raw);
      return s.highlightFill !== false;
    } catch (e) { return true; }
  }

  // Clear yellow highlight from body + every H/F across all sections.
  // Called after the user clicks "Looks Good" in the verification dialog.
  function _clearAllHighlights() {
    return eli.host.runRaw("build_draft:clear_hl", function (context) {
      context.document.body.font.highlightColor = null;
      var sections = context.document.sections;
      sections.load("items");
      return context.sync().then(function () {
        for (var i = 0; i < sections.items.length; i++) {
          var sec = sections.items[i];
          for (var j = 0; j < HF_TYPES.length; j++) {
            try { sec.getHeader(HF_TYPES[j]).font.highlightColor = null; } catch (e) {}
            try { sec.getFooter(HF_TYPES[j]).font.highlightColor = null; } catch (e) {}
          }
        }
        return context.sync();
      });
    });
  }

  // Refresh every Word field in the document (body + headers + footers)
  // programmatic equivalent of select-all + F9. Runs after Step 2 fill so
  // TOC entries, page numbers, cross-refs, dates, FORMULA fields, etc.
  // reflect the now-final body. Fully wrapped — per-field, per-section,
  // per-HF-getter try/catch so a single broken field never tanks the
  // whole pass. Returns the refresh count for telemetry.
  function _refreshAllFields() {
    var _t0 = Date.now();
    try { eli.log.event("tool", "build_draft_refresh_fields_started", { ts: _t0 }); } catch (_e) {}
    // 2026-05-29: rewritten to use context.document.fields (one collection
    // spanning body + headers + footers) and field.updateResult() — the
    // per-section getHeader/getFooter + field.update() approach didn't
    // refresh on the user's Word build. Auto-unlocks locked fields first.
    return eli.host.runRaw("build_draft:refresh_fields", function (context) {
      var fields = context.document.fields;
      fields.load("items/locked");
      return context.sync().then(function () {
        var found = (fields.items && fields.items.length) || 0;
        try { eli.log.event("tool", "build_draft_refresh_fields_scan", { fieldsFound: found }); } catch (_e) {}
        var updated = 0, unlocked = 0, errs = 0;
        for (var i = 0; i < found; i++) {
          var fld = fields.items[i];
          try {
            if (fld.locked) { fld.locked = false; unlocked++; }
            fld.updateResult();
            updated++;
          } catch (_e) { errs++; }
        }
        return context.sync().then(function () {
          var elapsed = Date.now() - _t0;
          try {
            eli.log.event("tool", "build_draft_refresh_fields_done", {
              fieldsFound: found, updated: updated, unlocked: unlocked,
              errors: errs, elapsedMs: elapsed,
            });
          } catch (_e) {}
          return updated;
        });
      });
    });
  }

  // FROM v2 showVerificationModal (line 7015). Premium dialog showing
  // count of filled fields with "Looks Good" button that clears the
  // yellow highlights and proceeds to pre-save scan.
  // Premium confirmation dialog shown when OARS detection auto-matches
  // a template. Replaces silent auto-load. Mascot rendered via the
  // eli_mascot_studio public API; falls back to a robot emoji if the
  // mascot tool isn't loaded.
  function _showOarsConfirmDialog(tpl, detectedType, handlers) {
    if (typeof showEliDialog !== "function") {
      // Kernel dialog primitive missing — fall back to immediate load
      // so we don't strand the user without any template.
      try { handlers.onConfirm(); } catch (_e) {}
      return;
    }
    function _esc(s) {
      return String(s == null ? "" : s)
        .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
    }
    var mascotSvg = "";
    try {
      if (eli.ui && typeof eli.ui.mascot === "function") mascotSvg = eli.ui.mascot();
    } catch (_e) {}
    var mascotHtml = mascotSvg
      ? '<div style="display:flex;justify-content:center;margin-bottom:14px;">' +
          '<div style="width:150px;height:150px;">' + mascotSvg + '</div>' +
        '</div>'
      : '<div style="text-align:center;font-size:56px;line-height:1;margin-bottom:14px;">🤖</div>';
    var typeName = _esc(detectedType || "agreement");
    var tplName  = _esc((tpl && tpl.name) || "matching template");
    // Capture the dialog overlay via onMount so we have a guaranteed
    // reference for explicit close + in-place content swap (loading
    // state).
    var dialogOverlay = null;
    // Mascot animation CSS — registered once per dialog open.
    // bdMascotBob: gentle vertical bob.
    // bdProgressSlide: indeterminate slider that traverses the bar.
    // bdMascotWiggle: subtle rotation for personality during loading.
    var animStyleId = "_bd_oars_anim_" + Date.now();
    function _ensureAnimStyle() {
      if (document.getElementById(animStyleId)) return;
      var st = document.createElement("style");
      st.id = animStyleId;
      st.textContent =
        "@keyframes _bdMascotBob{0%,100%{transform:translateY(0) rotate(-2deg)}50%{transform:translateY(-10px) rotate(2deg)}}" +
        "@keyframes _bdProgressSlide{0%{transform:translateX(-100%)}100%{transform:translateX(400%)}}" +
        "@keyframes _bdDotFade{0%,80%,100%{opacity:0.3}40%{opacity:1}}";
      document.head.appendChild(st);
    }
    function _renderLoadingHtml() {
      _ensureAnimStyle();
      return '<div style="text-align:center;">' +
          '<div style="display:flex;justify-content:center;margin-bottom:14px;">' +
            '<div style="width:150px;height:150px;animation:_bdMascotBob 1.4s ease-in-out infinite;transform-origin:center bottom;">' +
              (mascotSvg || '<div style="font-size:90px;line-height:150px;">🤖</div>') +
            '</div>' +
          '</div>' +
          '<div style="font-size:17px;color:#3a3528;line-height:1.4;">' +
            'Loading <b style="color:#1d3a8a;">' + tplName + '</b>' +
