    function _swapToLoading() {
      // Mutate the OPEN dialog: replace body content with loading state,
      // hide buttons + close X so the user can't bail mid-load.
      if (!dialogOverlay) return;
      try {
        var desc = dialogOverlay.querySelector(".eli-dialog-desc");
        if (desc) desc.innerHTML = "<p>" + _renderLoadingHtml() + "</p>";
        var actions = dialogOverlay.querySelector(".eli-dialog-actions");
        if (actions) actions.style.display = "none";
        var closeBtn = dialogOverlay.querySelector(".eli-dialog-close");
        if (closeBtn) closeBtn.style.display = "none";
        // Also swap the title to make it feel like a different state.
        var titleEl = dialogOverlay.querySelector(".eli-dialog-title");
        if (titleEl) titleEl.textContent = "Loading Template";
