    // Tag with a unique class so the fallback nuke targets ONLY this
    // dialog, not any other .eli-overlay that happens to be on screen.
    var tagClass = "eli-overlay-oars-confirm-" + Date.now();
    function _closeDialog() {
      var nuked = 0;
      // 1. Captured-at-mount overlay.
      try {
        if (dialogOverlay && dialogOverlay.parentNode) {
          dialogOverlay.parentNode.removeChild(dialogOverlay);
          nuked++;
        }
      } catch (_e) {}
      // 2. Class-tagged overlay (in case onMount wasn't called).
      try {
        var tagged = document.querySelectorAll("." + tagClass);
        for (var i = 0; i < tagged.length; i++) {
          if (tagged[i].parentNode) { tagged[i].parentNode.removeChild(tagged[i]); nuked++; }
        }
      } catch (_e) {}
      // 3. NUCLEAR: any remaining .eli-overlay. At OARS detection time
      // no other modal should be open — the dashboard isn't even fully
      // rendered yet. If another dialog WAS up, the user clicking our
      // button signals intent to advance, so collapsing the stack is
      // the right call.
      try {
        var all = document.querySelectorAll(".eli-overlay");
        for (var j = 0; j < all.length; j++) {
          if (all[j].parentNode) { all[j].parentNode.removeChild(all[j]); nuked++; }
        }
      } catch (_e) {}
      // 4. Nuke the OARS boot overlay (full-screen white spinner from
      // oars_loader.renderOverlay() — sits at z-index 99999 BEHIND the
      // dialog; dismisses on oars:ready but the signal may be lost).
      try {
        var bootOv = document.getElementById("_eli3_oars_overlay");
        if (bootOv && bootOv.parentNode) { bootOv.parentNode.removeChild(bootOv); nuked++; }
      } catch (_e) {}
      // 5. Re-emit oars:ready for any other waiting listeners.
      try { if (eli.bus) eli.bus.emit("oars:ready", { ts: Date.now() }); } catch (_e) {}
      // Diag: visible in console when eli.debug(true) is on.
      try { eli.log.event("tool", "build_draft_oars_dialog_closed", { nuked: nuked }); } catch (_e) {}
    }
    showEliDialog({
      variant: "info",
      tier: "premium",
      size: "wide",
      title: "OARS Detected",
      dialogClass: tagClass,
      onMount: function (ov) { dialogOverlay = ov; if (ov) ov.classList.add(tagClass); },
      paragraphs: [
        mascotHtml +
        '<div style="text-align:center;font-size:17px;color:#3a3528;margin-bottom:8px;line-height:1.4;">' +
          'I detected a <b style="color:#1d3a8a;">' + typeName + '</b>.' +
        '</div>' +
        '<div style="text-align:center;font-size:14px;color:#6b624a;line-height:1.5;">' +
          'Want me to load the <b>' + tplName + '</b> template?' +
        '</div>',
      ],
      primary: {
        label: "✅ Yes — Load Template",
        // Stay open + swap to mascot loading state. Auto-close when the
        // load promise settles (resolve OR reject — _doAutoLoad handles
        // its own error toast in the catch).
        // Return false from onclick to suppress showEliDialog's default
        // auto-close. We close manually after the load.
        onclick: function () {
          _swapToLoading();
          var p = null;
          try { p = handlers.onConfirm(); } catch (_e) {}
          if (p && typeof p.then === "function") {
            p.then(_closeDialog, _closeDialog);
          } else {
            // Handler didn't return a promise — close after a short beat
            // so user still sees the loading state momentarily.
            setTimeout(_closeDialog, 800);
          }
          return false; // keep dialog open
        },
      },
      secondary: {
        label: "📁 Choose Different",
        onclick: function () { _closeDialog(); try { handlers.onChoose(); } catch (_e) {} },
      },
      tertiary: {
        label: "Skip",
        onclick: function () { _closeDialog(); try { handlers.onSkip(); } catch (_e) {} },
      },
    });
  }

