              'style="background:linear-gradient(180deg,#fafaf8,#e9e6da);border:1px solid #c4bea8;border-radius:6px;padding:4px 12px;font-size:16px;cursor:pointer;color:#3a3528;" ' +
              'title="Previous change">‹</button>' +
            '<div style="flex:1;min-width:0;text-align:center;">' +
              '<div id="_bd_review_counter" style="font-size:12px;color:#6b624a;font-weight:600;letter-spacing:0.04em;">1 of ' + _bdReviewTrail.length + '</div>' +
              '<div id="_bd_review_key" style="font-family:Consolas,monospace;font-size:13px;color:#1d3a8a;margin-top:2px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">' + firstKey + '</div>' +
              '<div id="_bd_review_val" style="font-size:12px;color:#3a3528;margin-top:2px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:100%;">' + firstVal + '</div>' +
            '</div>' +
