      // saved-as-draft state to version_history so the user has a
      // recoverable point. No-ops if version_history isn't installed.
      try {
        if (eli.get && typeof eli.get("version_history", "snapshot") === "function") {
          eli.dispatch("version_history", "snapshot", {
            label: "CP Version: " + formData.filename +
              (formData.executionMode ? " [EXECUTION COPY]" : " [Original Version]"),
