  background: #eff6ff;
  border-bottom: 1px solid #bfdbfe;
  font: 600 11px/1.4 'Inter', sans-serif;
  color: #1e40af;
}
._eli3_bd_save_spinner {
  width: 14px; height: 14px;
  border: 2px solid #93c5fd;
  border-top-color: #1565c0;
  border-radius: 50%;
  animation: _eli3_bd_save_spin 0.8s linear infinite;
}
@keyframes _eli3_bd_save_spin { to { transform: rotate(360deg); } }
._eli3_bd_save_form {
  flex: 1 1 auto;
  overflow-y: auto;
  padding: 14px;
  display: flex; flex-direction: column; gap: 6px;
}
._eli3_bd_save_label {
  font: 700 11px/1.2 'Inter', sans-serif;
  text-transform: uppercase; letter-spacing: 0.4px;
  color: #0f172a; margin-top: 6px;
}
._eli3_bd_save_input {
  width: 100%;
  padding: 8px 10px;
  border: 1px solid #cbd5e1;
  background: #fff;
  font: 500 13px/1.3 'Inter', sans-serif;
  color: #0f172a;
  box-sizing: border-box;
  outline: none;
}
._eli3_bd_save_input:focus {
  border-color: #1565c0;
  box-shadow: 0 0 0 2px rgba(21,101,192,0.18);
}
._eli3_bd_save_hidden { display: none !important; }

/* FROM v2 IS_EXECUTION_MODE toggle — amber accent so it stands out. */
._eli3_bd_save_execmode {
  display: flex; align-items: flex-start; gap: 10px;
  margin-top: 12px;
  padding: 10px 12px;
  background: linear-gradient(180deg, #fffbeb 0%, #fef3c7 100%);
  border: 1px solid #fde68a;
  border-left: 4px solid #f59e0b;
  cursor: pointer;
  user-select: none;
}
._eli3_bd_save_execmode input[type="checkbox"] {
  margin: 2px 0 0 0;
  flex: 0 0 auto;
  accent-color: #d97706;
  width: 16px; height: 16px;
}
._eli3_bd_save_execmode_main {
  display: flex; flex-direction: column; gap: 2px;
}
._eli3_bd_save_execmode_label {
  font: 800 11px/1.2 'Inter', sans-serif;
  color: #92400e;
  letter-spacing: 0.3px;
}
._eli3_bd_save_execmode_hint {
  font: 500 10px/1.3 'Inter', sans-serif;
  color: #b45309;
  font-style: italic;
}
._eli3_bd_save_preview {
  margin-top: 12px;
  padding: 10px 12px;
  background: #f5f5f5;
  border: 1px solid #e2e8f0;
  display: flex; flex-direction: column; gap: 4px;
}
._eli3_bd_save_preview_label {
  font: 700 10px/1 'Inter', sans-serif;
  text-transform: uppercase; letter-spacing: 0.5px;
  color: #64748b;
}
._eli3_bd_save_preview_value {
  font: 600 12px/1.4 monospace;
  color: #0f172a; word-break: break-all;
}
/* Skip + Save row — equal-width buttons, save on the right (primary). */
._eli3_bd_save_actions {
  display: flex;
  gap: 8px;
  margin-top: 14px;
}
._eli3_bd_save_skip {
  flex: 1;
  background: linear-gradient(180deg, #fff 0%, #f1f5f9 100%);
  border: 1px solid #cbd5e1;
  font: 700 11px/1 'Inter', sans-serif;
  text-transform: uppercase; letter-spacing: 0.4px;
  color: #475569;
  padding: 10px 14px;
  cursor: pointer;
  transition: all 0.15s;
}
._eli3_bd_save_skip:hover {
  background: linear-gradient(180deg, #f8fafc 0%, #e2e8f0 100%);
  color: #0f172a;
  border-color: #94a3b8;
}
._eli3_bd_save_btn {
  flex: 1.6;
  display: inline-flex; align-items: center; justify-content: center; gap: 8px;
  background: linear-gradient(135deg, #1565c0 0%, #0d47a1 100%);
  color: #fff;
  border: 1px solid #0d47a1;
  font: 700 12px/1 'Inter', sans-serif;
  text-transform: uppercase; letter-spacing: 0.5px;
  padding: 10px 14px;
  cursor: pointer;
  transition: all 0.15s;
  box-shadow: 0 2px 6px rgba(21, 101, 192, 0.25);
}
._eli3_bd_save_btn:hover:not(:disabled) {
  background: linear-gradient(135deg, #1d4ed8 0%, #1565c0 100%);
  transform: translateY(-1px);
  box-shadow: 0 4px 12px rgba(21, 101, 192, 0.35);
}
._eli3_bd_save_btn:disabled { opacity: 0.6; cursor: progress; }
._eli3_bd_save_btn_icon { font-size: 14px; line-height: 1; }
._eli3_bd_save_btn_label { white-space: nowrap; }

/* ─── Filename builder + copy-paste block (2026-05-16 rework) ─── */
/* Big monospace filename target — click-to-select, prominent copy
   button below, ack toast slot below the button. Replaces the small
   inline preview pill. */
._eli3_bd_fn_block {
  margin: 14px 0 8px;
  padding: 14px;
  background: linear-gradient(180deg, #f8fafc 0%, #eff6ff 100%);
  border: 1px solid #93c5fd;
  border-left: 4px solid #1565c0;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
._eli3_bd_fn_label {
  font: 700 10px/1 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.6px;
  color: #1e3a8a;
}
._eli3_bd_fn_value {
  font: 600 15px/1.4 'Consolas', 'Monaco', monospace;
  color: #0f172a;
  background: #fff;
  padding: 12px 14px;
  border: 1px solid #cbd5e1;
  word-break: break-all;
  cursor: pointer;
  user-select: all;
  transition: border-color 0.12s, background 0.12s;
}
._eli3_bd_fn_value:hover {
  border-color: #1565c0;
  background: #fffbeb;
}
._eli3_bd_fn_copy {
  align-self: flex-start;
  padding: 10px 18px;
  font: 700 12px/1 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  background: linear-gradient(135deg, #1565c0 0%, #0d47a1 100%);
  color: #fff;
  border: 1px solid #0d47a1;
  cursor: pointer;
  transition: all 0.15s;
  box-shadow: 0 2px 6px rgba(21, 101, 192, 0.25);
}
._eli3_bd_fn_copy:hover {
  transform: translateY(-1px);
  box-shadow: 0 4px 12px rgba(21, 101, 192, 0.35);
}
._eli3_bd_fn_copy_ack {
  padding: 8px 10px;
  background: #d1fae5;
  border: 1px solid #6ee7b7;
  border-left: 3px solid #10b981;
  font-size: 11px;
  color: #065f46;
  line-height: 1.4;
}
._eli3_bd_fn_copy_ack kbd {
  display: inline-block;
  padding: 1px 6px;
  font: 700 10px/1.2 'Consolas', monospace;
  background: #fff;
  border: 1px solid #6ee7b7;
  border-radius: 3px;
  color: #065f46;
  margin: 0 1px;
}

/* Step-by-step instructions block */
._eli3_bd_fn_steps {
  margin: 8px 0 4px;
  padding: 12px 14px;
  background: #fffbeb;
  border: 1px solid #fcd34d;
  border-left: 3px solid #f59e0b;
}
._eli3_bd_fn_steps_head {
  font: 700 10px/1 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: #92400e;
  margin-bottom: 6px;
}
._eli3_bd_fn_steps_list {
  margin: 0;
  padding-left: 20px;
  font-size: 11px;
  line-height: 1.7;
  color: #0f172a;
}
._eli3_bd_fn_steps_list strong { color: #1e3a8a; }
._eli3_bd_fn_steps_list kbd {
  display: inline-block;
  padding: 1px 6px;
  font: 700 10px/1.2 'Consolas', monospace;
  background: #fff;
  border: 1px solid #cbd5e1;
  border-radius: 3px;
  color: #0f172a;
  margin: 0 1px;
}
._eli3_bd_fn_why {
  margin-top: 8px;
  padding-top: 6px;
  font-size: 10px;
  color: #92400e;
  font-style: italic;
  border-top: 1px dashed #fcd34d;
}

/* Guided mode toggle in the hub */
._eli3_bd_guided_toggle {
  display: flex; align-items: center; gap: 10px; padding: 10px 14px;
  margin: 10px 0 0; cursor: pointer; user-select: none;
  background: #f8fafc; border: 1px solid #e2e8f0; border-radius: 8px;
}
._eli3_bd_guided_toggle input { width: 16px; height: 16px; accent-color: #c9a227; flex: 0 0 auto; }
._eli3_bd_guided_toggle_text { font: 700 13px/1 Inter, sans-serif; color: #0f172a; }
._eli3_bd_guided_toggle_hint { font: 500 11px/1.3 Inter, sans-serif; color: #64748b; margin-left: auto; }

/* ─── Guided Mode (Step 1) ──────────────────────────────────────────── */
._eli3_bd_guided_root {
  display: flex; flex-direction: column; min-height: 0;
  background: #f1f5f9; font-family: Inter, "Segoe UI", system-ui, sans-serif;
  color: #0f172a; position: absolute; top: 0; left: 0; right: 0; bottom: 0; z-index: 10;
}
._eli3_bd_guided_header {
  background: linear-gradient(135deg, #0d1b2a 0%, #1b263b 100%);
  border-bottom: 3px solid #c9a227; padding: 18px 24px;
  display: flex; align-items: center; gap: 14px;
}
._eli3_bd_guided_back {
  background: none; border: none; color: #cbd5e1; font-size: 20px;
  cursor: pointer; padding: 4px 8px; border-radius: 6px;
}
._eli3_bd_guided_back:hover { background: rgba(255,255,255,.08); color: #fff; }
._eli3_bd_guided_eyebrow { font: 800 9px/1 Inter, sans-serif; letter-spacing: 1.4px; text-transform: uppercase; color: #d4af37; }
._eli3_bd_guided_title { font: 800 20px/1.15 "Book Antiqua", Georgia, serif; color: #fff; margin-top: 4px; }
._eli3_bd_guided_body { flex: 1 1 0; padding: 0; overflow: hidden; min-height: 0; }
._eli3_bd_guided_card {
  display: flex; gap: 0; height: 100%;
  background: #fff; overflow: hidden;
  animation: _eli3_bd_guided_fadein .2s ease-out;
}
@keyframes _eli3_bd_guided_fadein { 0% { opacity: 0; transform: translateX(12px); } 100% { opacity: 1; transform: translateX(0); } }
._eli3_bd_guided_left { flex: 3 1 0; display: flex; flex-direction: column; min-height: 0; overflow: hidden; }
._eli3_bd_guided_left_content { flex: 1 1 auto; overflow-y: auto; min-height: 0; padding: 28px 32px 12px; display: flex; flex-direction: column; gap: 16px; }
._eli3_bd_guided_nav { flex: 0 0 auto; padding: 12px 24px; margin: 0 24px 10px; border: 1px solid #cbd5e1; border-radius: 10px; background: linear-gradient(180deg, #fff, #f8fafc); box-shadow: 0 1px 3px rgba(15,23,42,.05); }
._eli3_bd_guided_progress_bar { flex: 0 0 auto; margin: 0 32px 16px; }
._eli3_bd_guided_qnum { font: 800 10px/1 Inter, sans-serif; letter-spacing: .1em; text-transform: uppercase; color: #c9a227; }
._eli3_bd_guided_qtitle { font: 800 22px/1.2 "Book Antiqua", Georgia, serif; color: #0f172a; }
._eli3_bd_guided_warning { font: 600 12px/1.4 Inter, sans-serif; color: #92400e; background: #fef3c7; border: 1px solid #f59e0b; border-radius: 8px; padding: 8px 12px; }
._eli3_bd_guided_btn_grid { display: flex; flex-direction: column; gap: 10px; }
._eli3_bd_guided_choice {
  display: block; width: 100%; text-align: left; padding: 14px 18px;
  font: 600 14px/1.4 Inter, sans-serif; color: #334155;
  background: linear-gradient(180deg, #fff 0%, #f8fafc 100%);
  border: 2px solid #e2e8f0; border-radius: 10px; cursor: pointer;
  transition: border-color .12s, background .12s, transform .05s;
}
._eli3_bd_guided_choice:hover { border-color: #cbd5e1; background: #f8fafc; }
._eli3_bd_guided_choice:active { transform: translateY(1px); }
._eli3_bd_guided_choice_on {
  border-color: #c9a227; background: linear-gradient(180deg, #fdf8e8 0%, #fbf3d6 100%);
  color: #6b5310; font-weight: 800; box-shadow: 0 0 0 3px rgba(201,162,39,.15);
}
._eli3_bd_guided_text_hint { font: 500 12px/1.4 Inter, sans-serif; color: #94a3b8; font-style: italic; }
._eli3_bd_guided_text_input {
  width: 100%; padding: 14px 16px; font: 400 14px/1.5 'Inter', system-ui, sans-serif;
  border: 2px solid #d4af37; border-radius: 10px; color: #0f172a;
  background: linear-gradient(180deg, #fff 0%, #fafbfc 100%);
  box-shadow: inset 0 1px 3px rgba(15,23,42,.04), 0 1px 2px rgba(201,162,39,.08);
  transition: border-color .2s, box-shadow .2s; box-sizing: border-box;
  min-height: 54px; resize: vertical;
}
._eli3_bd_guided_text_input:hover { border-color: #c9a227; box-shadow: inset 0 1px 3px rgba(15,23,42,.04), 0 0 0 3px rgba(201,162,39,.1); }
._eli3_bd_guided_text_input:focus { border-color: #c9a227; outline: none; box-shadow: inset 0 1px 3px rgba(15,23,42,.04), 0 0 0 4px rgba(201,162,39,.15); }
._eli3_bd_guided_nav { display: flex; gap: 10px; flex-wrap: wrap; margin-top: auto; padding-top: 12px; }
._eli3_bd_guided_nav_btn {
  font: 800 11px/1 Inter, sans-serif; letter-spacing: .04em; text-transform: uppercase;
  padding: 11px 18px; border-radius: 8px; border: 1px solid #cbd5e1; cursor: pointer;
  background: linear-gradient(180deg, #fff, #f1f5f9); color: #334155;
  transition: filter .15s, transform .05s;
}
._eli3_bd_guided_nav_btn:hover { filter: brightness(.97); }
._eli3_bd_guided_nav_btn:active { transform: translateY(1px); }
._eli3_bd_guided_nav_gen { background: linear-gradient(180deg, #d4af37, #c9a227); color: #0d1b2a; border-color: #b8941f; }
._eli3_bd_guided_nav_gen:hover { filter: brightness(1.05); }
._eli3_bd_guided_nav_next { background: #0d1b2a; color: #fff; border-color: #0d1b2a; }
._eli3_bd_guided_nav_next:hover { filter: brightness(1.2); }
._eli3_bd_guided_nav_startover { background: transparent; border-color: transparent; color: #94a3b8; font-weight: 600; font-size: 10px; margin-left: auto; }
._eli3_bd_guided_nav_startover:hover { color: #b3261e; }
._eli3_bd_guided_drag {
  flex: 0 0 6px; cursor: col-resize; background: linear-gradient(180deg, #c9a227, #d4af37);
  position: relative; z-index: 2;
  transition: background .15s;
}
._eli3_bd_guided_drag:hover { background: linear-gradient(180deg, #b8941f, #c9a227); }
._eli3_bd_guided_drag::after {
  content: ""; position: absolute; top: 50%; left: 1px;
  width: 4px; height: 28px; transform: translateY(-50%);
  border-left: 1px solid rgba(255,255,255,.5); border-right: 1px solid rgba(255,255,255,.5);
}
._eli3_bd_guided_right {
  flex: 2 1 0; background: #f8fafc;
  border-bottom: 3px solid #c9a227;
  display: flex; flex-direction: column; min-height: 0; overflow: hidden;
}
._eli3_bd_guided_right_body {
  flex: 1 1 auto; overflow-y: auto; min-height: 0; padding: 12px 18px;
}
._eli3_bd_guided_col_header {
  display: flex; align-items: center; gap: 8px; padding: 10px 14px;
  background: linear-gradient(135deg, #0d1b2a 0%, #1b263b 100%);
  border-bottom: 2px solid #c9a227; border-radius: 8px 8px 0 0;
  /* Header is a direct child of _guided_right (not inside _right_body),
     so no negative margins needed — it naturally spans the column width. */
}
._eli3_bd_guided_col_icon { font-size: 16px; }
._eli3_bd_guided_col_viewall {
  margin-left: auto; padding: 4px 10px; font: 700 9px/1 Inter, sans-serif;
  letter-spacing: .05em; text-transform: uppercase;
  background: rgba(255,255,255,.12); color: #d4af37; border: 1px solid rgba(201,162,39,.4);
  border-radius: 5px; cursor: pointer;
}
._eli3_bd_guided_col_viewall:hover { background: rgba(255,255,255,.2); }
._eli3_bd_guided_col_header span:nth-child(2) {
  font: 800 12px/1 Inter, sans-serif; letter-spacing: .14em;
  text-transform: uppercase; color: #d4af37; flex: 1 1 auto;
}
._eli3_bd_guided_ctx_header { font: 800 10px/1 Inter, sans-serif; letter-spacing: .12em; text-transform: uppercase; color: #64748b; }
._eli3_bd_guided_ctx_body { font: 500 13px/1.6 Inter, sans-serif; color: #334155; }
._eli3_bd_guided_ctx_term { font: 700 15px/1.3 Inter, sans-serif; color: #0f172a; margin-bottom: 8px; }
._eli3_bd_guided_ctx_open {
  margin-top: 8px; padding: 8px 14px; font: 700 11px/1 Inter, sans-serif;
  background: linear-gradient(180deg, #d4af37, #c9a227); color: #0d1b2a;
  border: none; border-radius: 7px; cursor: pointer;
}
._eli3_bd_guided_ctx_open:hover { filter: brightness(1.05); }
._eli3_bd_guided_ctx_guidance { white-space: pre-wrap; }
._eli3_bd_guided_ctx_list { margin: 0; padding-left: 20px; }
._eli3_bd_guided_ctx_list li { margin-bottom: 6px; }
._eli3_bd_guided_ctx_empty { color: #94a3b8; font-style: italic; }
/* Premium guidance card */
._eli3_bd_guided_guidance_card {
  background: linear-gradient(135deg, #fffbeb 0%, #fef3c7 100%);
  border: 1px solid #f59e0b; border-left: 4px solid #c9a227;
  border-radius: 10px; padding: 20px; display: flex; gap: 14px;
  align-items: flex-start; margin-top: 4px;
}
._eli3_bd_guided_guidance_icon { font-size: 28px; flex: 0 0 auto; line-height: 1; }
._eli3_bd_guided_guidance_text {
  font: 500 14px/1.65 "Book Antiqua", Georgia, serif; color: #6b5310;
  white-space: pre-wrap;
}
/* Inline OARS fields grid */
._eli3_bd_guided_oars_grid { display: flex; flex-direction: column; gap: 1px; background: #eef2f7; border: 1px solid #eef2f7; border-radius: 8px; overflow: hidden; max-height: 100%; overflow-y: auto; }
._eli3_bd_guided_oars_row { display: flex; gap: 8px; padding: 6px 10px; background: #fff; font-size: 12px; }
._eli3_bd_guided_oars_hit { background: #fef9e7; }
._eli3_bd_guided_oars_k { flex: 0 0 40%; font-weight: 700; color: #475569; word-break: break-word; }
._eli3_bd_guided_oars_v { flex: 1 1 auto; color: #0f172a; word-break: break-word; }
/* Ask ELI button below guidance */
._eli3_bd_guided_ask_eli_btn {
  display: inline-flex; align-items: center; gap: 6px; margin: 12px 0 4px;
  padding: 8px 18px; border: 1px solid #c9a227; border-radius: 8px;
  background: linear-gradient(135deg, #fefce8, #fef9c3); color: #92400e;
  font: 600 12px/1 Inter, sans-serif; cursor: pointer;
  transition: filter .15s, box-shadow .15s;
}
._eli3_bd_guided_ask_eli_btn:hover { filter: brightness(.96); box-shadow: 0 2px 6px rgba(201,162,39,.25); }
/* Full OARS tables (View All) */
._eli3_bd_guided_oars_tbl { width: 100%; border-collapse: collapse; font-size: 11px; margin-bottom: 12px; table-layout: fixed; }
._eli3_bd_guided_oars_tbl_th { background: linear-gradient(180deg, #e0f2fe, #bae6fd); color: #0c4a6e; font: 700 11px/1.3 Inter, sans-serif; padding: 6px 8px; text-align: left; border-bottom: 2px solid #38bdf8; }
._eli3_bd_guided_oars_tbl_td { padding: 5px 8px; border-bottom: 1px solid #eef2f7; color: #1e293b; font-size: 11px; vertical-align: top; word-break: break-word; }
._eli3_bd_guided_oars_tbl tbody tr:nth-child(even) td { background: #f8fafc; }
._eli3_bd_guided_oars_tbl tbody tr:hover td { background: #eef2f7; }
._eli3_bd_guided_oars_tbl_empty { color: #cbd5e1; }
._eli3_bd_guided_progress_bar {
  position: relative; height: 28px; background: #e2e8f0; flex: 0 0 auto;
  border-radius: 6px; margin-top: auto; overflow: hidden;
}
._eli3_bd_guided_progress_fill {
  position: absolute; top: 0; left: 0; height: 100%; width: 0;
  background: linear-gradient(90deg, #c9a227, #d4af37);
  transition: width .3s ease-out;
}
._eli3_bd_guided_progress_label {
  position: absolute; top: 0; left: 0; right: 0; height: 100%;
  display: flex; align-items: center; justify-content: center;
  font: 700 11px/1 Inter, sans-serif; color: #0f172a; letter-spacing: .03em; z-index: 1;
}
@media (max-width: 550px) {
  ._eli3_bd_guided_card { flex-direction: column; }
  ._eli3_bd_guided_right { border-top: 1px solid #eef2f7; }
  ._eli3_bd_guided_drag { flex: 0 0 6px; cursor: row-resize; }
  ._eli3_bd_guided_drag::after { width: 28px; height: 4px; left: 50%; top: 1px; transform: translateX(-50%); border-left: none; border-right: none; border-top: 1px solid rgba(255,255,255,.5); border-bottom: 1px solid rgba(255,255,255,.5); }
}

/* Dark mode */
